fn transport_ingestion_state_index_is_concrete(index: &str) -> bool {
    let trimmed = index.trim();
    !trimmed.is_empty()
        && trimmed == index
        && !trimmed.contains('*')
        && !trimmed.contains('?')
        && !trimmed.contains(',')
        && !trimmed.starts_with('<')
        && !trimmed.contains(':')
}

