fn get_pipeline_response_from_metadata_manifest(
    metadata_manifest: &Value,
    request: &os_transport::action::OpenSearchGetPipelineRequestWire,
) -> os_transport::action::OpenSearchGetPipelineResponseWire {
    let Some(pipelines) = metadata_manifest
        .get("ingest_pipelines")
        .and_then(Value::as_object)
    else {
        return os_transport::action::OpenSearchGetPipelineResponseWire {
            pipelines: Vec::new(),
        };
    };
    let mut response_pipelines = Vec::new();
    if request.ids.is_empty() {
        for (id, pipeline) in pipelines {
            if let Some(configuration) = ingest_pipeline_configuration_from_json(id, pipeline) {
                response_pipelines.push(configuration);
            }
        }
    } else {
        let mut seen = BTreeSet::new();
        for pattern in &request.ids {
            if is_simple_wildcard_pattern(pattern) {
                for (id, pipeline) in pipelines {
                    if wildcard_match(pattern, id) && seen.insert(id.clone()) {
                        if let Some(configuration) =
                            ingest_pipeline_configuration_from_json(id, pipeline)
                        {
                            response_pipelines.push(configuration);
                        }
                    }
                }
            } else if let Some(pipeline) = pipelines.get(pattern) {
                if seen.insert(pattern.clone()) {
                    if let Some(configuration) =
                        ingest_pipeline_configuration_from_json(pattern, pipeline)
                    {
                        response_pipelines.push(configuration);
                    }
                }
            }
        }
    }
    os_transport::action::OpenSearchGetPipelineResponseWire {
        pipelines: response_pipelines,
    }
}

fn put_ingest_pipeline_into_metadata_manifest(
    metadata_manifest: &mut Value,
    request: &os_transport::action::OpenSearchPutPipelineRequestWire,
) -> bool {
    let Ok(source) = serde_json::from_slice::<Value>(&request.source) else {
        return false;
    };
    if !metadata_manifest.is_object() {
        *metadata_manifest = serde_json::json!({});
    }
    let Some(root) = metadata_manifest.as_object_mut() else {
        return false;
    };
    let pipelines = root
        .entry("ingest_pipelines".to_string())
        .or_insert_with(|| serde_json::json!({}));
    if !pipelines.is_object() {
        *pipelines = serde_json::json!({});
    }
    let Some(pipelines) = pipelines.as_object_mut() else {
        return false;
    };
    pipelines.insert(request.id.clone(), source);
    true
}

fn simulate_pipeline_request_supports_empty_doc_subset(
    metadata_manifest: &Value,
    request: &os_transport::action::OpenSearchSimulatePipelineRequestWire,
) -> bool {
    if request.validate_supported_execution_subset().is_err() {
        return false;
    }
    let Ok(source) = serde_json::from_slice::<Value>(&request.source) else {
        return false;
    };
    let Some(docs) = source.get("docs").and_then(Value::as_array) else {
        return false;
    };
    if !docs.is_empty() {
        return false;
    }
    match &request.id {
        Some(id) => metadata_manifest
            .get("ingest_pipelines")
            .and_then(Value::as_object)
            .is_some_and(|pipelines| pipelines.contains_key(id)),
        None => source.get("pipeline").and_then(Value::as_object).is_some(),
    }
}

fn delete_ingest_pipeline_request_matches_manifest_subset(
    metadata_manifest: &Value,
    pipeline_id: &str,
) -> bool {
    let Some(pipelines) = metadata_manifest
        .get("ingest_pipelines")
        .and_then(Value::as_object)
    else {
        return pipeline_id == "*" || pipeline_id == "_all";
    };
    if pipelines.keys().any(|id| wildcard_match(pipeline_id, id)) {
        return true;
    }
    pipeline_id == "*" || pipeline_id == "_all"
}

fn delete_ingest_pipeline_from_metadata_manifest(
    metadata_manifest: &mut Value,
    pipeline_id: &str,
) -> bool {
    let Some(pipelines) = metadata_manifest
        .get_mut("ingest_pipelines")
        .and_then(Value::as_object_mut)
    else {
        return pipeline_id == "*" || pipeline_id == "_all";
    };
    let to_remove = pipelines
        .keys()
        .filter(|id| wildcard_match(pipeline_id, id))
        .cloned()
        .collect::<Vec<_>>();
    if to_remove.is_empty() {
        return pipeline_id == "*" || pipeline_id == "_all";
    }
    for id in to_remove {
        pipelines.remove(&id);
    }
    true
}

fn selected_pipeline_entries<'a>(
    pipelines: &'a serde_json::Map<String, Value>,
    ids: &[String],
) -> Vec<(String, &'a Value)> {
    let mut selected = Vec::new();
    if ids.is_empty() {
        for (id, pipeline) in pipelines {
            selected.push((id.clone(), pipeline));
        }
        return selected;
    }
    let mut seen = BTreeSet::new();
    for pattern in ids {
        if is_simple_wildcard_pattern(pattern) {
            for (id, pipeline) in pipelines {
                if wildcard_match(pattern, id) && seen.insert(id.clone()) {
                    selected.push((id.clone(), pipeline));
                }
            }
        } else if let Some(pipeline) = pipelines.get(pattern) {
            if seen.insert(pattern.clone()) {
                selected.push((pattern.clone(), pipeline));
            }
        }
    }
    selected
}

