fn put_weighted_routing_into_metadata_manifest(
    metadata_manifest: &mut Value,
    request: &os_transport::action::ClusterPutWeightedRoutingRequestWire,
) -> bool {
    if !metadata_manifest.is_object() {
        *metadata_manifest = serde_json::json!({});
    }
    let Some(root) = metadata_manifest.as_object_mut() else {
        return false;
    };
    let cluster_admin_state = root
        .entry("cluster_admin_state")
        .or_insert_with(|| serde_json::json!({}));
    if !cluster_admin_state.is_object() {
        *cluster_admin_state = serde_json::json!({});
    }
    let Some(cluster_admin_state) = cluster_admin_state.as_object_mut() else {
        return false;
    };
    cluster_admin_state.insert(
        "weighted_routing_version".to_string(),
        serde_json::json!(request.version + 1),
    );
    let weighted_routing = cluster_admin_state
        .entry("weighted_routing")
        .or_insert_with(|| serde_json::json!({}));
    if !weighted_routing.is_object() {
        *weighted_routing = serde_json::json!({});
    }
    let Some(weighted_routing) = weighted_routing.as_object_mut() else {
        return false;
    };
    weighted_routing.insert(
        request.attribute_name.clone(),
        serde_json::json!({
            "weights": &request.weights,
            "discovered_cluster_manager": true
        }),
    );
    true
}

fn delete_weighted_routing_from_metadata_manifest(
    metadata_manifest: &mut Value,
    request: &os_transport::action::ClusterDeleteWeightedRoutingRequestWire,
) -> bool {
    let Some(attribute) = request.awareness_attribute.as_deref() else {
        return false;
    };
    let Some(weighted_routing) = metadata_manifest
        .pointer_mut("/cluster_admin_state/weighted_routing")
        .and_then(Value::as_object_mut)
    else {
        return false;
    };
    if weighted_routing.remove(attribute).is_none() {
        return false;
    }
    let Some(cluster_admin_state) = metadata_manifest
        .pointer_mut("/cluster_admin_state")
        .and_then(Value::as_object_mut)
    else {
        return false;
    };
    cluster_admin_state.insert(
        "weighted_routing_version".to_string(),
        serde_json::json!(request.version + 1),
    );
    true
}

fn get_weighted_routing_response_from_metadata_manifest(
    metadata_manifest: &Value,
    awareness_attribute: &str,
) -> os_transport::action::ClusterGetWeightedRoutingResponseWire {
    let Some(state) = metadata_manifest
        .pointer("/cluster_admin_state/weighted_routing")
        .and_then(|weighted_routing| weighted_routing.get(awareness_attribute))
    else {
        return os_transport::action::ClusterGetWeightedRoutingResponseWire::empty();
    };
    let weights = state
        .get("weights")
        .and_then(Value::as_object)
        .map(|weights| {
            weights
                .iter()
                .filter_map(|(zone, weight)| {
                    let value = weight.as_f64()?;
                    value.is_finite().then(|| (zone.clone(), value))
                })
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    if weights.is_empty() {
        return os_transport::action::ClusterGetWeightedRoutingResponseWire::empty();
    }
    let version = metadata_manifest
        .pointer("/cluster_admin_state/weighted_routing_version")
        .and_then(Value::as_i64)
        .unwrap_or(-1);
    let discovered_cluster_manager = state
        .get("discovered_cluster_manager")
        .and_then(Value::as_bool)
        .unwrap_or(true);
    os_transport::action::ClusterGetWeightedRoutingResponseWire::weighted(
        awareness_attribute,
        weights,
        version,
        Some(discovered_cluster_manager),
    )
}

fn is_simple_wildcard_pattern(pattern: &str) -> bool {
    pattern.contains('*') || pattern.contains('?')
}

