fn get_component_template_response_from_metadata_manifest(
    metadata_manifest: &Value,
) -> os_transport::action::OpenSearchGetComponentTemplateResponseWire {
    let mut response = os_transport::action::OpenSearchGetComponentTemplateResponseWire::empty();
    let Some(templates) = metadata_manifest.pointer("/templates/component_templates") else {
        return response;
    };
    let Some(object) = templates.as_object() else {
        return response;
    };
    for (name, template_entry) in object {
        if let Some(component_template) = component_template_wire_from_manifest(template_entry) {
            response
                .component_templates
                .insert(name.clone(), component_template);
        }
    }
    response
}

fn component_template_wire_from_manifest(
    template_entry: &Value,
) -> Option<os_transport::action::OpenSearchComponentTemplateWire> {
    let component_template = template_entry
        .get("component_template")
        .unwrap_or(template_entry);
    if component_template
        .get("_meta")
        .or_else(|| component_template.get("metadata"))
        .filter(|value| !value.is_null())
        .is_some()
    {
        return None;
    }
    let template = component_template
        .get("template")
        .unwrap_or(component_template);
    if template
        .get("mappings")
        .filter(|value| !value.is_null())
        .is_some()
        || template
            .get("aliases")
            .filter(|value| !value.is_null())
            .is_some()
    {
        return None;
    }
    let mut settings = BTreeMap::new();
    flatten_string_settings(
        None,
        template.get("settings").unwrap_or(&Value::Null),
        &mut settings,
    );
    Some(os_transport::action::OpenSearchComponentTemplateWire {
        template: os_transport::action::OpenSearchTemplateWire {
            settings,
            mappings: None,
            aliases_count: 0,
        },
        version: component_template.get("version").and_then(Value::as_i64),
        metadata_count: 0,
    })
}

