fn simulate_index_template_request_matches_no_match_subset(
    request: &os_transport::action::OpenSearchSimulateIndexTemplateRequestWire,
) -> bool {
    request.validate_supported_no_match_subset().is_ok()
        && !manifest_composable_index_template_matches(&request.index_name)
}

fn simulate_template_request_matches_missing_named_template_subset(
    request: &os_transport::action::OpenSearchSimulateTemplateRequestWire,
) -> bool {
    request.cluster_manager_timeout == os_transport::action::TimeValueWire::seconds(30)
        && !request.local
        && request.index_template_request.is_none()
        && request
            .template_name
            .as_deref()
            .is_some_and(|template_name| {
                !template_name.trim().is_empty()
                    && !manifest_composable_index_template_exists(template_name)
            })
}

fn manifest_composable_index_template_exists(template_name: &str) -> bool {
    let manifest = dev_transport_pit_bindings()
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    manifest
        .pointer("/templates/index_templates")
        .and_then(Value::as_object)
        .is_some_and(|templates| templates.contains_key(template_name))
}

fn manifest_composable_index_template_matches(index_name: &str) -> bool {
    let manifest = dev_transport_pit_bindings()
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let Some(templates) = manifest
        .pointer("/templates/index_templates")
        .and_then(Value::as_object)
    else {
        return false;
    };
    templates.values().any(|template_entry| {
        let index_template = template_entry
            .get("index_template")
            .unwrap_or(template_entry);
        index_template
            .get("index_patterns")
            .or_else(|| index_template.get("indexPatterns"))
            .and_then(Value::as_array)
            .is_some_and(|patterns| {
                patterns
                    .iter()
                    .filter_map(Value::as_str)
                    .any(|pattern| wildcard_match(pattern, index_name))
            })
    })
}

fn get_composable_index_template_response_from_metadata_manifest(
    metadata_manifest: &Value,
) -> os_transport::action::OpenSearchGetComposableIndexTemplateResponseWire {
    let mut response =
        os_transport::action::OpenSearchGetComposableIndexTemplateResponseWire::empty();
    let Some(templates) = metadata_manifest.pointer("/templates/index_templates") else {
        return response;
    };
    let Some(object) = templates.as_object() else {
        return response;
    };
    for (name, template_entry) in object {
        if let Some(index_template) = composable_index_template_wire_from_manifest(template_entry) {
            response
                .index_templates
                .insert(name.clone(), index_template);
        }
    }
    response
}

fn composable_index_template_wire_from_manifest(
    template_entry: &Value,
) -> Option<os_transport::action::OpenSearchComposableIndexTemplateWire> {
    let index_template = template_entry
        .get("index_template")
        .unwrap_or(template_entry);
    if index_template
        .get("_meta")
        .or_else(|| index_template.get("metadata"))
        .filter(|value| !value.is_null())
        .is_some()
        || index_template
            .get("data_stream")
            .filter(|value| !value.is_null())
            .is_some()
        || index_template
            .get("context")
            .filter(|value| !value.is_null())
            .is_some()
    {
        return None;
    }
    let index_patterns = index_template
        .get("index_patterns")
        .or_else(|| index_template.get("indexPatterns"))
        .and_then(Value::as_array)?
        .iter()
        .map(Value::as_str)
        .collect::<Option<Vec<_>>>()?
        .into_iter()
        .map(str::to_string)
        .collect::<Vec<_>>();
    if index_patterns.is_empty()
        || index_patterns
            .iter()
            .any(|pattern| pattern.trim().is_empty())
    {
        return None;
    }
    let template = index_template
        .get("template")
        .and_then(template_wire_from_manifest);
    let composed_of = index_template
        .get("composed_of")
        .or_else(|| index_template.get("composedOf"))
        .and_then(Value::as_array)
        .map(|values| {
            values
                .iter()
                .map(Value::as_str)
                .collect::<Option<Vec<_>>>()
                .map(|values| values.into_iter().map(str::to_string).collect::<Vec<_>>())
        })
        .unwrap_or(Some(Vec::new()))?;
    Some(
        os_transport::action::OpenSearchComposableIndexTemplateWire {
            index_patterns,
            template,
            composed_of: Some(composed_of),
            priority: index_template.get("priority").and_then(Value::as_i64),
            version: index_template.get("version").and_then(Value::as_i64),
            metadata_count: 0,
            data_stream_template_present: false,
            context_present: false,
        },
    )
}

fn template_wire_from_manifest(
    template: &Value,
) -> Option<os_transport::action::OpenSearchTemplateWire> {
    if template
        .get("mappings")
        .filter(|value| !value.is_null())
        .is_some()
        || template
            .get("aliases")
            .filter(|value| !value.is_null())
            .is_some()
    {
        return None;
    }
    let mut settings = BTreeMap::new();
    flatten_string_settings(
        None,
        template.get("settings").unwrap_or(&Value::Null),
        &mut settings,
    );
    Some(os_transport::action::OpenSearchTemplateWire {
        settings,
        mappings: None,
        aliases_count: 0,
    })
}

fn legacy_template_entries(metadata_manifest: &Value) -> Vec<(String, &Value)> {
    let mut entries = Vec::new();
    let candidate_maps = [
        metadata_manifest.pointer("/templates/legacy_index_templates"),
        metadata_manifest.pointer("/metadata/templates"),
        metadata_manifest.get("templates"),
        metadata_manifest.get("index_templates"),
        metadata_manifest.get("legacy_templates"),
    ];
    for candidate in candidate_maps.into_iter().flatten() {
        if let Some(object) = candidate.as_object() {
            for (name, template) in object {
                if matches!(
                    name.as_str(),
                    "legacy_index_templates" | "component_templates" | "index_templates"
                ) {
                    continue;
                }
                entries.push((name.clone(), template));
            }
        } else if let Some(array) = candidate.as_array() {
            for template in array {
                if let Some(name) = template.get("name").and_then(Value::as_str) {
                    entries.push((name.to_string(), template));
                }
            }
        }
    }
    entries
}

fn index_template_metadata_wire_from_manifest(
    name: &str,
    template: &Value,
) -> os_transport::action::OpenSearchIndexTemplateMetadataWire {
    let mut wire = os_transport::action::OpenSearchIndexTemplateMetadataWire::new(name);
    wire.order = template
        .get("order")
        .and_then(Value::as_i64)
        .and_then(|order| i32::try_from(order).ok())
        .unwrap_or(0);
    wire.index_patterns = template_string_array(template, "index_patterns")
        .or_else(|| template_string_array(template, "patterns"))
        .unwrap_or_default();
    flatten_json_settings_value(
        template.get("settings").unwrap_or(&Value::Null),
        &mut wire.settings,
    );
    if let Some(mappings) = template.get("mappings").filter(|value| !value.is_null()) {
        if let Some(object) = mappings.as_object() {
            if object.contains_key("_doc") {
                if let Some(mapping) = object.get("_doc") {
                    wire.mappings.insert("_doc".to_string(), mapping.clone());
                }
            } else {
                wire.mappings.insert("_doc".to_string(), mappings.clone());
            }
        } else {
            wire.mappings.insert("_doc".to_string(), mappings.clone());
        }
    }
    if let Some(aliases) = template.get("aliases").and_then(Value::as_object) {
        wire.aliases = aliases
            .iter()
            .map(|(alias, metadata)| alias_metadata_wire_from_manifest(alias, metadata))
            .collect();
    }
    wire.version = template
        .get("version")
        .and_then(Value::as_i64)
        .and_then(|version| i32::try_from(version).ok());
    wire
}

fn template_string_array(template: &Value, field: &str) -> Option<Vec<String>> {
    let values = template.get(field)?.as_array()?;
    Some(
        values
            .iter()
            .filter_map(Value::as_str)
            .map(str::to_string)
            .collect(),
    )
}

fn build_get_mappings_response(request_id: i64, header_version_id: u32, body: &[u8]) -> Vec<u8> {
    let request = decode_get_mappings_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .unwrap_or_default();
    let response = get_mappings_response_from_metadata_manifest(
        &dev_transport_pit_bindings()
            .metadata_manifest
            .lock()
            .expect("metadata manifest lock poisoned"),
        &request,
    );
    os_transport::action::build_opensearch_get_mappings_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

