fn transport_create_index_name_is_valid(index: &str) -> bool {
    let trimmed = index.trim();
    !trimmed.is_empty()
        && trimmed == index
        && !trimmed.starts_with('_')
        && !trimmed.starts_with('-')
        && !trimmed.starts_with('+')
        && !trimmed.contains(',')
        && !trimmed.chars().any(|ch| ch.is_ascii_uppercase())
}

fn transport_delete_index_name_is_concrete(index: &str) -> bool {
    let trimmed = index.trim();
    !trimmed.is_empty()
        && trimmed == index
        && !trimmed.contains('*')
        && !trimmed.contains('?')
        && !trimmed.contains(',')
        && !trimmed.starts_with('<')
        && !trimmed.contains(':')
}

fn transport_index_exists(index: &str) -> bool {
    let bindings = dev_transport_pit_bindings();
    if bindings
        .created_indices
        .lock()
        .expect("dev transport created indices lock poisoned")
        .contains(index)
    {
        return true;
    }
    bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned")["indices"]
        .as_object()
        .is_some_and(|indices| indices.contains_key(index))
}

fn insert_transport_created_index(
    request: &os_transport::action::OpenSearchCreateIndexRequestWire,
) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    if !manifest.is_object() {
        *manifest = serde_json::json!({});
    }
    if manifest.get("indices").and_then(Value::as_object).is_none() {
        manifest["indices"] = serde_json::json!({});
    }
    let Some(indices) = manifest["indices"].as_object_mut() else {
        return false;
    };
    if indices.contains_key(&request.index) {
        return false;
    }
    let mappings =
        serde_json::from_str::<Value>(&request.mappings).unwrap_or_else(|_| serde_json::json!({}));
    indices.insert(
        request.index.clone(),
        serde_json::json!({
            "settings": request.settings,
            "mappings": mappings,
            "aliases": {},
            "state": "open"
        }),
    );
    drop(manifest);
    bindings
        .created_indices
        .lock()
        .expect("dev transport created indices lock poisoned")
        .insert(request.index.clone());
    bindings
        .documents
        .lock()
        .expect("dev transport documents lock poisoned")
        .retain(|key, _| !key.starts_with(&format!("{}:", request.index)));
    true
}

fn apply_transport_delete_index(indices: &[String]) {
    let bindings = dev_transport_pit_bindings();
    {
        let mut manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        if let Some(indices_object) = manifest["indices"].as_object_mut() {
            for index in indices {
                indices_object.remove(index);
            }
        }
    }
    {
        let mut created_indices = bindings
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned");
        for index in indices {
            created_indices.remove(index);
        }
    }
    bindings
        .documents
        .lock()
        .expect("dev transport documents lock poisoned")
        .retain(|key, _| {
            !indices
                .iter()
                .any(|index| key.starts_with(&format!("{index}:")))
        });
}

fn apply_transport_open_index(indices: &[String]) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let Some(indices_object) = manifest["indices"].as_object_mut() else {
        return false;
    };
    if !indices
        .iter()
        .all(|index| indices_object.contains_key(index))
    {
        return false;
    }
    for index in indices {
        if let Some(entry) = indices_object.get_mut(index) {
            entry["state"] = serde_json::json!("open");
        }
    }
    true
}

fn apply_transport_close_index(indices: &[String]) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let Some(indices_object) = manifest["indices"].as_object_mut() else {
        return false;
    };
    if !indices
        .iter()
        .all(|index| indices_object.contains_key(index))
    {
        return false;
    }
    for index in indices {
        if let Some(entry) = indices_object.get_mut(index) {
            entry["state"] = serde_json::json!("close");
        }
    }
    true
}

fn apply_transport_add_index_block(indices: &[String], block: i32) -> bool {
    let Some(setting_key) = transport_add_index_block_setting_key(block) else {
        return false;
    };
    let bindings = dev_transport_pit_bindings();
    let mut manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let Some(indices_object) = manifest["indices"].as_object_mut() else {
        return false;
    };
    if !indices
        .iter()
        .all(|index| indices_object.contains_key(index))
    {
        return false;
    }
    for index in indices {
        let Some(entry) = indices_object.get_mut(index) else {
            return false;
        };
        if !entry.is_object() {
            return false;
        }
        if entry.get("settings").and_then(Value::as_object).is_none() {
            entry["settings"] = serde_json::json!({});
        }
        set_manifest_index_setting_bool(&mut entry["settings"], setting_key, true);
    }
    true
}

fn apply_transport_scale_index(index: &str) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let Some(entry) = manifest["indices"].get_mut(index) else {
        return false;
    };
    if !entry.is_object() {
        return false;
    }
    if entry.get("settings").and_then(Value::as_object).is_none() {
        entry["settings"] = serde_json::json!({});
    }
    set_manifest_index_setting_bool(&mut entry["settings"], "index.blocks.search_only", true);
    true
}

fn transport_add_index_block_setting_key(block: i32) -> Option<&'static str> {
    match block {
        0 => Some("index.blocks.read_only"),
        1 => Some("index.blocks.read"),
        2 => Some("index.blocks.write"),
        3 => Some("index.blocks.metadata"),
        5 => Some("index.blocks.search_only"),
        _ => None,
    }
}

fn set_manifest_index_setting_bool(settings: &mut Value, key: &str, value: bool) {
    if !settings.is_object() {
        *settings = serde_json::json!({});
    }
    settings[key] = Value::Bool(value);
    let parts: Vec<&str> = key.split('.').collect();
    set_nested_manifest_setting_bool(settings, &parts, value);
}

fn set_nested_manifest_setting_bool(settings: &mut Value, parts: &[&str], value: bool) {
    if parts.is_empty() {
        *settings = Value::Bool(value);
        return;
    }
    if parts.len() == 1 {
        settings[parts[0]] = Value::Bool(value);
        return;
    }
    if !settings.is_object() {
        *settings = serde_json::json!({});
    }
    if settings.get(parts[0]).and_then(Value::as_object).is_none() {
        settings[parts[0]] = serde_json::json!({});
    }
    set_nested_manifest_setting_bool(&mut settings[parts[0]], &parts[1..], value);
}

fn transport_analyze_tokens(
    texts: &[String],
) -> Vec<os_transport::action::OpenSearchAnalyzeTokenWire> {
    let text = texts.join(" ");
    let mut offset = 0usize;
    transport_tokenize_search_text(&text)
        .into_iter()
        .enumerate()
        .map(|(position, token)| {
            let start_offset = text[offset..]
                .to_ascii_lowercase()
                .find(&token)
                .map(|delta| offset + delta)
                .unwrap_or(offset);
            let end_offset = start_offset + token.len();
            offset = end_offset;
            os_transport::action::OpenSearchAnalyzeTokenWire {
                term: token,
                start_offset: start_offset as i32,
                end_offset: end_offset as i32,
                position: position as i32,
                position_length: 1,
                token_type: Some("word".to_string()),
            }
        })
        .collect()
}

fn transport_tokenize_search_text(input: &str) -> Vec<String> {
    input
        .split(|character: char| !character.is_ascii_alphanumeric())
        .map(|token| token.to_ascii_lowercase())
        .filter(|token| !token.is_empty())
        .collect()
}

fn get_field_mappings_response_from_metadata_manifest(
    metadata_manifest: &Value,
    request: &os_transport::action::OpenSearchGetFieldMappingsRequestWire,
) -> os_transport::action::OpenSearchGetFieldMappingsResponseWire {
    if request.validate_supported_subset().is_err() {
        return os_transport::action::OpenSearchGetFieldMappingsResponseWire::empty();
    }
    let Some(indices) = metadata_manifest["indices"].as_object() else {
        return os_transport::action::OpenSearchGetFieldMappingsResponseWire::empty();
    };
    let empty_field_mapping_indices = indices
        .iter()
        .filter_map(|(index, entry)| {
            let properties_empty = entry
                .get("mappings")
                .and_then(|mappings| mappings.get("properties"))
                .and_then(Value::as_object)
                .map_or(true, |properties| properties.is_empty());
            if properties_empty {
                Some(index.clone())
            } else {
                None
            }
        })
        .collect();
    os_transport::action::OpenSearchGetFieldMappingsResponseWire {
        empty_field_mapping_indices,
    }
}

