fn delete_stored_script_from_metadata_manifest(
    metadata_manifest: &mut Value,
    script_id: &str,
) -> bool {
    metadata_manifest
        .get_mut("stored_scripts")
        .and_then(Value::as_object_mut)
        .and_then(|scripts| scripts.remove(script_id))
        .is_some()
}

fn put_stored_script_into_metadata_manifest(
    metadata_manifest: &mut Value,
    request: &os_transport::action::OpenSearchPutStoredScriptRequestWire,
) {
    let script_id = request
        .id
        .as_deref()
        .expect("validated put stored script request has id");
    let object = metadata_manifest
        .as_object_mut()
        .expect("metadata manifest should be object");
    let stored_scripts = object
        .entry("stored_scripts".to_string())
        .or_insert_with(|| Value::Object(serde_json::Map::new()));
    stored_scripts
        .as_object_mut()
        .expect("stored_scripts manifest entry should be object")
        .insert(
            script_id.to_string(),
            serde_json::json!({
                "lang": request.source.lang.clone(),
                "source": request.source.source.clone(),
                "options": request.source.options.clone(),
            }),
        );
}

fn get_stored_script_response_from_metadata_manifest(
    metadata_manifest: &Value,
    script_id: &str,
) -> os_transport::action::OpenSearchGetStoredScriptResponseWire {
    let Some(script) = metadata_manifest
        .get("stored_scripts")
        .and_then(|scripts| scripts.get(script_id))
    else {
        return os_transport::action::OpenSearchGetStoredScriptResponseWire::not_found(script_id);
    };
    let lang = script
        .get("lang")
        .and_then(Value::as_str)
        .unwrap_or("painless")
        .to_string();
    let source = script
        .get("source")
        .map(|source| {
            source
                .as_str()
                .map(ToString::to_string)
                .unwrap_or_else(|| source.to_string())
        })
        .unwrap_or_default();
    let options = script
        .get("options")
        .and_then(Value::as_object)
        .map(|options| {
            options
                .iter()
                .filter_map(|(name, value)| {
                    value
                        .as_str()
                        .map(|value| (name.clone(), value.to_string()))
                })
                .collect::<BTreeMap<_, _>>()
        })
        .unwrap_or_default();
    os_transport::action::OpenSearchGetStoredScriptResponseWire::found(
        script_id,
        os_transport::action::OpenSearchStoredScriptSourceWire {
            lang,
            source,
            options,
        },
    )
}

