fn build_get_tiering_status_no_active_migration_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_get_tiering_status_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let reason = format!("Index [{}] has no active migrations", request.index);
    let mut output = StreamOutput::new();
    os_transport::error::write_illegal_argument_exception(&mut output, Some(&reason));
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn get_tiering_status_request_supports_no_active_migration_subset(body: &[u8]) -> bool {
    decode_get_tiering_status_request_from_transport_body(body).is_some_and(|request| {
        get_tiering_status_request_matches_no_active_migration_subset(&request)
    })
}

fn decode_get_tiering_status_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::GetTieringStatusRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_get_tiering_status_request_message(&message).ok()
}

fn get_tiering_status_request_matches_no_active_migration_subset(
    request: &os_transport::action::GetTieringStatusRequestWire,
) -> bool {
    request.cluster_manager_timeout == os_transport::action::TimeValueWire::seconds(30)
        && !request.local
        && !request.index.trim().is_empty()
        && transport_index_exists(&request.index)
}

#[cfg(test)]
fn build_local_create_pit_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    build_local_create_pit_response_for_node(request_id, header_version_id, body, "steel-node-id")
}

fn build_local_create_pit_response_for_node(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    local_node_id: &str,
) -> Vec<u8> {
    let Some(request) = decode_create_pit_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if request.validate_supported_subset().is_err() || request.allow_partial_pit_creation.is_none()
    {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let now_millis = now_epoch_ms();
    let creation_time_millis = now_millis as i64;
    let keep_alive_millis = time_value_wire_to_millis(&request.keep_alive);
    if keep_alive_millis > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let keep_alive_millis_u64 = if keep_alive_millis <= 0 {
        DEV_TRANSPORT_NON_POSITIVE_PIT_KEEP_ALIVE_MILLIS
    } else {
        keep_alive_millis as u64
    };
    let bindings = dev_transport_pit_bindings();
    let Some(resolved_indices) = transport_pit_indices(bindings, &request) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    {
        let mut contexts = bindings
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned");
        prune_expired_transport_pits(&mut contexts, now_millis);
        prune_unavailable_transport_pits(&mut contexts);
        if contexts.len() >= DEV_TRANSPORT_MAX_OPEN_PIT_CONTEXTS {
            return build_create_pit_too_many_open_contexts_error_response(
                request_id,
                header_version_id,
            );
        }
    }
    let documents =
        transport_pit_document_snapshot(bindings, &resolved_indices, request.routing.as_deref());
    let total_shards = transport_pit_total_primary_shards(bindings, &resolved_indices);
    let pit_id = {
        let mut next_id = bindings
            .next_id
            .lock()
            .expect("dev transport next PIT id lock poisoned");
        *next_id += 1;
        let pit_id = build_transport_search_context_pit_id(
            bindings,
            &resolved_indices,
            *next_id,
            local_node_id,
            Version::from_id(header_version_id as i32),
        )
        .unwrap_or_else(|| build_local_pit_id(*next_id));
        let expires_at_millis = transport_pit_expires_at_millis(now_millis, keep_alive_millis_u64);
        register_reader_contexts_for_created_transport_pit(
            bindings,
            &pit_id,
            &documents,
            keep_alive_millis_u64,
            expires_at_millis,
            now_millis,
            now_millis,
        );
        bindings
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .insert(
                pit_id.clone(),
                PitContext {
                    indices: resolved_indices,
                    documents,
                    keep_alive_millis: keep_alive_millis_u64,
                    expires_at_millis,
                    creation_time_millis: now_millis,
                },
            );
        pit_id
    };
    os_transport::action::build_opensearch_create_pit_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &os_transport::action::OpenSearchCreatePitResponseWire::success(
            pit_id,
            creation_time_millis,
            usize_to_i32_saturating(total_shards),
        ),
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn transport_pit_indices(
    bindings: &DevTransportPitBindings,
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<Vec<String>> {
    let selectors = if request.indices.is_empty() {
        vec!["_all".to_string()]
    } else {
        request.indices.clone()
    };
    let (manifest_indices, data_streams) = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        (
            manifest["indices"].as_object().cloned(),
            transport_pit_data_stream_catalog(&manifest),
        )
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    let mut resolved = Vec::new();
    if !indices.is_empty() {
        let mut wildcard_seen = false;
        for selector in selectors.iter().filter(|selector| !selector.is_empty()) {
            let exclude_selector = selector.starts_with('-') && wildcard_seen;
            let selector_expression = if exclude_selector {
                &selector[1..]
            } else {
                selector.as_str()
            };
            let wildcard_selector = selector_expression == "_all"
                || selector_expression.contains('*')
                || selector_expression.contains('?');
            let effective_selector = if selector_expression == "_all" {
                "*"
            } else {
                selector_expression
            };
            let mut selector_matched = false;
            let mut selector_alias_matches = 0_usize;
            let mut selector_resolved = Vec::new();
            for (index_name, index_body) in indices.iter() {
                if effective_selector == index_name
                    || wildcard_match(effective_selector, index_name.as_str())
                {
                    selector_matched = true;
                    if transport_pit_index_matches_options(
                        index_body,
                        wildcard_selector,
                        &request.indices_options,
                    )? {
                        selector_resolved.push(index_name.clone());
                    }
                    continue;
                }
                if !request.indices_options.ignore_aliases {
                    if let Some(aliases) = index_body["aliases"].as_object() {
                        if aliases.contains_key(selector_expression)
                            || aliases
                                .keys()
                                .any(|alias| wildcard_match(effective_selector, alias))
                        {
                            selector_matched = true;
                            selector_alias_matches += 1;
                            if transport_pit_index_matches_options(
                                index_body,
                                wildcard_selector,
                                &request.indices_options,
                            )? {
                                selector_resolved.push(index_name.clone());
                            }
                        }
                    }
                }
            }
            for (data_stream_name, backing_indices) in data_streams.iter() {
                if effective_selector == data_stream_name
                    || wildcard_match(effective_selector, data_stream_name)
                {
                    selector_matched = true;
                    for backing_index in backing_indices {
                        let Some(index_body) = indices.get(backing_index) else {
                            resolved.push(backing_index.clone());
                            continue;
                        };
                        if transport_pit_index_matches_options(
                            index_body,
                            wildcard_selector,
                            &request.indices_options,
                        )? {
                            selector_resolved.push(backing_index.clone());
                        }
                    }
                }
            }
            if selector_alias_matches > 1
                && request.indices_options.forbid_aliases_to_multiple_indices
            {
                return None;
            }
            if !selector_matched
                && ((wildcard_selector && !request.indices_options.allow_no_indices)
                    || (!wildcard_selector && !request.indices_options.ignore_unavailable))
            {
                return None;
            }
            if exclude_selector {
                resolved
                    .retain(|index| !selector_resolved.iter().any(|candidate| candidate == index));
            } else {
                resolved.extend(selector_resolved);
            }
            if wildcard_selector {
                wildcard_seen = true;
            }
        }
    } else if !request.indices.is_empty() {
        for selector in selectors.iter().filter(|selector| !selector.is_empty()) {
            let wildcard_selector =
                selector == "_all" || selector.contains('*') || selector.contains('?');
            if (wildcard_selector && !request.indices_options.allow_no_indices)
                || (!wildcard_selector && !request.indices_options.ignore_unavailable)
            {
                return None;
            }
        }
    }
    if resolved.is_empty() && request.indices.is_empty() {
        resolved = bindings
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .iter()
            .cloned()
            .collect();
    }
    resolved.sort();
    resolved.dedup();
    Some(resolved)
}

fn create_pit_missing_concrete_index(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<String> {
    if request.indices_options.ignore_unavailable {
        return None;
    }
    let bindings = dev_transport_pit_bindings();
    let (manifest_indices, data_streams) = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        (
            manifest["indices"].as_object().cloned(),
            transport_pit_data_stream_catalog(&manifest),
        )
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| {
            selector.as_str() != "_all" && !selector.contains('*') && !selector.contains('?')
        })
        .filter(|selector| {
            !transport_pit_selector_matches_target(selector, &indices, &data_streams, request)
        })
        .cloned()
        .next()
}

fn create_pit_closed_concrete_index(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<String> {
    if !request.indices_options.forbid_closed_indices || request.indices_options.ignore_unavailable
    {
        return None;
    }
    let bindings = dev_transport_pit_bindings();
    let manifest_indices = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        manifest["indices"].as_object().cloned()
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| {
            selector.as_str() != "_all" && !selector.contains('*') && !selector.contains('?')
        })
        .find_map(|selector| {
            indices
                .get(selector)
                .filter(|index_body| {
                    index_body["state"]
                        .as_str()
                        .is_some_and(|state| state == "close")
                })
                .map(|_| selector.clone())
        })
}

fn create_pit_ignored_alias(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<String> {
    if !request.indices_options.ignore_aliases {
        return None;
    }
    let fail_no_indices = if request.indices.len() == 1 {
        !request.indices_options.allow_no_indices
    } else {
        !request.indices_options.ignore_unavailable
    };
    if !fail_no_indices {
        return None;
    }
    let bindings = dev_transport_pit_bindings();
    let manifest_indices = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        manifest["indices"].as_object().cloned()
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| {
            selector.as_str() != "_all" && !selector.contains('*') && !selector.contains('?')
        })
        .find(|selector| {
            indices.values().any(|index_body| {
                index_body["aliases"]
                    .as_object()
                    .is_some_and(|aliases| aliases.contains_key(selector.as_str()))
            })
        })
        .cloned()
}

fn create_pit_alias_multiple_indices(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<(String, Vec<String>)> {
    if request.indices_options.ignore_aliases
        || !request.indices_options.forbid_aliases_to_multiple_indices
    {
        return None;
    }
    let bindings = dev_transport_pit_bindings();
    let manifest_indices = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        manifest["indices"].as_object().cloned()
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| {
            selector.as_str() != "_all" && !selector.contains('*') && !selector.contains('?')
        })
        .find_map(|selector| {
            let mut matching_indices = indices
                .iter()
                .filter_map(|(index_name, index_body)| {
                    index_body["aliases"]
                        .as_object()
                        .is_some_and(|aliases| aliases.contains_key(selector.as_str()))
                        .then(|| index_name.clone())
                })
                .collect::<Vec<_>>();
            matching_indices.sort();
            matching_indices.dedup();
            (matching_indices.len() > 1).then(|| (selector.clone(), matching_indices))
        })
}

fn create_pit_invalid_index_name(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> Option<String> {
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| selector.as_str() != "_all")
        .find(|selector| selector.starts_with('_'))
        .cloned()
}

fn create_pit_closed_only_wildcard_forbid_error(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> bool {
    let options = &request.indices_options;
    if !options.forbid_closed_indices
        || options.ignore_unavailable
        || !options.expand_closed
        || options.expand_open
        || options.expand_hidden
    {
        return false;
    }
    let bindings = dev_transport_pit_bindings();
    let manifest_indices = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        manifest["indices"].as_object().cloned()
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    request
        .indices
        .iter()
        .filter(|selector| !selector.is_empty())
        .filter(|selector| {
            selector.as_str() == "_all" || selector.contains('*') || selector.contains('?')
        })
        .any(|selector| {
            let effective_selector = if selector == "_all" { "*" } else { selector };
            indices.iter().any(|(index_name, index_body)| {
                let closed = index_body["state"]
                    .as_str()
                    .is_some_and(|state| state == "close");
                if !closed {
                    return false;
                }
                effective_selector == index_name
                    || wildcard_match(effective_selector, index_name.as_str())
                    || (!options.ignore_aliases
                        && index_body["aliases"].as_object().is_some_and(|aliases| {
                            aliases.contains_key(selector.as_str())
                                || aliases
                                    .keys()
                                    .any(|alias| wildcard_match(effective_selector, alias))
                        }))
            })
        })
}

fn create_pit_wildcard_no_indices_error(
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> bool {
    if request.indices_options.allow_no_indices {
        return false;
    }
    let selectors = if request.indices.is_empty() {
        vec!["_all".to_string()]
    } else {
        request.indices.clone()
    };
    let bindings = dev_transport_pit_bindings();
    if selectors.len() == 1 && selectors[0] == "_all" {
        return match transport_pit_indices(bindings, request) {
            Some(indices) => indices.is_empty(),
            None => true,
        };
    }
    selectors.iter().any(|selector| {
        let selector_expression = selector
            .strip_prefix('-')
            .filter(|_| selector.contains('*') || selector.contains('?'))
            .unwrap_or(selector.as_str());
        (selector_expression.contains('*') || selector_expression.contains('?'))
            && !transport_pit_selector_has_match(bindings, selector_expression, request)
    })
}

fn transport_pit_selector_matches_target(
    selector: &str,
    indices: &BTreeMap<String, Value>,
    data_streams: &BTreeMap<String, Vec<String>>,
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> bool {
    indices.contains_key(selector)
        || data_streams.contains_key(selector)
        || (!request.indices_options.ignore_aliases
            && indices.values().any(|index_body| {
                index_body["aliases"]
                    .as_object()
                    .is_some_and(|aliases| aliases.contains_key(selector))
            }))
}

fn transport_pit_selector_has_match(
    bindings: &DevTransportPitBindings,
    selector: &str,
    request: &os_transport::action::OpenSearchCreatePitRequestWire,
) -> bool {
    let (manifest_indices, data_streams) = {
        let manifest = bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned");
        (
            manifest["indices"].as_object().cloned(),
            transport_pit_data_stream_catalog(&manifest),
        )
    };
    let indices = transport_pit_index_catalog(bindings, manifest_indices);
    let effective_selector = if selector == "_all" { "*" } else { selector };
    let wildcard_selector = selector == "_all" || selector.contains('*') || selector.contains('?');
    indices.iter().any(|(index_name, index_body)| {
        let matches_index =
            effective_selector == index_name || wildcard_match(effective_selector, index_name);
        let matches_alias = !request.indices_options.ignore_aliases
            && index_body["aliases"].as_object().is_some_and(|aliases| {
                aliases.contains_key(selector)
                    || aliases
                        .keys()
                        .any(|alias| wildcard_match(effective_selector, alias))
            });
        (matches_index || matches_alias)
            && transport_pit_index_matches_options(
                index_body,
                wildcard_selector,
                &request.indices_options,
            )
            .unwrap_or(false)
    }) || data_streams.iter().any(|(data_stream, backing_indices)| {
        (effective_selector == data_stream || wildcard_match(effective_selector, data_stream))
            && backing_indices.iter().any(|backing_index| {
                indices.get(backing_index).map_or(true, |index_body| {
                    transport_pit_index_matches_options(
                        index_body,
                        wildcard_selector,
                        &request.indices_options,
                    )
                    .unwrap_or(false)
                })
            })
    })
}

fn transport_pit_data_stream_catalog(metadata_manifest: &Value) -> BTreeMap<String, Vec<String>> {
    resolve_index_data_stream_entries(metadata_manifest)
        .into_iter()
        .map(|(data_stream_name, data_stream_metadata)| {
            let mut backing_indices = data_stream_metadata
                .get("backing_indices")
                .or_else(|| data_stream_metadata.get("backingIndices"))
                .or_else(|| data_stream_metadata.get("indices"))
                .and_then(Value::as_array)
                .map(|indices| {
                    indices
                        .iter()
                        .filter_map(Value::as_str)
                        .map(ToOwned::to_owned)
                        .collect::<Vec<_>>()
                })
                .unwrap_or_default();
            backing_indices.sort();
            backing_indices.dedup();
            (data_stream_name, backing_indices)
        })
        .collect()
}

fn build_transport_search_context_pit_id(
    bindings: &DevTransportPitBindings,
    resolved_indices: &[String],
    sequence: u64,
    local_node_id: &str,
    version: Version,
) -> Option<String> {
    let mut shards = BTreeMap::new();
    let mut ordinal = 0_i64;
    for index in resolved_indices {
        for shard_id in 0..transport_pit_primary_shard_count(bindings, index) {
            ordinal += 1;
            shards.insert(
                os_transport::action::OpenSearchShardIdWire {
                    index_name: index.clone(),
                    index_uuid: transport_pit_index_uuid(bindings, index),
                    shard_id: shard_id as i32,
                },
                os_transport::action::OpenSearchSearchContextIdForNodeWire {
                    node: local_node_id.to_string(),
                    cluster_alias: None,
                    search_context_id:
                        os_transport::action::OpenSearchShardSearchContextIdWire::new(
                            format!("steelsearch-pit-session-{sequence}"),
                            (sequence as i64)
                                .saturating_mul(1_000_000)
                                .saturating_add(ordinal),
                        ),
                },
            );
        }
    }
    os_transport::action::OpenSearchSearchContextIdWire::new(shards)
        .encode(version)
        .ok()
}

fn register_reader_contexts_for_created_transport_pit(
    bindings: &DevTransportPitBindings,
    pit_id: &str,
    documents: &Arc<DocumentMap>,
    keep_alive_millis: u64,
    expires_at_millis: u128,
    creation_time_millis: u128,
    now_millis: u128,
) {
    let Ok(search_context_id) = os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id)
    else {
        return;
    };
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_millis);
    for (shard_id, context) in search_context_id.shards {
        reader_contexts.insert(
            reader_context_key(&context.search_context_id),
            DevTransportReaderContext {
                shard_id,
                documents: Arc::clone(documents),
                keep_alive_millis,
                expires_at_millis,
                pit_id: Some(pit_id.to_string()),
                creation_time_millis: Some(u128_to_i64_saturating(creation_time_millis)),
            },
        );
    }
}

fn transport_pit_index_catalog(
    bindings: &DevTransportPitBindings,
    manifest_indices: Option<serde_json::Map<String, Value>>,
) -> BTreeMap<String, Value> {
    let mut catalog = manifest_indices
        .unwrap_or_default()
        .into_iter()
        .collect::<BTreeMap<_, _>>();
    for index in bindings
        .created_indices
        .lock()
        .expect("dev transport created indices lock poisoned")
        .iter()
    {
        catalog.entry(index.clone()).or_insert_with(|| {
            serde_json::json!({
                "settings": {
                    "index": {
                        "number_of_shards": "1"
                    }
                }
            })
        });
    }
    catalog
}

fn transport_pit_index_uuid(bindings: &DevTransportPitBindings, index: &str) -> String {
    let manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    transport_manifest_index_uuid(&manifest["indices"][index])
        .unwrap_or("_na_")
        .to_string()
}

fn transport_manifest_index_uuid(index_body: &Value) -> Option<&str> {
    index_body["settings"]["index"]["uuid"]
        .as_str()
        .or_else(|| index_body["settings"]["uuid"].as_str())
}

fn transport_pit_primary_shard_count(bindings: &DevTransportPitBindings, index: &str) -> usize {
    let manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    manifest["indices"][index]["settings"]["index"]["number_of_shards"]
        .as_str()
        .or_else(|| manifest["indices"][index]["settings"]["number_of_shards"].as_str())
        .and_then(|value| value.parse::<usize>().ok())
        .filter(|value| *value > 0)
        .unwrap_or(1)
}

fn transport_pit_index_matches_options(
    index_body: &Value,
    wildcard_selector: bool,
    options: &os_transport::action::OpenSearchIndicesOptionsWire,
) -> Option<bool> {
    if !wildcard_selector {
        let closed = index_body["state"]
            .as_str()
            .is_some_and(|state| state == "close");
        return if closed && options.forbid_closed_indices {
            None
        } else {
            Some(true)
        };
    }
    let closed = index_body["state"]
        .as_str()
        .is_some_and(|state| state == "close");
    if closed && (!options.expand_closed || options.forbid_closed_indices) {
        return Some(false);
    }
    if !closed && !options.expand_open {
        return Some(false);
    }
    if transport_index_metadata_is_hidden(index_body) && !options.expand_hidden {
        return Some(false);
    }
    Some(true)
}

fn transport_pit_document_snapshot(
    bindings: &DevTransportPitBindings,
    resolved_indices: &[String],
    routing: Option<&str>,
) -> Arc<DocumentMap> {
    let requested_routings = routing.map(parse_transport_routing_values);
    Arc::new(
        bindings
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .iter()
            .filter_map(|(key, record)| {
                let (doc_index, doc_id, doc_routing) = split_transport_document_key(key)?;
                resolved_indices
                    .iter()
                    .any(|candidate| candidate == doc_index)
                    .then_some(())?;
                if let Some(requested_routings) = requested_routings.as_ref() {
                    transport_document_matches_requested_routing_shards(
                        bindings,
                        doc_index,
                        doc_id,
                        doc_routing,
                        requested_routings,
                    )
                    .then_some(())?;
                }
                Some((key.clone(), Arc::clone(record)))
            })
            .collect(),
    )
}

fn parse_transport_routing_values(routing: &str) -> Vec<String> {
    routing
        .split(',')
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned)
        .collect()
}

fn transport_document_matches_requested_routing_shards(
    bindings: &DevTransportPitBindings,
    index: &str,
    doc_id: &str,
    doc_routing: &str,
    requested_routings: &[String],
) -> bool {
    if requested_routings.is_empty() {
        return true;
    }
    let shard_count = transport_pit_primary_shard_count(bindings, index);
    let doc_shard = transport_routing_shard_id(
        shard_count,
        transport_effective_routing(doc_id, doc_routing),
    );
    requested_routings
        .iter()
        .any(|routing| transport_routing_shard_id(shard_count, routing.as_str()) == doc_shard)
}

fn transport_effective_routing<'a>(doc_id: &'a str, doc_routing: &'a str) -> &'a str {
    if doc_routing.is_empty() {
        doc_id
    } else {
        doc_routing
    }
}

fn transport_routing_shard_id(shard_count: usize, routing: &str) -> i64 {
    if shard_count == 0 {
        0
    } else {
        opensearch_transport_routing_hash(routing).rem_euclid(shard_count as i64)
    }
}

fn transport_live_document_snapshot(bindings: &DevTransportPitBindings) -> Arc<DocumentMap> {
    Arc::new(
        bindings
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .clone(),
    )
}

fn transport_pit_total_primary_shards(
    bindings: &DevTransportPitBindings,
    resolved_indices: &[String],
) -> usize {
    let manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    resolved_indices
        .iter()
        .map(|index| {
            let settings = &manifest["indices"][index]["settings"];
            settings["index"]["number_of_shards"]
                .as_str()
                .or_else(|| settings["number_of_shards"].as_str())
                .and_then(|value| value.parse::<usize>().ok())
                .unwrap_or(1)
        })
        .sum()
}

fn split_transport_document_key(key: &str) -> Option<(&str, &str, &str)> {
    let mut parts = key.splitn(3, ':');
    Some((parts.next()?, parts.next()?, parts.next()?))
}

