fn build_search_request_missing_pit_context_error_response(
    request_id: i64,
    header_version_id: u32,
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> Vec<u8> {
    let pit_id = search_request_pit_id(request).unwrap_or_default();
    let context_id = first_missing_transport_reader_context_id_from_pit_id(pit_id)
        .or_else(|| first_search_context_id_from_pit_id(pit_id))
        .unwrap_or_else(|| {
            os_transport::action::OpenSearchShardSearchContextIdWire::new(String::new(), -1)
        });
    build_missing_search_context_error_response(request_id, header_version_id, &context_id)
}

fn build_missing_search_context_error_response(
    request_id: i64,
    header_version_id: u32,
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> Vec<u8> {
    let reason = format!("No search context found for id [{}]", context_id.id);
    let mut output = StreamOutput::new();
    os_transport::error::write_search_context_missing_exception(
        &mut output,
        Some(&reason),
        &context_id.session_id,
        context_id.id,
    );
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn first_search_context_id_from_pit_id(
    pit_id: &str,
) -> Option<os_transport::action::OpenSearchShardSearchContextIdWire> {
    let context_id = os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id).ok()?;
    context_id
        .shards
        .values()
        .next()
        .map(|context| context.search_context_id.clone())
}

fn search_request_pit_keep_alive_exceeds_limit(
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> bool {
    request
        .source
        .as_ref()
        .and_then(|source| source.point_in_time.as_ref())
        .and_then(|pit| pit.keep_alive.as_ref())
        .is_some_and(|keep_alive| {
            time_value_wire_to_millis(keep_alive) > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS
        })
}

fn build_search_request_pit_keep_alive_too_large_error_response(
    request_id: i64,
    header_version_id: u32,
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> Vec<u8> {
    let keep_alive_millis = request
        .source
        .as_ref()
        .and_then(|source| source.point_in_time.as_ref())
        .and_then(|pit| pit.keep_alive.as_ref())
        .map(time_value_wire_to_millis)
        .unwrap_or_default();
    build_pit_keep_alive_too_large_error_response(request_id, header_version_id, keep_alive_millis)
}

fn build_local_multi_search_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_multi_search_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if request.validate_supported_execution_subset().is_err() {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let response = os_transport::action::OpenSearchMultiSearchResponseWire::success(
        request
            .requests
            .iter()
            .map(local_transport_search_response_from_request)
            .collect(),
        1,
    );
    os_transport::action::build_opensearch_multi_search_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn multi_search_request_supports_local_execution_subset(body: &[u8]) -> bool {
    decode_multi_search_request_from_transport_body(body).is_some_and(|request| {
        request.validate_supported_execution_subset().is_ok()
            && request
                .requests
                .iter()
                .all(search_request_matches_local_execution_subset)
    })
}

