fn missing_search_scroll_context_id(
    request: &os_transport::action::OpenSearchSearchScrollRequestWire,
) -> Option<os_transport::action::OpenSearchShardSearchContextIdWire> {
    if request.validate_supported_execution_subset().is_err() {
        return None;
    }
    let parsed =
        os_transport::action::OpenSearchParsedScrollIdWire::decode(&request.scroll_id).ok()?;
    let contexts = dev_transport_scroll_bindings()
        .contexts
        .lock()
        .expect("dev transport scroll contexts lock poisoned");
    parsed.contexts.iter().find_map(|context| {
        transport_scroll_context_lookup_key_for_request(&contexts, &context.search_context_id)
            .is_none()
            .then(|| context.search_context_id.clone())
    })
}

fn advance_transport_scroll_context(
    scroll_id: &str,
) -> os_transport::action::OpenSearchSearchResponseWire {
    let mut contexts = dev_transport_scroll_bindings()
        .contexts
        .lock()
        .expect("dev transport scroll contexts lock poisoned");
    let context_key = transport_scroll_context_lookup_key_for_scroll_id(&contexts, scroll_id);
    let Some(context) = contexts.get_mut(&context_key) else {
        return os_transport::action::OpenSearchSearchResponseWire::empty_with_total_hits(0);
    };
    let take = context.page_size.max(1);
    let page = context
        .remaining_hits
        .iter()
        .take(take)
        .cloned()
        .collect::<Vec<_>>();
    context.remaining_hits = context.remaining_hits.iter().skip(take).cloned().collect();
    let total_hits = page.len() as i64;
    let hits = page
        .iter()
        .map(transport_scroll_hit_from_rest_hit)
        .collect::<Vec<_>>();
    os_transport::action::OpenSearchSearchResponseWire {
        total_hits: Some(total_hits),
        total_hits_relation: 0,
        max_score: hits
            .iter()
            .map(|hit| hit.score)
            .filter(|score| !score.is_nan())
            .max_by(|left, right| left.partial_cmp(right).unwrap_or(std::cmp::Ordering::Equal))
            .unwrap_or(f32::NAN),
        hits,
        total_shards: 1,
        successful_shards: 1,
        scroll_id: Some(scroll_id.to_string()),
        took_millis: 1,
        ..os_transport::action::OpenSearchSearchResponseWire::empty_with_total_hits(total_hits)
    }
}

fn transport_scroll_context_lookup_key_for_scroll_id(
    contexts: &BTreeMap<String, ScrollContext>,
    scroll_id: &str,
) -> String {
    os_transport::action::OpenSearchParsedScrollIdWire::decode(scroll_id)
        .ok()
        .and_then(|parsed| {
            (parsed.contexts.len() == 1).then(|| {
                transport_scroll_context_lookup_key_for_request(
                    contexts,
                    &parsed.contexts[0].search_context_id,
                )
                .unwrap_or_else(|| {
                    transport_scroll_context_key(&parsed.contexts[0].search_context_id)
                })
            })
        })
        .unwrap_or_else(|| scroll_id.to_string())
}

fn transport_scroll_context_key(
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> String {
    format!("{}:{}", context_id.session_id, context_id.id)
}

fn transport_scroll_context_lookup_key_for_request(
    contexts: &BTreeMap<String, ScrollContext>,
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> Option<String> {
    if context_id.session_id.is_empty() {
        contexts
            .keys()
            .find(|key| {
                key.rsplit_once(':')
                    .and_then(|(_, id)| id.parse::<i64>().ok())
                    == Some(context_id.id)
            })
            .cloned()
    } else {
        let key = transport_scroll_context_key(context_id);
        contexts.contains_key(&key).then_some(key)
    }
}

fn transport_scroll_hit_from_rest_hit(
    hit: &Value,
) -> os_transport::action::OpenSearchSearchHitWire {
    let index = hit
        .get("_index")
        .and_then(Value::as_str)
        .unwrap_or_default();
    os_transport::action::OpenSearchSearchHitWire {
        id: hit
            .get("_id")
            .and_then(Value::as_str)
            .filter(|id| !id.is_empty())
            .map(ToString::to_string),
        score: hit
            .get("_score")
            .and_then(Value::as_f64)
            .map(|score| score as f32)
            .unwrap_or(1.0),
        nested_identity: None,
        version: hit.get("_version").and_then(Value::as_i64).unwrap_or(-1),
        seq_no: hit.get("_seq_no").and_then(Value::as_i64).unwrap_or(-2),
        primary_term: hit
            .get("_primary_term")
            .and_then(Value::as_i64)
            .unwrap_or(0),
        source: hit.get("_source").cloned(),
        explanation: hit.get("_explanation").cloned(),
        fields: BTreeMap::new(),
        meta_fields: BTreeMap::new(),
        highlight_fields: BTreeMap::new(),
        sort_values: hit
            .get("sort")
            .and_then(Value::as_array)
            .cloned()
            .unwrap_or_default(),
        matched_queries: BTreeMap::new(),
        shard_target: os_transport::action::OpenSearchSearchShardTargetWire::from_hit_index(index),
        inner_hits: BTreeMap::new(),
    }
}

