fn local_transport_query_children(
    query: &os_transport::action::OpenSearchQueryBuilderWire,
) -> Vec<&os_transport::action::OpenSearchQueryBuilderWire> {
    match query {
        os_transport::action::OpenSearchQueryBuilderWire::Bool(query) => query
            .must
            .iter()
            .chain(query.must_not.iter())
            .chain(query.should.iter())
            .chain(query.filter.iter())
            .collect(),
        os_transport::action::OpenSearchQueryBuilderWire::Boosting(query) => {
            vec![query.positive.as_ref(), query.negative.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::ConstantScore(query) => {
            vec![query.filter.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::DisMax(query) => {
            query.queries.iter().collect()
        }
        os_transport::action::OpenSearchQueryBuilderWire::FieldMaskingSpan(query) => {
            vec![query.query.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::FunctionScore(query) => {
            let mut children = vec![query.query.as_ref()];
            children.extend(
                query
                    .filter_functions
                    .iter()
                    .map(|function| function.filter.as_ref()),
            );
            children
        }
        os_transport::action::OpenSearchQueryBuilderWire::Nested(query) => {
            vec![query.query.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::ScriptScore(query) => {
            vec![query.query.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::SpanMulti(query) => {
            vec![query.query.as_ref()]
        }
        os_transport::action::OpenSearchQueryBuilderWire::SpanNear(query) => {
            query.clauses.iter().collect()
        }
        os_transport::action::OpenSearchQueryBuilderWire::SpanOr(query) => {
            query.clauses.iter().collect()
        }
        _ => Vec::new(),
    }
}

fn local_transport_hit_fields(
    source: &Value,
    request_source: Option<&os_transport::action::OpenSearchSearchSourceBuilderWire>,
) -> BTreeMap<String, Vec<Value>> {
    let Some(request_source) = request_source else {
        return BTreeMap::new();
    };
    let mut fields = BTreeMap::new();
    for field in request_source
        .doc_value_fields
        .as_deref()
        .unwrap_or_default()
        .iter()
        .chain(request_source.fetch_fields.as_deref().unwrap_or_default())
    {
        local_transport_insert_field_values(source, &mut fields, &field.field);
    }
    if let Some(stored_fields) = &request_source.stored_fields {
        if stored_fields.fetch_fields {
            for field in stored_fields.field_names.as_deref().unwrap_or_default() {
                local_transport_insert_field_values(source, &mut fields, field);
            }
        }
    }
    for script_field in request_source
        .script_fields
        .as_deref()
        .unwrap_or_default()
        .iter()
    {
        if let Some(value) = local_transport_script_field_value(source, script_field) {
            fields.insert(script_field.field_name.clone(), vec![value]);
        }
    }
    fields
}

fn local_transport_insert_field_values(
    source: &Value,
    fields: &mut BTreeMap<String, Vec<Value>>,
    field: &str,
) {
    let Some(value) = lookup_transport_source_value(source, field) else {
        return;
    };
    let values = match value {
        Value::Array(values) => values.clone(),
        value => vec![value.clone()],
    };
    if !values.is_empty() {
        fields.insert(field.to_string(), values);
    }
}

fn local_transport_script_field_value(
    source: &Value,
    script_field: &os_transport::action::OpenSearchScriptFieldWire,
) -> Option<Value> {
    let script = script_field.script.source.trim();
    let emitted = script.strip_prefix("emit(")?.strip_suffix(')')?.trim();
    if let Some(field) = emitted
        .strip_prefix("params._source['")
        .and_then(|value| value.strip_suffix("']"))
        .or_else(|| {
            emitted
                .strip_prefix("params._source[\"")
                .and_then(|value| value.strip_suffix("\"]"))
        })
    {
        return lookup_transport_source_value(source, field).cloned();
    }
    emitted
        .strip_prefix('\'')
        .and_then(|value| value.strip_suffix('\''))
        .or_else(|| {
            emitted
                .strip_prefix('"')
                .and_then(|value| value.strip_suffix('"'))
        })
        .map(|value| Value::String(value.to_string()))
        .or_else(|| {
            emitted
                .parse::<i64>()
                .ok()
                .map(|value| Value::Number(value.into()))
        })
        .or_else(|| {
            emitted
                .parse::<f64>()
                .ok()
                .and_then(serde_json::Number::from_f64)
                .map(Value::Number)
        })
}

fn local_transport_filter_hit_source(
    source: &Value,
    fetch_source: Option<&os_transport::action::OpenSearchFetchSourceContextWire>,
) -> Option<Value> {
    let Some(fetch_source) = fetch_source else {
        return Some(source.clone());
    };
    if !fetch_source.fetch_source {
        return None;
    }
    let mut filtered = if fetch_source.includes.is_empty() {
        source.clone()
    } else {
        let mut included = Value::Object(serde_json::Map::new());
        for path in &fetch_source.includes {
            local_transport_copy_source_paths(source, &mut included, path);
        }
        included
    };
    for path in &fetch_source.excludes {
        local_transport_remove_source_paths(&mut filtered, path);
    }
    Some(filtered)
}

fn local_transport_copy_source_paths(source: &Value, target: &mut Value, path: &str) {
    let parts = path.split('.').collect::<Vec<_>>();
    if parts.is_empty() {
        return;
    }
    if let Some(extracted) = local_transport_extract_source_path_parts(source, &parts) {
        local_transport_merge_source_value(target, extracted);
    }
}

fn local_transport_extract_source_path_parts(source: &Value, parts: &[&str]) -> Option<Value> {
    let Some((part, rest)) = parts.split_first() else {
        return Some(source.clone());
    };
    match source {
        Value::Object(source_object) => {
            let mut output = serde_json::Map::new();
            for (field, value) in source_object {
                if !wildcard_match(part, field) {
                    continue;
                }
                let extracted = if rest.is_empty() {
                    value.clone()
                } else {
                    local_transport_extract_source_path_parts(value, rest)?
                };
                output.insert(field.clone(), extracted);
            }
            (!output.is_empty()).then_some(Value::Object(output))
        }
        Value::Array(values) => {
            let filtered = values
                .iter()
                .filter_map(|value| local_transport_extract_source_path_parts(value, parts))
                .collect::<Vec<_>>();
            (!filtered.is_empty()).then_some(Value::Array(filtered))
        }
        _ => None,
    }
}

fn local_transport_merge_source_value(target: &mut Value, incoming: Value) {
    match (target, incoming) {
        (Value::Object(target_object), Value::Object(incoming_object)) => {
            for (field, value) in incoming_object {
                match target_object.get_mut(&field) {
                    Some(existing) => local_transport_merge_source_value(existing, value),
                    None => {
                        target_object.insert(field, value);
                    }
                }
            }
        }
        (target_value, incoming_value) => *target_value = incoming_value,
    }
}

fn local_transport_remove_source_paths(source: &mut Value, path: &str) {
    let parts = path.split('.').collect::<Vec<_>>();
    if parts.is_empty() {
        return;
    }
    local_transport_remove_source_path_parts(source, &parts);
}

fn local_transport_remove_source_path_parts(source: &mut Value, parts: &[&str]) {
    let Some((part, rest)) = parts.split_first() else {
        return;
    };
    match source {
        Value::Object(source_object) => {
            if rest.is_empty() {
                source_object.retain(|field, _| !wildcard_match(part, field));
                return;
            }
            for value in source_object
                .iter_mut()
                .filter_map(|(field, value)| wildcard_match(part, field).then_some(value))
            {
                local_transport_remove_source_path_parts(value, rest);
            }
        }
        Value::Array(values) => {
            for value in values {
                local_transport_remove_source_path_parts(value, parts);
            }
        }
        _ => {}
    }
}

fn sort_transport_search_matches(
    matches: &mut [LocalTransportSearchMatch],
    sorts: Option<&[os_transport::action::OpenSearchSortBuilderWire]>,
    shard_count: usize,
) {
    matches.sort_by(|left, right| {
        if let Some(sorts) = sorts {
            for sort in sorts {
                let ordering = compare_transport_search_sort_values(left, right, sort, shard_count);
                if ordering != std::cmp::Ordering::Equal {
                    return ordering;
                }
            }
        }
        left.5
            .cmp(&right.5)
            .then_with(|| left.0.cmp(&right.0))
            .then_with(|| left.1.cmp(&right.1))
    });
}

fn compare_transport_search_sort_values(
    left: &LocalTransportSearchMatch,
    right: &LocalTransportSearchMatch,
    sort: &os_transport::action::OpenSearchSortBuilderWire,
    shard_count: usize,
) -> std::cmp::Ordering {
    let descending = transport_search_sort_descending(sort);
    let left_value = transport_search_sort_value_for_match(
        shard_count,
        &left.0,
        &left.1,
        &left.2,
        &left.3,
        left.5,
        left.7,
        sort,
    );
    let right_value = transport_search_sort_value_for_match(
        shard_count,
        &right.0,
        &right.1,
        &right.2,
        &right.3,
        right.5,
        right.7,
        sort,
    );
    let ordering = compare_transport_search_sort_json(&left_value, &right_value);
    if descending {
        ordering.reverse()
    } else {
        ordering
    }
}

fn transport_search_match_after(
    candidate: &LocalTransportSearchMatch,
    sorts: &[os_transport::action::OpenSearchSortBuilderWire],
    search_after: &[Value],
    shard_count: usize,
) -> bool {
    if sorts.is_empty() || sorts.len() != search_after.len() {
        return true;
    }
    for (sort, after_value) in sorts.iter().zip(search_after.iter()) {
        let value = transport_search_sort_value_for_match(
            shard_count,
            &candidate.0,
            &candidate.1,
            &candidate.2,
            &candidate.3,
            candidate.5,
            candidate.7,
            sort,
        );
        let mut ordering = compare_transport_search_sort_json(&value, after_value);
        if transport_search_sort_descending(sort) {
            ordering = ordering.reverse();
        }
        if ordering == std::cmp::Ordering::Equal {
            continue;
        }
        return ordering == std::cmp::Ordering::Greater;
    }
    false
}

fn transport_search_sort_values_for_match(
    shard_count: usize,
    index: &str,
    id: &str,
    routing: &str,
    source: &Value,
    seq_no: i64,
    score: f32,
    sorts: &[os_transport::action::OpenSearchSortBuilderWire],
) -> Vec<Value> {
    sorts
        .iter()
        .map(|sort| {
            transport_search_sort_value_for_match(
                shard_count,
                index,
                id,
                routing,
                source,
                seq_no,
                score,
                sort,
            )
        })
        .collect()
}

fn transport_search_sort_value_for_match(
    shard_count: usize,
    index: &str,
    id: &str,
    routing: &str,
    source: &Value,
    seq_no: i64,
    score: f32,
    sort: &os_transport::action::OpenSearchSortBuilderWire,
) -> Value {
    match sort {
        os_transport::action::OpenSearchSortBuilderWire::ShardDoc(_) => Value::from(
            opensearch_transport_shard_doc_sort_key(shard_count, routing, seq_no),
        ),
        os_transport::action::OpenSearchSortBuilderWire::Score(_) => serde_json::json!(score),
        os_transport::action::OpenSearchSortBuilderWire::Field(field) => {
            match field.field_name.as_str() {
                "_shard_doc" => Value::from(opensearch_transport_shard_doc_sort_key(
                    shard_count,
                    routing,
                    seq_no,
                )),
                "_id" => Value::String(id.to_string()),
                "_index" => Value::String(index.to_string()),
                field_name => lookup_transport_source_value(source, field_name)
                    .cloned()
                    .unwrap_or_else(|| field.missing.clone()),
            }
        }
    }
}

fn transport_search_sort_descending(
    sort: &os_transport::action::OpenSearchSortBuilderWire,
) -> bool {
    match sort {
        os_transport::action::OpenSearchSortBuilderWire::Score(score) => {
            score.order == os_transport::action::OpenSearchSortOrderWire::Desc
        }
        os_transport::action::OpenSearchSortBuilderWire::ShardDoc(shard_doc) => {
            shard_doc.order == os_transport::action::OpenSearchSortOrderWire::Desc
        }
        os_transport::action::OpenSearchSortBuilderWire::Field(field) => {
            field.order == Some(os_transport::action::OpenSearchSortOrderWire::Desc)
        }
    }
}

fn compare_transport_search_sort_json(left: &Value, right: &Value) -> std::cmp::Ordering {
    match (left.as_f64(), right.as_f64()) {
        (Some(left), Some(right)) => left
            .partial_cmp(&right)
            .unwrap_or(std::cmp::Ordering::Equal),
        _ => left
            .as_str()
            .unwrap_or_default()
            .cmp(right.as_str().unwrap_or_default()),
    }
}

fn opensearch_transport_shard_doc_sort_key(shard_count: usize, routing: &str, seq_no: i64) -> i64 {
    let shard_id = if shard_count == 0 {
        0
    } else {
        opensearch_transport_routing_hash(routing).rem_euclid(shard_count as i64)
    };
    (shard_id << 32) | (seq_no & 0xffff_ffff)
}

fn opensearch_transport_routing_hash(routing: &str) -> i64 {
    let mut bytes = Vec::with_capacity(routing.len() * 2);
    for code_unit in routing.encode_utf16() {
        bytes.push((code_unit & 0xff) as u8);
        bytes.push((code_unit >> 8) as u8);
    }
    opensearch_transport_murmur3_x86_32(&bytes, 0)
}

fn transport_document_matches_search_slice(
    doc_id: &str,
    source: &Value,
    slice: &os_transport::action::OpenSearchSliceBuilderWire,
) -> bool {
    if slice.max <= 1 {
        return true;
    }
    let hash = if slice.field == "_id" {
        opensearch_transport_terms_slice_hash(&opensearch_transport_uid_encoded_utf8_id(doc_id))
    } else {
        let key = lookup_transport_source_value(source, &slice.field)
            .map(transport_search_slice_value_key)
            .unwrap_or_default();
        opensearch_transport_terms_slice_hash(key.as_bytes())
    };
    hash.rem_euclid(slice.max as i64) == slice.id as i64
}

fn transport_search_slice_value_key(value: &Value) -> String {
    match value {
        Value::String(value) => format!("s:{value}"),
        Value::Number(value) => format!("n:{value}"),
        Value::Bool(value) => format!("b:{value}"),
        Value::Null => "null".to_string(),
        _ => value.to_string(),
    }
}

fn opensearch_transport_uid_encoded_utf8_id(id: &str) -> Vec<u8> {
    let mut encoded = Vec::with_capacity(id.len() + 1);
    encoded.push(0xff);
    encoded.extend_from_slice(id.as_bytes());
    encoded
}

fn opensearch_transport_terms_slice_hash(value: &[u8]) -> i64 {
    opensearch_transport_murmur3_x86_32(value, 7919)
}

fn opensearch_transport_murmur3_x86_32(value: &[u8], seed: u32) -> i64 {
    let mut hash = seed;
    let mut chunks = value.chunks_exact(4);
    for chunk in &mut chunks {
        let mut k = u32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]);
        k = k.wrapping_mul(0xcc9e2d51);
        k = k.rotate_left(15);
        k = k.wrapping_mul(0x1b873593);

        hash ^= k;
        hash = hash.rotate_left(13);
        hash = hash.wrapping_mul(5).wrapping_add(0xe6546b64);
    }

    let tail = chunks.remainder();
    let mut k = 0_u32;
    match tail.len() {
        3 => {
            k ^= u32::from(tail[2]) << 16;
            k ^= u32::from(tail[1]) << 8;
            k ^= u32::from(tail[0]);
        }
        2 => {
            k ^= u32::from(tail[1]) << 8;
            k ^= u32::from(tail[0]);
        }
        1 => {
            k ^= u32::from(tail[0]);
        }
        _ => {}
    }
    if !tail.is_empty() {
        k = k.wrapping_mul(0xcc9e2d51);
        k = k.rotate_left(15);
        k = k.wrapping_mul(0x1b873593);
        hash ^= k;
    }

    hash ^= value.len() as u32;
    hash ^= hash >> 16;
    hash = hash.wrapping_mul(0x85ebca6b);
    hash ^= hash >> 13;
    hash = hash.wrapping_mul(0xc2b2ae35);
    hash ^= hash >> 16;
    i32::from_ne_bytes(hash.to_ne_bytes()) as i64
}

fn transport_search_documents_for_request(
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> Option<(Arc<DocumentMap>, Vec<String>, Option<String>)> {
    let pit = request
        .source
        .as_ref()
        .and_then(|source| source.point_in_time.as_ref());
    if let Some(pit) = pit {
        if first_missing_transport_reader_context_id_from_pit_id(&pit.id).is_some()
            && (!search_request_allows_partial_results(request)
                || !transport_pit_has_available_reader_context(&pit.id))
        {
            return None;
        }
        let now_millis = now_epoch_ms();
        let mut contexts = dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned");
        prune_expired_transport_pits(&mut contexts, now_millis);
        remove_transport_pit_if_indices_missing(&mut contexts, &pit.id)?;
        let context = contexts.get_mut(&pit.id)?;
        if let Some(keep_alive) = pit.keep_alive.as_ref() {
            let keep_alive_millis = time_value_wire_to_millis(keep_alive);
            if keep_alive_millis > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS {
                return None;
            }
            let keep_alive_millis = keep_alive_millis.max(0) as u64;
            if keep_alive_millis > 0 {
                let effective_keep_alive = context.keep_alive_millis.max(keep_alive_millis);
                context.keep_alive_millis = effective_keep_alive;
                context.expires_at_millis =
                    transport_pit_expires_at_millis(now_millis, effective_keep_alive);
                extend_transport_reader_contexts_for_pit_id(
                    &pit.id,
                    effective_keep_alive,
                    context.expires_at_millis,
                    now_millis,
                );
            }
        }
        return Some((
            context.documents.clone(),
            context.indices.clone(),
            Some(pit.id.clone()),
        ));
    }
    let bindings = dev_transport_pit_bindings();
    let resolved_indices = transport_search_indices(bindings, request)?;
    let documents = transport_live_document_snapshot(bindings);
    Some((documents, resolved_indices, None))
}

fn transport_search_indices(
    bindings: &DevTransportPitBindings,
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> Option<Vec<String>> {
    transport_pit_indices(
        bindings,
        &os_transport::action::OpenSearchCreatePitRequestWire {
            parent_task_node: request.parent_task_node.clone(),
            parent_task_id: request.parent_task_id,
            indices: request.indices.clone(),
            indices_options: request.indices_options.clone(),
            routing: request.routing.clone(),
            preference: request.preference.clone(),
            keep_alive: os_transport::action::TimeValueWire::minutes(1),
            allow_partial_pit_creation: Some(true),
        },
    )
}

fn transport_search_pit_keep_alive_within_limit(
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> bool {
    request
        .source
        .as_ref()
        .and_then(|source| source.point_in_time.as_ref())
        .and_then(|pit| pit.keep_alive.as_ref())
        .map_or(true, |keep_alive| {
            time_value_wire_to_millis(keep_alive) <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS
        })
}

fn transport_search_pit_context_exists_for_request(
    request: &os_transport::action::OpenSearchSearchRequestWire,
) -> bool {
    let Some(pit) = request
        .source
        .as_ref()
        .and_then(|source| source.point_in_time.as_ref())
    else {
        return true;
    };
    if !transport_search_pit_request_indices_match_actual(request, &pit.id) {
        return false;
    }
    let mut contexts = dev_transport_pit_bindings()
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    prune_expired_transport_pits(&mut contexts, now_epoch_ms());
    let pit_context_exists =
        remove_transport_pit_if_indices_missing(&mut contexts, &pit.id).is_some();
    drop(contexts);
    if !pit_context_exists {
        return false;
    }
    first_missing_transport_reader_context_id_from_pit_id(&pit.id).is_none()
        || (search_request_allows_partial_results(request)
            && transport_pit_has_available_reader_context(&pit.id))
}

fn first_missing_transport_reader_context_id_from_pit_id(
    pit_id: &str,
) -> Option<os_transport::action::OpenSearchShardSearchContextIdWire> {
    transport_pit_missing_reader_contexts(pit_id)
        .into_iter()
        .map(|(_, context)| context.search_context_id)
        .next()
}

fn transport_pit_missing_reader_contexts(
    pit_id: &str,
) -> Vec<(
    os_transport::action::OpenSearchShardIdWire,
    os_transport::action::OpenSearchSearchContextIdForNodeWire,
)> {
    let Ok(context_id) = os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id) else {
        return Vec::new();
    };
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    context_id
        .shards
        .into_iter()
        .filter(|(_, context)| {
            reader_context_lookup_key_for_request(&reader_contexts, &context.search_context_id)
                .is_none()
        })
        .collect()
}

fn transport_pit_has_available_reader_context(pit_id: &str) -> bool {
    let Ok(context_id) = os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id) else {
        return false;
    };
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    context_id.shards.values().any(|context| {
        reader_context_lookup_key_for_request(&reader_contexts, &context.search_context_id)
            .is_some()
    })
}

fn transport_search_total_shards(pit_id: Option<&str>, resolved_indices: &[String]) -> i32 {
    pit_id
        .and_then(|pit_id| os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id).ok())
        .map(|context_id| context_id.shards.len() as i32)
        .unwrap_or_else(|| {
            transport_pit_total_primary_shards(dev_transport_pit_bindings(), resolved_indices)
                as i32
        })
}

fn transport_pit_missing_reader_context_failures(
    missing_contexts: &[(
        os_transport::action::OpenSearchShardIdWire,
        os_transport::action::OpenSearchSearchContextIdForNodeWire,
    )],
) -> Vec<os_transport::action::OpenSearchShardSearchFailureWire> {
    missing_contexts
        .iter()
        .map(|(shard_id, context)| {
            let reason = format!(
                "No search context found for id [{}]",
                context.search_context_id.id
            );
            os_transport::action::OpenSearchShardSearchFailureWire {
                shard_target: Some(os_transport::action::OpenSearchSearchShardTargetWire {
                    node_id: Some(context.node.clone()),
                    index: shard_id.index_name.clone(),
                    index_uuid: shard_id.index_uuid.clone(),
                    shard_id: shard_id.shard_id,
                    cluster_alias: context.cluster_alias.clone(),
                }),
                reason: reason.clone(),
                status: "NOT_FOUND".to_string(),
                cause: Some(os_transport::error::TransportError {
                    class_name: "org.opensearch.search.SearchContextMissingException".to_string(),
                    message: Some(reason),
                    cause: None,
                    search_context_id: Some(os_transport::error::TransportErrorSearchContextId {
                        session_id: context.search_context_id.session_id.clone(),
                        id: context.search_context_id.id,
                    }),
                }),
            }
        })
        .collect()
}

fn transport_search_pit_request_indices_match_actual(
    request: &os_transport::action::OpenSearchSearchRequestWire,
    pit_id: &str,
) -> bool {
    if request.indices.is_empty() {
        return true;
    }
    let Some(mut actual_indices) = transport_pit_indices_from_id(pit_id) else {
        return false;
    };
    let mut request_indices = request.indices.clone();
    actual_indices.sort();
    actual_indices.dedup();
    request_indices.sort();
    request_indices.dedup();
    request_indices == actual_indices
}

fn remove_transport_pit_if_indices_missing(
    contexts: &mut BTreeMap<String, PitContext>,
    pit_id: &str,
) -> Option<()> {
    let context = contexts.get(pit_id)?;
    let bindings = dev_transport_pit_bindings();
    let created_indices = bindings
        .created_indices
        .lock()
        .expect("dev transport created indices lock poisoned");
    let all_indices_exist = context
        .indices
        .iter()
        .all(|index| created_indices.contains(index));
    drop(created_indices);
    if !all_indices_exist {
        contexts.remove(pit_id);
        return None;
    }

    let metadata_manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    let all_indices_open = context.indices.iter().all(|index| {
        metadata_manifest["indices"][index]["state"]
            .as_str()
            .map_or(true, |state| state != "close")
    });
    drop(metadata_manifest);
    if all_indices_open {
        return Some(());
    }
    contexts.remove(pit_id);
    None
}

fn local_transport_query_matches(
    source: &Value,
    id: &str,
    query: Option<&os_transport::action::OpenSearchQueryBuilderWire>,
) -> bool {
    match query {
        None | Some(os_transport::action::OpenSearchQueryBuilderWire::MatchAll(_)) => true,
        Some(os_transport::action::OpenSearchQueryBuilderWire::MatchNone(_)) => false,
        Some(os_transport::action::OpenSearchQueryBuilderWire::Bool(bool_query)) => {
            local_transport_bool_query_matches(source, id, bool_query)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Boosting(query)) => {
            local_transport_query_matches(source, id, Some(query.positive.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::ConstantScore(query)) => {
            local_transport_query_matches(source, id, Some(query.filter.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::DisMax(query)) => query
            .queries
            .iter()
            .any(|query| local_transport_query_matches(source, id, Some(query))),
        Some(os_transport::action::OpenSearchQueryBuilderWire::Exists(exists)) => {
            if exists.field_name == "_id" {
                return true;
            }
            lookup_transport_source_value(source, &exists.field_name).is_some()
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::FieldMaskingSpan(query)) => {
            local_transport_query_matches(source, id, Some(query.query.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::FunctionScore(query)) => {
            query.min_score.is_none()
                && local_transport_query_matches(source, id, Some(query.query.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Fuzzy(query)) => {
            let value = if query.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &query.field_name).cloned()
            };
            value.is_some_and(|value| {
                transport_any_actual_value_matches(&value, |candidate| {
                    local_transport_value_matches_fuzzy(
                        candidate,
                        query.value.as_str().unwrap_or_default(),
                        local_transport_fuzziness(
                            &query.fuzziness,
                            query.value.as_str().unwrap_or_default(),
                        ),
                    )
                })
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Ids(ids)) => {
            ids.ids.iter().any(|candidate| candidate == id)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::GeoDistance(query)) => {
            let Some(candidate_point) = lookup_transport_source_value(source, &query.field_name)
                .and_then(parse_transport_geo_point_value)
            else {
                return query.ignore_unmapped;
            };
            let query_point = (query.center.lat, query.center.lon);
            haversine_transport_distance_meters(candidate_point, query_point)
                <= query.distance_meters
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::CombinedFields(query)) => {
            let fields = query
                .fields
                .iter()
                .map(|field| field.field_name.as_str())
                .collect::<Vec<_>>();
            let haystacks = collect_transport_searchable_field_values(source, Some(&fields));
            let query_text = query.query_value.as_str().unwrap_or_default();
            local_transport_text_query_matches(&haystacks, query_text, query.operator)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Common(query)) => {
            let haystacks = lookup_transport_source_value(source, &query.field_name)
                .map(collect_transport_string_leaf_values)
                .unwrap_or_default();
            let query_text = query.text.as_str().unwrap_or_default();
            local_transport_text_query_matches(&haystacks, query_text, query.low_freq_operator)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Match(query)) => {
            let haystacks = lookup_transport_source_value(source, &query.field_name)
                .map(collect_transport_string_leaf_values)
                .unwrap_or_default();
            let query_text = query.value.as_str().unwrap_or_default();
            local_transport_match_query_matches(&haystacks, query_text, query.operator)
                || (query_text.trim().is_empty()
                    && query.zero_terms_query
                        == os_transport::action::OpenSearchZeroTermsQueryWire::All)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::MatchBoolPrefix(query)) => {
            let haystacks = lookup_transport_source_value(source, &query.field_name)
                .map(collect_transport_string_leaf_values)
                .unwrap_or_default();
            let query_text = query.value.as_str().unwrap_or_default();
            local_transport_match_bool_prefix_matches(&haystacks, query_text)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::MatchPhrase(query)) => {
            let value = lookup_transport_source_value(source, &query.field_name);
            let query_text = query.value.as_str().unwrap_or_default();
            local_transport_value_matches_phrase(value, query_text, false)
                || (query_text.trim().is_empty()
                    && query.zero_terms_query
                        == os_transport::action::OpenSearchZeroTermsQueryWire::All)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::MatchPhrasePrefix(query)) => {
            let value = lookup_transport_source_value(source, &query.field_name);
            let query_text = query.value.as_str().unwrap_or_default();
            local_transport_value_matches_phrase(value, query_text, true)
                || (query_text.trim().is_empty()
                    && query.zero_terms_query
                        == os_transport::action::OpenSearchZeroTermsQueryWire::All)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::MoreLikeThis(query)) => {
            let fields = query
                .fields
                .as_deref()
                .unwrap_or_default()
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>();
            let haystacks = collect_transport_searchable_field_values(source, Some(&fields));
            query.like_texts.first().is_some_and(|like| {
                local_transport_match_query_matches(
                    &haystacks,
                    like,
                    os_transport::action::OpenSearchMatchOperatorWire::Or,
                )
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::MultiMatch(query)) => {
            let fields = query
                .fields
                .iter()
                .map(|field| field.field_name.as_str())
                .collect::<Vec<_>>();
            let haystacks = collect_transport_searchable_field_values(source, Some(&fields));
            let query_text = query.value.as_str().unwrap_or_default();
            local_transport_text_query_matches(&haystacks, query_text, query.operator)
                || (query_text.trim().is_empty()
                    && query.zero_terms_query
                        == os_transport::action::OpenSearchZeroTermsQueryWire::All)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Nested(query)) => {
            let Some(candidates) =
                lookup_transport_source_value(source, &query.path).and_then(Value::as_array)
            else {
                return query.ignore_unmapped;
            };
            candidates
                .iter()
                .any(|candidate| local_transport_query_matches(candidate, id, Some(&query.query)))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Prefix(prefix)) => {
            let value = if prefix.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &prefix.field_name).cloned()
            };
            value.is_some_and(|value| {
                transport_any_actual_string_matches(&value, |candidate| {
                    local_transport_string_has_prefix(
                        candidate,
                        &prefix.value,
                        prefix.case_insensitive,
                    )
                })
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::QueryString(query)) => {
            let fields = if query.fields.is_empty() {
                query.default_field.as_deref().map(|field| vec![field])
            } else {
                Some(
                    query
                        .fields
                        .iter()
                        .map(|field| field.field_name.as_str())
                        .collect::<Vec<_>>(),
                )
            };
            let haystacks = collect_transport_searchable_field_values(source, fields.as_deref());
            local_transport_query_string_matches(
                &haystacks,
                &query.query_string,
                query.default_operator,
                false,
            )
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Range(range)) => {
            let value = if range.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &range.field_name).cloned()
            };
            value.is_some_and(|value| {
                transport_any_actual_value_matches(&value, |candidate| {
                    local_transport_range_query_matches(candidate, range)
                })
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Regexp(regexp)) => {
            let value = if regexp.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &regexp.field_name).cloned()
            };
            value.is_some_and(|value| {
                transport_any_actual_string_matches(&value, |candidate| {
                    local_transport_regexp_query_matches(
                        candidate,
                        &regexp.value,
                        regexp.case_insensitive,
                    )
                })
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::ScriptScore(query)) => {
            query.min_score.is_none()
                && local_transport_query_matches(source, id, Some(query.query.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::SimpleQueryString(query)) => {
            let fields = if query.fields.is_empty() {
                None
            } else {
                Some(
                    query
                        .fields
                        .iter()
                        .map(|field| field.field_name.as_str())
                        .collect::<Vec<_>>(),
                )
            };
            let haystacks = collect_transport_searchable_field_values(source, fields.as_deref());
            local_transport_query_string_matches(
                &haystacks,
                &query.query_text,
                query.default_operator,
                true,
            )
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::SpanMulti(query)) => {
            local_transport_query_matches(source, id, Some(query.query.as_ref()))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::SpanNear(query)) => {
            local_transport_span_near_query_matches(source, query)
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::SpanOr(query)) => query
            .clauses
            .iter()
            .any(|query| local_transport_query_matches(source, id, Some(query))),
        Some(os_transport::action::OpenSearchQueryBuilderWire::SpanTerm(term)) => {
            if term.field_name == "_id" {
                return value_matches_transport_term(&Value::String(id.to_string()), &term.value);
            }
            lookup_transport_source_value(source, &term.field_name)
                .is_some_and(|value| transport_actual_matches_term(value, &term.value))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Term(term)) => {
            if term.field_name == "_id" {
                return value_matches_transport_term(&Value::String(id.to_string()), &term.value);
            }
            lookup_transport_source_value(source, &term.field_name)
                .is_some_and(|value| transport_actual_matches_term(value, &term.value))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Terms(terms)) => {
            if terms.field_name == "_id" {
                return terms.values.iter().any(|value| {
                    value_matches_transport_term(&Value::String(id.to_string()), value)
                });
            }
            lookup_transport_source_value(source, &terms.field_name)
                .is_some_and(|actual| transport_actual_matches_any_term(actual, &terms.values))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::TermsSet(terms_set)) => {
            let value = if terms_set.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &terms_set.field_name).cloned()
            };
            value.is_some_and(|value| local_transport_terms_set_query_matches(&value, terms_set))
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Wildcard(wildcard)) => {
            let value = if wildcard.field_name == "_id" {
                Some(Value::String(id.to_string()))
            } else {
                lookup_transport_source_value(source, &wildcard.field_name).cloned()
            };
            value.is_some_and(|value| {
                transport_any_actual_string_matches(&value, |candidate| {
                    local_transport_wildcard_query_matches(
                        candidate,
                        &wildcard.value,
                        wildcard.case_insensitive,
                    )
                })
            })
        }
        Some(os_transport::action::OpenSearchQueryBuilderWire::Wrapper(wrapper)) => {
            serde_json::from_slice::<Value>(wrapper.source.as_ref())
                .ok()
                .is_some_and(|query| local_transport_json_query_matches(source, id, &query))
        }
    }
}

fn local_transport_bool_query_matches(
    source: &Value,
    id: &str,
    query: &os_transport::action::OpenSearchBoolQueryBuilderWire,
) -> bool {
    if query
        .must
        .iter()
        .any(|clause| !local_transport_query_matches(source, id, Some(clause)))
    {
        return false;
    }
    if query
        .filter
        .iter()
        .any(|clause| !local_transport_query_matches(source, id, Some(clause)))
    {
        return false;
    }
    if query
        .must_not
        .iter()
        .any(|clause| local_transport_query_matches(source, id, Some(clause)))
    {
        return false;
    }
    let should_match_count = query
        .should
        .iter()
        .filter(|clause| local_transport_query_matches(source, id, Some(clause)))
        .count();
    let minimum_should_match = local_transport_bool_minimum_should_match(query, query.should.len());
    should_match_count >= minimum_should_match
}

fn local_transport_bool_minimum_should_match(
    query: &os_transport::action::OpenSearchBoolQueryBuilderWire,
    should_clause_count: usize,
) -> usize {
    if should_clause_count == 0 {
        return 0;
    }
    if let Some(value) = query.minimum_should_match.as_deref() {
        return value
            .trim()
            .parse::<usize>()
            .map(|minimum| minimum.min(should_clause_count))
            .unwrap_or(1);
    }
    if query.must.is_empty() && query.filter.is_empty() {
        1
    } else {
        0
    }
}

fn local_transport_range_query_matches(
    actual: &Value,
    query: &os_transport::action::OpenSearchRangeQueryBuilderWire,
) -> bool {
    let lower_matches = query.from.is_null()
        || local_transport_range_bound_matches(actual, &query.from, query.include_lower, true);
    let upper_matches = query.to.is_null()
        || local_transport_range_bound_matches(actual, &query.to, query.include_upper, false);
    lower_matches && upper_matches
}

fn local_transport_range_bound_matches(
    actual: &Value,
    bound: &Value,
    inclusive: bool,
    lower_bound: bool,
) -> bool {
    let ordering = match (actual.as_f64(), bound.as_f64()) {
        (Some(actual), Some(bound)) => actual
            .partial_cmp(&bound)
            .unwrap_or(std::cmp::Ordering::Less),
        _ => actual
            .as_str()
            .unwrap_or_default()
            .cmp(bound.as_str().unwrap_or_default()),
    };
    if lower_bound {
        ordering == std::cmp::Ordering::Greater
            || (inclusive && ordering == std::cmp::Ordering::Equal)
    } else {
        ordering == std::cmp::Ordering::Less || (inclusive && ordering == std::cmp::Ordering::Equal)
    }
}

fn local_transport_string_has_prefix(value: &str, prefix: &str, case_insensitive: bool) -> bool {
    if case_insensitive {
        value.to_lowercase().starts_with(&prefix.to_lowercase())
    } else {
        value.starts_with(prefix)
    }
}

fn local_transport_wildcard_query_matches(
    value: &str,
    pattern: &str,
    case_insensitive: bool,
) -> bool {
    if case_insensitive {
        wildcard_match(&pattern.to_lowercase(), &value.to_lowercase())
    } else {
        wildcard_match(pattern, value)
    }
}

fn local_transport_json_query_matches(source: &Value, id: &str, query: &Value) -> bool {
    if let Some(inner) = query.get("query") {
        return local_transport_json_query_matches(source, id, inner);
    }
    if query.get("match_all").is_some() {
        return true;
    }
    if query.get("match_none").is_some() {
        return false;
    }
    if let Some(bool_query) = query.get("bool").and_then(Value::as_object) {
        return local_transport_json_bool_query_matches(source, id, bool_query);
    }
    if let Some(term_query) = query.get("term").and_then(Value::as_object) {
        return local_transport_json_term_query_matches(source, id, term_query);
    }
    if let Some(terms_query) = query.get("terms").and_then(Value::as_object) {
        return local_transport_json_terms_query_matches(source, id, terms_query);
    }
    if let Some(range_query) = query.get("range").and_then(Value::as_object) {
        return local_transport_json_range_query_matches(source, id, range_query);
    }
    if let Some(match_query) = query.get("match").and_then(Value::as_object) {
        return local_transport_json_match_query_matches(source, match_query);
    }
    if let Some(match_phrase_query) = query.get("match_phrase").and_then(Value::as_object) {
        return local_transport_json_phrase_query_matches(source, match_phrase_query, false);
    }
    if let Some(match_phrase_prefix_query) =
        query.get("match_phrase_prefix").and_then(Value::as_object)
    {
        return local_transport_json_phrase_query_matches(source, match_phrase_prefix_query, true);
    }
    if let Some(query_string) = query.get("query_string").and_then(Value::as_object) {
        return local_transport_json_text_query_matches(source, query_string, false);
    }
    if let Some(simple_query_string) = query.get("simple_query_string").and_then(Value::as_object) {
        return local_transport_json_text_query_matches(source, simple_query_string, true);
    }
    if let Some(exists_query) = query.get("exists").and_then(Value::as_object) {
        let field = exists_query
            .get("field")
            .and_then(Value::as_str)
            .unwrap_or_default();
        return field == "_id" || lookup_transport_source_value(source, field).is_some();
    }
    if let Some(ids_query) = query.get("ids").and_then(Value::as_object) {
        return ids_query
            .get("values")
            .or_else(|| ids_query.get("ids"))
            .and_then(Value::as_array)
            .is_some_and(|values| {
                values
                    .iter()
                    .any(|candidate| candidate.as_str() == Some(id))
            });
    }
    if let Some(prefix_query) = query.get("prefix").and_then(Value::as_object) {
        return local_transport_json_prefix_query_matches(source, id, prefix_query);
    }
    if let Some(wildcard_query) = query.get("wildcard").and_then(Value::as_object) {
        return local_transport_json_wildcard_query_matches(source, id, wildcard_query);
    }
    if let Some(regexp_query) = query.get("regexp").and_then(Value::as_object) {
        return local_transport_json_regexp_query_matches(source, id, regexp_query);
    }
    if let Some(fuzzy_query) = query.get("fuzzy").and_then(Value::as_object) {
        return local_transport_json_fuzzy_query_matches(source, id, fuzzy_query);
    }
    if let Some(terms_set_query) = query.get("terms_set").and_then(Value::as_object) {
        return local_transport_json_terms_set_query_matches(source, id, terms_set_query);
    }
    if let Some(geo_distance_query) = query.get("geo_distance").and_then(Value::as_object) {
        return local_transport_json_geo_distance_query_matches(source, geo_distance_query);
    }
    if let Some(nested_query) = query.get("nested").and_then(Value::as_object) {
        return local_transport_json_nested_query_matches(source, id, nested_query);
    }
    if let Some(constant_score_query) = query.get("constant_score").and_then(Value::as_object) {
        return constant_score_query
            .get("filter")
            .or_else(|| constant_score_query.get("query"))
            .is_some_and(|inner| local_transport_json_query_matches(source, id, inner));
    }
    if let Some(dis_max_query) = query.get("dis_max").and_then(Value::as_object) {
        return dis_max_query
            .get("queries")
            .and_then(Value::as_array)
            .is_some_and(|queries| {
                queries
                    .iter()
                    .any(|inner| local_transport_json_query_matches(source, id, inner))
            });
    }
    if let Some(boosting_query) = query.get("boosting").and_then(Value::as_object) {
        return boosting_query
            .get("positive")
            .is_some_and(|inner| local_transport_json_query_matches(source, id, inner));
    }
    if let Some(function_score_query) = query.get("function_score").and_then(Value::as_object) {
        return function_score_query.get("query").map_or(true, |inner| {
            local_transport_json_query_matches(source, id, inner)
        });
    }
    if let Some(script_score_query) = query.get("script_score").and_then(Value::as_object) {
        return script_score_query
            .get("query")
            .is_some_and(|inner| local_transport_json_query_matches(source, id, inner));
    }
    if query.get("span_term").is_some()
        || query.get("span_or").is_some()
        || query.get("span_multi").is_some()
        || query.get("span_near").is_some()
        || query.get("field_masking_span").is_some()
    {
        return local_transport_json_span_query_matches(source, id, query);
    }
    false
}

fn local_transport_json_bool_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    if json_query_clauses(query.get("must"))
        .into_iter()
        .any(|clause| !local_transport_json_query_matches(source, id, clause))
    {
        return false;
    }
    if json_query_clauses(query.get("filter"))
        .into_iter()
        .any(|clause| !local_transport_json_query_matches(source, id, clause))
    {
        return false;
    }
    if json_query_clauses(query.get("must_not"))
        .into_iter()
        .any(|clause| local_transport_json_query_matches(source, id, clause))
    {
        return false;
    }
    let should = json_query_clauses(query.get("should"));
    if should.is_empty() {
        return true;
    }
    let should_matches = should
        .iter()
        .filter(|clause| local_transport_json_query_matches(source, id, clause))
        .count();
    let minimum_should_match = query
        .get("minimum_should_match")
        .and_then(|value| {
            value
                .as_u64()
                .or_else(|| value.as_str().and_then(|text| text.parse::<u64>().ok()))
        })
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or_else(|| {
            usize::from(
                !should.is_empty()
                    && json_query_clauses(query.get("must")).is_empty()
                    && json_query_clauses(query.get("filter")).is_empty(),
            )
        });
    should_matches >= minimum_should_match.min(should.len())
}

fn json_query_clauses(value: Option<&Value>) -> Vec<&Value> {
    match value {
        Some(Value::Array(values)) => values.iter().collect(),
        Some(value) => vec![value],
        None => Vec::new(),
    }
}

fn local_transport_json_term_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some((field, expected)) = query.iter().next() else {
        return false;
    };
    let expected = expected.get("value").unwrap_or(expected);
    if field == "_id" {
        return value_matches_transport_term(&Value::String(id.to_string()), expected);
    }
    lookup_transport_source_value(source, field)
        .is_some_and(|value| transport_actual_matches_term(value, expected))
}

fn local_transport_json_terms_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some((field, expected)) = query.iter().next() else {
        return false;
    };
    let Some(values) = expected
        .as_array()
        .or_else(|| expected.get("terms").and_then(Value::as_array))
    else {
        return false;
    };
    if field == "_id" {
        let actual = Value::String(id.to_string());
        return values
            .iter()
            .any(|expected| value_matches_transport_term(&actual, expected));
    }
    lookup_transport_source_value(source, field)
        .is_some_and(|actual| transport_actual_matches_any_term(actual, values))
}

