fn local_transport_json_fuzzy_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some((field, expected)) = query.iter().next() else {
        return false;
    };
    let expected_value = expected
        .as_str()
        .or_else(|| expected.get("value").and_then(Value::as_str))
        .unwrap_or_default();
    let fuzziness = expected
        .get("fuzziness")
        .and_then(|value| {
            value
                .as_u64()
                .and_then(|value| usize::try_from(value).ok())
                .or_else(|| {
                    value.as_str().map(|value| {
                        if value.eq_ignore_ascii_case("AUTO") {
                            auto_transport_fuzziness(expected_value)
                        } else {
                            value
                                .parse::<usize>()
                                .unwrap_or_else(|_| auto_transport_fuzziness(expected_value))
                        }
                    })
                })
        })
        .unwrap_or_else(|| auto_transport_fuzziness(expected_value));
    let value = if field == "_id" {
        Some(Value::String(id.to_string()))
    } else {
        lookup_transport_source_value(source, field).cloned()
    };
    value.is_some_and(|value| {
        transport_any_actual_value_matches(&value, |candidate| {
            local_transport_value_matches_fuzzy(candidate, expected_value, fuzziness)
        })
    })
}

fn local_transport_json_terms_set_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some((field, spec)) = query.iter().next() else {
        return false;
    };
    let Some(terms) = spec.get("terms").and_then(Value::as_array) else {
        return false;
    };
    let minimum = spec
        .get("minimum_should_match")
        .and_then(|value| {
            value
                .as_u64()
                .or_else(|| value.as_str().and_then(|text| text.parse::<u64>().ok()))
        })
        .or_else(|| {
            spec.get("minimum_should_match_script")
                .and_then(|script| script.get("source"))
                .and_then(|value| {
                    value
                        .as_u64()
                        .or_else(|| value.as_str().and_then(|text| text.parse::<u64>().ok()))
                })
        })
        .and_then(|value| usize::try_from(value).ok())
        .unwrap_or(terms.len());
    if minimum == 0 {
        return false;
    }
    let actual = if field == "_id" {
        Some(Value::String(id.to_string()))
    } else {
        lookup_transport_source_value(source, field).cloned()
    };
    actual.is_some_and(|actual| {
        terms
            .iter()
            .filter(|term| transport_actual_matches_term(&actual, term))
            .count()
            >= minimum
    })
}

fn local_transport_json_geo_distance_query_matches(
    source: &Value,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let max_distance = query
        .get("distance")
        .and_then(|value| {
            value
                .as_f64()
                .or_else(|| value.as_str().and_then(parse_transport_distance_meters))
        })
        .unwrap_or(0.0);
    let Some((field, point)) = query.iter().find(|(field, _)| {
        !matches!(
            field.as_str(),
            "distance" | "ignore_unmapped" | "validation_method" | "type" | "_name" | "boost"
        )
    }) else {
        return false;
    };
    let Some(expected_point) = parse_transport_geo_point_value(point) else {
        return false;
    };
    lookup_transport_source_value(source, field)
        .and_then(parse_transport_geo_point_value)
        .is_some_and(|actual_point| {
            haversine_transport_distance_meters(actual_point, expected_point) <= max_distance
        })
}

fn parse_transport_distance_meters(raw: &str) -> Option<f64> {
    let trimmed = raw.trim();
    let number_len = trimmed
        .char_indices()
        .take_while(|(_, ch)| ch.is_ascii_digit() || matches!(ch, '.' | '+' | '-'))
        .map(|(index, ch)| index + ch.len_utf8())
        .last()?;
    let value = trimmed[..number_len].parse::<f64>().ok()?;
    let unit = trimmed[number_len..].trim().to_ascii_lowercase();
    let multiplier = match unit.as_str() {
        "" | "m" | "meter" | "meters" => 1.0,
        "km" | "kilometer" | "kilometers" => 1_000.0,
        "cm" | "centimeter" | "centimeters" => 0.01,
        "mm" | "millimeter" | "millimeters" => 0.001,
        "mi" | "mile" | "miles" => 1_609.344,
        "yd" | "yard" | "yards" => 0.9144,
        "ft" | "feet" | "foot" => 0.3048,
        "in" | "inch" | "inches" => 0.0254,
        "nmi" | "nauticalmile" | "nauticalmiles" => 1_852.0,
        _ => return None,
    };
    Some(value * multiplier)
}

fn local_transport_json_nested_query_matches(
    source: &Value,
    id: &str,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some(path) = query.get("path").and_then(Value::as_str) else {
        return false;
    };
    let Some(inner_query) = query.get("query") else {
        return false;
    };
    let Some(nested_value) = lookup_transport_source_value(source, path) else {
        return query
            .get("ignore_unmapped")
            .and_then(Value::as_bool)
            .unwrap_or(false);
    };
    match nested_value {
        Value::Array(values) => values
            .iter()
            .any(|value| local_transport_json_query_matches(value, id, inner_query)),
        value => local_transport_json_query_matches(value, id, inner_query),
    }
}

fn local_transport_json_span_query_matches(source: &Value, id: &str, query: &Value) -> bool {
    if let Some(span_term) = query.get("span_term").and_then(Value::as_object) {
        return local_transport_json_term_query_matches(source, id, span_term);
    }
    if let Some(span_or) = query.get("span_or").and_then(Value::as_object) {
        return span_or
            .get("clauses")
            .and_then(Value::as_array)
            .is_some_and(|clauses| {
                clauses
                    .iter()
                    .any(|clause| local_transport_json_span_query_matches(source, id, clause))
            });
    }
    if let Some(span_multi) = query.get("span_multi").and_then(Value::as_object) {
        return span_multi
            .get("match")
            .is_some_and(|inner| local_transport_json_query_matches(source, id, inner));
    }
    if let Some(span_near) = query.get("span_near").and_then(Value::as_object) {
        return local_transport_json_span_near_query_matches(source, span_near);
    }
    if let Some(field_masking_span) = query.get("field_masking_span").and_then(Value::as_object) {
        return field_masking_span
            .get("query")
            .is_some_and(|inner| local_transport_json_span_query_matches(source, id, inner));
    }
    false
}

fn local_transport_json_span_near_query_matches(
    source: &Value,
    query: &serde_json::Map<String, Value>,
) -> bool {
    let Some(clauses) = query.get("clauses").and_then(Value::as_array) else {
        return false;
    };
    let mut extracted = Vec::new();
    for clause in clauses {
        let Some(extracted_clause) = extract_transport_json_span_clause(source, clause) else {
            return false;
        };
        extracted.push(extracted_clause);
    }
    let Some((field, _)) = extracted.first() else {
        return false;
    };
    if extracted
        .iter()
        .any(|(candidate_field, _)| candidate_field != field)
    {
        return false;
    }
    let Some(tokens) = lookup_transport_source_value(source, field)
        .and_then(Value::as_str)
        .map(tokenize_transport_search_text)
    else {
        return false;
    };
    if tokens.is_empty() {
        return false;
    }
    let specs = extracted
        .into_iter()
        .map(|(_, values)| values)
        .collect::<Vec<_>>();
    let in_order = query
        .get("in_order")
        .and_then(Value::as_bool)
        .unwrap_or(false);
    let slop = query.get("slop").and_then(Value::as_u64).unwrap_or(0) as usize;
    if in_order {
        let Some((first_terms, rest)) = first_transport_span_near_term_clause(&specs) else {
            return false;
        };
        for start_position in 0..tokens.len() {
            if !first_terms
                .iter()
                .any(|term| term == &tokens[start_position])
            {
                continue;
            }
            let mut previous_position = start_position;
            let mut matched = true;
            for spec in rest {
                let TransportSpanClause::Terms(accepted_terms) = spec;
                let start = previous_position + 1;
                let mut matched_position = None;
                for (index, token) in tokens.iter().enumerate().skip(start) {
                    if accepted_terms.iter().any(|term| term == token) {
                        matched_position = Some(index);
                        break;
                    }
                }
                let Some(position) = matched_position else {
                    matched = false;
                    break;
                };
                if position.saturating_sub(previous_position + 1) > slop {
                    matched = false;
                    break;
                }
                previous_position = position;
            }
            if matched {
                return true;
            }
        }
        return false;
    }
    specs.iter().all(|spec| {
        let TransportSpanClause::Terms(accepted_terms) = spec;
        tokens
            .iter()
            .any(|token| accepted_terms.iter().any(|term| term == token))
    })
}

fn extract_transport_json_span_clause(
    source: &Value,
    clause: &Value,
) -> Option<(String, TransportSpanClause)> {
    if let Some(span_term) = clause.get("span_term").and_then(Value::as_object) {
        let (field, value) = span_term.iter().next()?;
        return Some((
            field.clone(),
            TransportSpanClause::Terms(vec![value.as_str()?.to_ascii_lowercase()]),
        ));
    }
    if let Some(span_multi) = clause.get("span_multi").and_then(Value::as_object) {
        let prefix = span_multi.get("match")?.get("prefix")?.as_object()?;
        let (field, expected) = prefix.iter().next()?;
        let expected = expected
            .as_str()
            .or_else(|| expected.get("value").and_then(Value::as_str))?
            .to_ascii_lowercase();
        let tokens = lookup_transport_source_value(source, field)
            .and_then(Value::as_str)
            .map(tokenize_transport_search_text)?;
        let accepted = tokens
            .into_iter()
            .filter(|token| token.starts_with(&expected))
            .collect::<Vec<_>>();
        return Some((field.clone(), TransportSpanClause::Terms(accepted)));
    }
    None
}

fn local_transport_regexp_query_matches(
    value: &str,
    pattern: &str,
    case_insensitive: bool,
) -> bool {
    let candidate = if case_insensitive {
        value.to_ascii_lowercase()
    } else {
        value.to_string()
    };
    let pattern = if case_insensitive {
        pattern.to_ascii_lowercase()
    } else {
        pattern.to_string()
    };
    bounded_transport_regexp_match(pattern.as_bytes(), candidate.as_bytes())
}

fn bounded_transport_regexp_match(pattern: &[u8], candidate: &[u8]) -> bool {
    fn recurse(pattern: &[u8], candidate: &[u8]) -> bool {
        if pattern.is_empty() {
            return candidate.is_empty();
        }
        let char_matches =
            !candidate.is_empty() && (pattern[0] == b'.' || pattern[0] == candidate[0]);
        if pattern.len() >= 2 && pattern[1] == b'*' {
            return recurse(&pattern[2..], candidate)
                || (char_matches && recurse(pattern, &candidate[1..]));
        }
        char_matches && recurse(&pattern[1..], &candidate[1..])
    }
    recurse(pattern, candidate)
}

fn local_transport_value_matches_fuzzy(
    candidate: &Value,
    expected: &str,
    fuzziness: usize,
) -> bool {
    let Some(candidate_text) = candidate.as_str() else {
        return false;
    };
    let expected = expected.to_ascii_lowercase();
    tokenize_transport_search_text(candidate_text)
        .into_iter()
        .any(|token| levenshtein_transport_distance(&token, &expected) <= fuzziness)
}

fn local_transport_fuzziness(
    fuzziness: &os_transport::action::OpenSearchFuzzinessWire,
    query_value: &str,
) -> usize {
    if fuzziness.value == "AUTO" {
        return auto_transport_fuzziness(query_value);
    }
    fuzziness
        .value
        .parse::<usize>()
        .unwrap_or_else(|_| auto_transport_fuzziness(query_value))
}

fn auto_transport_fuzziness(query_value: &str) -> usize {
    match query_value.chars().count() {
        0..=2 => 0,
        3..=5 => 1,
        _ => 2,
    }
}

fn levenshtein_transport_distance(left: &str, right: &str) -> usize {
    let left_chars = left.chars().collect::<Vec<_>>();
    let right_chars = right.chars().collect::<Vec<_>>();
    let mut prev = (0..=right_chars.len()).collect::<Vec<_>>();
    let mut curr = vec![0; right_chars.len() + 1];
    for (i, left_char) in left_chars.iter().enumerate() {
        curr[0] = i + 1;
        for (j, right_char) in right_chars.iter().enumerate() {
            let cost = usize::from(left_char != right_char);
            curr[j + 1] = (curr[j] + 1).min(prev[j + 1] + 1).min(prev[j] + cost);
        }
        std::mem::swap(&mut prev, &mut curr);
    }
    prev[right_chars.len()]
}

fn local_transport_terms_set_query_matches(
    actual: &Value,
    query: &os_transport::action::OpenSearchTermsSetQueryBuilderWire,
) -> bool {
    let Some(minimum) = query
        .minimum_should_match_script
        .as_ref()
        .and_then(|script| script.source.parse::<usize>().ok())
    else {
        return false;
    };
    if minimum == 0 {
        return false;
    }
    let matched_terms = query
        .values
        .iter()
        .filter(|term| match actual {
            Value::Array(values) => values
                .iter()
                .any(|value| value_matches_transport_term(value, term)),
            _ => value_matches_transport_term(actual, term),
        })
        .count();
    matched_terms >= minimum
}

fn parse_transport_geo_point_value(value: &Value) -> Option<(f64, f64)> {
    if let Some(object) = value.as_object() {
        return Some((object.get("lat")?.as_f64()?, object.get("lon")?.as_f64()?));
    }
    let array = value.as_array()?;
    if array.len() != 2 {
        return None;
    }
    Some((array[1].as_f64()?, array[0].as_f64()?))
}

fn haversine_transport_distance_meters(left: (f64, f64), right: (f64, f64)) -> f64 {
    let earth_radius_m = 6_371_000.0_f64;
    let (left_lat, left_lon) = (left.0.to_radians(), left.1.to_radians());
    let (right_lat, right_lon) = (right.0.to_radians(), right.1.to_radians());
    let delta_lat = right_lat - left_lat;
    let delta_lon = right_lon - left_lon;
    let a = (delta_lat / 2.0).sin().powi(2)
        + left_lat.cos() * right_lat.cos() * (delta_lon / 2.0).sin().powi(2);
    let c = 2.0 * a.sqrt().atan2((1.0 - a).sqrt());
    earth_radius_m * c
}

fn local_transport_text_query_matches(
    haystacks: &[String],
    query_text: &str,
    operator: os_transport::action::OpenSearchMatchOperatorWire,
) -> bool {
    local_transport_match_query_matches(haystacks, query_text, operator)
}

fn local_transport_query_string_matches(
    haystacks: &[String],
    query_text: &str,
    operator: os_transport::action::OpenSearchMatchOperatorWire,
    simple_syntax: bool,
) -> bool {
    let explicit_or = if simple_syntax && query_text.contains('|') {
        Some(
            query_text
                .split('|')
                .map(str::trim)
                .filter(|part| !part.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>(),
        )
    } else if query_text.contains(" OR ") {
        Some(
            query_text
                .split(" OR ")
                .map(str::trim)
                .filter(|part| !part.is_empty())
                .map(str::to_string)
                .collect::<Vec<_>>(),
        )
    } else {
        None
    };
    if let Some(disjuncts) = explicit_or {
        return disjuncts.iter().any(|disjunct| {
            local_transport_match_query_matches(
                haystacks,
                disjunct,
                os_transport::action::OpenSearchMatchOperatorWire::And,
            )
        });
    }
    if query_text.contains(" AND ") {
        return local_transport_match_query_matches(
            haystacks,
            query_text,
            os_transport::action::OpenSearchMatchOperatorWire::And,
        );
    }
    local_transport_match_query_matches(haystacks, query_text, operator)
}

fn local_transport_match_query_matches(
    haystacks: &[String],
    query_text: &str,
    operator: os_transport::action::OpenSearchMatchOperatorWire,
) -> bool {
    let terms = split_transport_query_terms(query_text);
    if terms.is_empty() {
        return false;
    }
    match operator {
        os_transport::action::OpenSearchMatchOperatorWire::And => terms
            .iter()
            .all(|term| score_transport_text_query_term(haystacks, term) > 0.0),
        os_transport::action::OpenSearchMatchOperatorWire::Or => terms
            .iter()
            .any(|term| score_transport_text_query_term(haystacks, term) > 0.0),
    }
}

fn local_transport_match_bool_prefix_matches(haystacks: &[String], query_text: &str) -> bool {
    let terms = split_transport_query_terms(query_text);
    let Some((last, required)) = terms.split_last() else {
        return false;
    };
    if required
        .iter()
        .any(|term| score_transport_text_query_term(haystacks, term) == 0.0)
    {
        return false;
    }
    let prefix = last.to_ascii_lowercase();
    haystacks.iter().any(|haystack| {
        haystack
            .split(|ch: char| !ch.is_ascii_alphanumeric())
            .filter(|token| !token.is_empty())
            .any(|token| token.to_ascii_lowercase().starts_with(&prefix))
    })
}

fn local_transport_span_near_query_matches(
    source: &Value,
    query: &os_transport::action::OpenSearchSpanNearQueryBuilderWire,
) -> bool {
    let mut extracted = Vec::new();
    for clause in &query.clauses {
        let Some(extracted_clause) = extract_transport_span_clause(source, clause) else {
            return false;
        };
        extracted.push(extracted_clause);
    }
    let Some((field, _)) = extracted.first() else {
        return false;
    };
    if extracted
        .iter()
        .any(|(candidate_field, _)| candidate_field != field)
    {
        return false;
    }
    let Some(tokens) = lookup_transport_source_value(source, field)
        .and_then(Value::as_str)
        .map(tokenize_transport_search_text)
    else {
        return false;
    };
    if tokens.is_empty() {
        return false;
    }
    let specs = extracted
        .into_iter()
        .map(|(_, values)| values)
        .collect::<Vec<_>>();
    if query.in_order {
        let Some((first_terms, rest)) = first_transport_span_near_term_clause(&specs) else {
            return false;
        };
        for start_position in 0..tokens.len() {
            if !first_terms
                .iter()
                .any(|term| term == &tokens[start_position])
            {
                continue;
            }
            let mut previous_position = start_position;
            let mut matched = true;
            for spec in rest {
                let TransportSpanClause::Terms(accepted_terms) = spec;
                let start = previous_position + 1;
                let mut matched_position = None;
                for (index, token) in tokens.iter().enumerate().skip(start) {
                    if accepted_terms.iter().any(|term| term == token) {
                        matched_position = Some(index);
                        break;
                    }
                }
                let Some(position) = matched_position else {
                    matched = false;
                    break;
                };
                let gap = position.saturating_sub(previous_position + 1);
                if gap > query.slop as usize {
                    matched = false;
                    break;
                }
                previous_position = position;
            }
            if matched {
                return true;
            }
        }
        return false;
    }
    specs.iter().all(|spec| {
        let TransportSpanClause::Terms(accepted_terms) = spec;
        tokens
            .iter()
            .any(|token| accepted_terms.iter().any(|term| term == token))
    })
}

#[derive(Clone, Debug, Eq, PartialEq)]
enum TransportSpanClause {
    Terms(Vec<String>),
}

fn extract_transport_span_clause(
    source: &Value,
    clause: &os_transport::action::OpenSearchQueryBuilderWire,
) -> Option<(String, TransportSpanClause)> {
    match clause {
        os_transport::action::OpenSearchQueryBuilderWire::SpanTerm(term) => Some((
            term.field_name.clone(),
            TransportSpanClause::Terms(vec![term.value.as_str()?.to_ascii_lowercase()]),
        )),
        os_transport::action::OpenSearchQueryBuilderWire::SpanMulti(query) => {
            let os_transport::action::OpenSearchQueryBuilderWire::Prefix(prefix) =
                query.query.as_ref()
            else {
                return None;
            };
            let expected = prefix.value.to_ascii_lowercase();
            let tokens = lookup_transport_source_value(source, &prefix.field_name)
                .and_then(Value::as_str)
                .map(tokenize_transport_search_text)?;
            let accepted = tokens
                .into_iter()
                .filter(|token| token.starts_with(&expected))
                .collect::<Vec<_>>();
            Some((
                prefix.field_name.clone(),
                TransportSpanClause::Terms(accepted),
            ))
        }
        _ => None,
    }
}

fn first_transport_span_near_term_clause(
    specs: &[TransportSpanClause],
) -> Option<(&[String], &[TransportSpanClause])> {
    let TransportSpanClause::Terms(terms) = specs.first()?;
    Some((terms.as_slice(), &specs[1..]))
}

fn score_transport_text_query_term(haystacks: &[String], term: &str) -> f64 {
    let phrase = term.trim_matches('"');
    let is_phrase = term.contains(' ') || term.starts_with('"') || term.ends_with('"');
    let mut best_score: f64 = 0.0;
    for haystack in haystacks {
        let candidate = Value::String(haystack.clone());
        let score = if is_phrase {
            if local_transport_value_matches_phrase(Some(&candidate), phrase, false) {
                phrase.split_whitespace().count().max(1) as f64
            } else {
                0.0
            }
        } else {
            score_transport_match_text(Some(&candidate), phrase)
        };
        best_score = best_score.max(score);
    }
    best_score
}

fn score_transport_match_text(candidate: Option<&Value>, expected: &str) -> f64 {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return 0.0;
    };
    let haystack = candidate_text.to_ascii_lowercase();
    let mut score = 0.0;
    for token in expected
        .split_whitespace()
        .map(|token| token.to_ascii_lowercase())
        .filter(|token| !token.is_empty())
    {
        if haystack.contains(&token) {
            score += 1.0;
        }
    }
    score
}

fn local_transport_value_matches_phrase(
    candidate: Option<&Value>,
    expected: &str,
    prefix_last_token: bool,
) -> bool {
    let Some(candidate_text) = candidate.and_then(Value::as_str) else {
        return false;
    };
    let candidate_tokens = tokenize_transport_search_text(candidate_text);
    let expected_tokens = tokenize_transport_search_text(expected);
    if expected_tokens.is_empty() || candidate_tokens.len() < expected_tokens.len() {
        return false;
    }
    for window in candidate_tokens.windows(expected_tokens.len()) {
        let mut matched = true;
        for (index, expected_token) in expected_tokens.iter().enumerate() {
            let candidate_token = &window[index];
            let token_matches = if prefix_last_token && index + 1 == expected_tokens.len() {
                candidate_token.starts_with(expected_token)
            } else {
                candidate_token == expected_token
            };
            if !token_matches {
                matched = false;
                break;
            }
        }
        if matched {
            return true;
        }
    }
    false
}

fn collect_transport_searchable_field_values(
    source: &Value,
    fields: Option<&[&str]>,
) -> Vec<String> {
    let Some(source_object) = source.as_object() else {
        return Vec::new();
    };
    if let Some(fields) = fields {
        return fields
            .iter()
            .filter_map(|field| lookup_transport_source_value(source, field))
            .flat_map(collect_transport_string_leaf_values)
            .collect();
    }
    source_object
        .values()
        .flat_map(collect_transport_string_leaf_values)
        .collect()
}

fn collect_transport_string_leaf_values(value: &Value) -> Vec<String> {
    match value {
        Value::String(text) => vec![text.to_string()],
        Value::Array(items) => items
            .iter()
            .flat_map(collect_transport_string_leaf_values)
            .collect(),
        Value::Object(object) => object
            .values()
            .flat_map(collect_transport_string_leaf_values)
            .collect(),
        _ => Vec::new(),
    }
}

fn split_transport_query_terms(query_text: &str) -> Vec<String> {
    let mut terms = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut chars = query_text.chars().peekable();
    while let Some(ch) = chars.next() {
        match ch {
            '"' => {
                in_quotes = !in_quotes;
            }
            ' ' if !in_quotes => {
                if !current.is_empty() {
                    if current != "AND" && current != "OR" {
                        terms.push(std::mem::take(&mut current));
                    } else {
                        current.clear();
                    }
                }
                while chars.peek().is_some_and(|next| *next == ' ') {
                    chars.next();
                }
            }
            _ => current.push(ch),
        }
    }
    if !current.is_empty() && current != "AND" && current != "OR" {
        terms.push(current);
    }
    terms
}

fn tokenize_transport_search_text(input: &str) -> Vec<String> {
    input
        .split(|character: char| !character.is_ascii_alphanumeric())
        .map(|token| token.to_ascii_lowercase())
        .filter(|token| !token.is_empty())
        .collect()
}

fn lookup_transport_source_value<'a>(source: &'a Value, field: &str) -> Option<&'a Value> {
    let mut current = source;
    for part in field.split('.') {
        current = current.as_object()?.get(part)?;
    }
    Some(current)
}

fn transport_any_actual_value_matches(actual: &Value, predicate: impl Fn(&Value) -> bool) -> bool {
    match actual {
        Value::Array(values) => values.iter().any(predicate),
        value => predicate(value),
    }
}

fn transport_any_actual_string_matches(actual: &Value, predicate: impl Fn(&str) -> bool) -> bool {
    match actual {
        Value::String(text) => predicate(text),
        Value::Array(values) => values.iter().filter_map(Value::as_str).any(predicate),
        _ => false,
    }
}

fn transport_actual_matches_any_term(actual: &Value, expected_values: &[Value]) -> bool {
    expected_values
        .iter()
        .any(|expected| transport_actual_matches_term(actual, expected))
}

fn transport_actual_matches_term(actual: &Value, expected: &Value) -> bool {
    match actual {
        Value::Array(values) => values
            .iter()
            .any(|value| value_matches_transport_term(value, expected)),
        _ => value_matches_transport_term(actual, expected),
    }
}

fn value_matches_transport_term(actual: &Value, expected: &Value) -> bool {
    if actual == expected {
        return true;
    }
    match (actual, expected) {
        (Value::Number(actual), Value::String(expected)) => actual.to_string() == *expected,
        (Value::String(actual), Value::Number(expected)) => *actual == expected.to_string(),
        _ => false,
    }
}

fn transport_index_metadata_is_hidden(index_body: &Value) -> bool {
    index_body["settings"]["index"]["hidden"]
        .as_str()
        .map(|value| value == "true")
        .or_else(|| index_body["settings"]["index"]["hidden"].as_bool())
        .unwrap_or(false)
}

fn wildcard_match(pattern: &str, candidate: &str) -> bool {
    if !pattern.contains('*') && !pattern.contains('?') {
        return pattern == candidate;
    }
    wildcard_match_inner(pattern.as_bytes(), candidate.as_bytes())
}

fn wildcard_match_inner(pattern: &[u8], candidate: &[u8]) -> bool {
    if pattern.is_empty() {
        return candidate.is_empty();
    }
    match pattern[0] {
        b'*' => {
            wildcard_match_inner(&pattern[1..], candidate)
                || (!candidate.is_empty() && wildcard_match_inner(pattern, &candidate[1..]))
        }
        b'?' => !candidate.is_empty() && wildcard_match_inner(&pattern[1..], &candidate[1..]),
        byte => {
            !candidate.is_empty()
                && candidate[0] == byte
                && wildcard_match_inner(&pattern[1..], &candidate[1..])
        }
    }
}

fn time_value_wire_to_millis(time_value: &os_transport::action::TimeValueWire) -> i64 {
    match time_value.time_unit_ordinal {
        0 => time_value.duration / 1_000_000,
        1 => time_value.duration / 1_000,
        2 => time_value.duration,
        3 => time_value.duration.saturating_mul(1_000),
        4 => time_value.duration.saturating_mul(60_000),
        5 => time_value.duration.saturating_mul(3_600_000),
        6 => time_value.duration.saturating_mul(86_400_000),
        _ => time_value.duration,
    }
}

fn transport_positive_keep_alive_millis(keep_alive_millis: i64) -> u64 {
    if keep_alive_millis <= 0 {
        DEV_TRANSPORT_NON_POSITIVE_PIT_KEEP_ALIVE_MILLIS
    } else {
        u64::try_from(keep_alive_millis).unwrap_or(u64::MAX)
    }
}

fn u128_to_i64_saturating(value: u128) -> i64 {
    i64::try_from(value).unwrap_or(i64::MAX)
}

fn u64_to_i64_saturating(value: u64) -> i64 {
    i64::try_from(value).unwrap_or(i64::MAX)
}

fn usize_to_i32_saturating(value: usize) -> i32 {
    i32::try_from(value).unwrap_or(i32::MAX)
}

fn create_pit_request_supports_local_lifecycle_subset(body: &[u8]) -> bool {
    decode_create_pit_request_from_transport_body(body)
        .filter(|request| {
            time_value_wire_to_millis(&request.keep_alive)
                <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS
        })
        .filter(|request| request.allow_partial_pit_creation.is_some())
        .and_then(|request| request.validate_supported_subset().ok())
        .is_some()
}

fn build_local_can_match_response(request_id: i64, header_version_id: u32, body: &[u8]) -> Vec<u8> {
    let Some(request) = decode_can_match_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let Ok(mut can_match) = request.can_match_local_subset_result() else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let bindings = dev_transport_pit_bindings();
    if !can_match_request_context_admitted(bindings, &request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if request.reader_id.is_none() && local_transport_shard_has_refresh_pending(bindings, &request)
    {
        can_match = true;
    }
    os_transport::action::build_opensearch_can_match_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &os_transport::action::OpenSearchCanMatchResponseWire::new(can_match),
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn can_match_request_supports_local_execution_subset(body: &[u8]) -> bool {
    decode_can_match_request_from_transport_body(body)
        .filter(|request| request.reject_unsupported_execution().is_ok())
        .is_some_and(|request| {
            can_match_request_context_admitted(dev_transport_pit_bindings(), &request)
        })
}

fn dfs_phase_request_supports_local_execution_subset(body: &[u8]) -> bool {
    decode_dfs_phase_request_from_transport_body(body)
        .filter(|request| request.reject_unsupported_execution().is_ok())
        .filter(|request| request.reader_id.is_none())
        .filter(dfs_phase_request_has_no_term_statistics)
        .filter(|request| {
            create_reader_context_shard_admission(dev_transport_pit_bindings(), &request.shard_id)
                == CreateReaderContextShardAdmission::Accepted
        })
        .is_some_and(|_| can_allocate_reader_context(dev_transport_pit_bindings()))
}

fn dfs_phase_request_has_no_term_statistics(
    request: &os_transport::action::OpenSearchShardSearchRequestWire,
) -> bool {
    request
        .source
        .as_ref()
        .and_then(|source| source.query.as_ref())
        .map_or(true, |query| {
            matches!(
                query,
                os_transport::action::OpenSearchQueryBuilderWire::MatchAll(_)
                    | os_transport::action::OpenSearchQueryBuilderWire::MatchNone(_)
            )
        })
}

fn can_match_request_has_missing_reader_context(body: &[u8]) -> bool {
    decode_can_match_request_from_transport_body(body)
        .filter(|request| request.reject_unsupported_execution().is_ok())
        .and_then(|request| request.reader_id)
        .is_some_and(|reader_id| !reader_context_exists(&reader_id))
}

fn can_match_request_exceeds_local_reader_keep_alive_limit(body: &[u8]) -> bool {
    decode_can_match_request_from_transport_body(body)
        .filter(|request| request.reject_unsupported_execution().is_ok())
        .filter(|request| {
            request
                .reader_id
                .as_ref()
                .is_some_and(reader_context_exists)
        })
        .and_then(|request| request.keep_alive)
        .is_some_and(|keep_alive| {
            time_value_wire_to_millis(&keep_alive) > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS
        })
}

fn query_id_request_has_missing_reader_context(body: &[u8]) -> bool {
    decode_query_id_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .is_some_and(|request| !reader_context_exists(&request.context_id))
}

fn build_can_match_missing_reader_context_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_can_match_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let Some(reader_id) = request.reader_id else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    build_missing_search_context_error_response(request_id, header_version_id, &reader_id)
}

fn build_local_dfs_phase_response(request_id: i64, header_version_id: u32, body: &[u8]) -> Vec<u8> {
    let Some(request) = decode_dfs_phase_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if request.reject_unsupported_execution().is_err() || request.reader_id.is_some() {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if !dfs_phase_request_has_no_term_statistics(&request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if create_reader_context_shard_admission(dev_transport_pit_bindings(), &request.shard_id)
        != CreateReaderContextShardAdmission::Accepted
    {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if !can_allocate_reader_context(dev_transport_pit_bindings()) {
        return build_empty_transport_response(request_id, header_version_id);
    }

    let bindings = dev_transport_pit_bindings();
    let documents = transport_pit_document_snapshot(
        bindings,
        std::slice::from_ref(&request.shard_id.index_name),
        None,
    );
    let max_doc = i32::try_from(documents.len()).unwrap_or(i32::MAX);
    let keep_alive_millis = DEV_TRANSPORT_NON_POSITIVE_PIT_KEEP_ALIVE_MILLIS;
    let now_millis = now_epoch_ms();
    let context_id = {
        let mut next_id = bindings
            .next_id
            .lock()
            .expect("dev transport next PIT id lock poisoned");
        *next_id += 1;
        let context_id = os_transport::action::OpenSearchShardSearchContextIdWire::new(
            format!("steelsearch-dfs-reader-{}", *next_id),
            i64::try_from(*next_id).unwrap_or(i64::MAX),
        );
        let reader_context = DevTransportReaderContext {
            shard_id: request.shard_id.clone(),
            documents,
            keep_alive_millis,
            expires_at_millis: transport_pit_expires_at_millis(now_millis, keep_alive_millis),
            pit_id: None,
            creation_time_millis: None,
        };
        bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .insert(reader_context_key(&context_id), reader_context);
        context_id
    };
    let response = os_transport::action::OpenSearchDfsSearchResultWire::empty(context_id, max_doc);
    os_transport::action::build_opensearch_dfs_phase_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn build_query_id_missing_reader_context_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_query_id_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    build_missing_search_context_error_response(request_id, header_version_id, &request.context_id)
}

fn query_id_request_supports_local_execution_subset(body: &[u8]) -> bool {
    let Some(request) = decode_query_id_request_from_transport_body(body) else {
        return false;
    };
    if request.validate_supported_subset().is_err()
        || !request.dfs.term_statistics.is_empty()
        || !request.dfs.field_statistics.is_empty()
    {
        return false;
    }
    let Some(reader_context) = reader_context_for_query_id_request(&request) else {
        return false;
    };
    let Some(shard_search_request) = request.shard_search_request.as_ref() else {
        return true;
    };
    reader_context.shard_id == shard_search_request.shard_id
        && shard_search_request.reject_unsupported_execution().is_ok()
        && dfs_phase_request_has_no_term_statistics(shard_search_request)
}

fn reader_context_for_query_id_request(
    request: &os_transport::action::OpenSearchQuerySearchRequestWire,
) -> Option<DevTransportReaderContext> {
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    let key = reader_context_lookup_key_for_request(&reader_contexts, &request.context_id)?;
    reader_contexts.get(&key).cloned()
}

fn query_id_total_hits_for_reader_context(
    request: &os_transport::action::OpenSearchQuerySearchRequestWire,
    reader_context: &DevTransportReaderContext,
) -> i64 {
    i64::try_from(query_id_score_doc_ids_for_reader_context(request, reader_context).len())
        .unwrap_or(i64::MAX)
}

fn query_id_score_doc_ids_for_reader_context(
    request: &os_transport::action::OpenSearchQuerySearchRequestWire,
    reader_context: &DevTransportReaderContext,
) -> Vec<i32> {
    let query = request
        .shard_search_request
        .as_ref()
        .and_then(|request| request.source.as_ref())
        .and_then(|source| source.query.as_ref());
    match query {
        Some(os_transport::action::OpenSearchQueryBuilderWire::MatchNone(_)) => Vec::new(),
        _ => reader_context
            .documents
            .iter()
            .enumerate()
            .filter_map(|(doc_id, (_, record))| {
                record
                    .refreshed
                    .then(|| i32::try_from(doc_id).unwrap_or(i32::MAX))
            })
            .collect(),
    }
}

fn build_local_query_id_phase_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> Vec<u8> {
    let Some(request) = decode_query_id_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let Some(reader_context) = reader_context_for_query_id_request(&request) else {
        return build_missing_search_context_error_response(
            request_id,
            header_version_id,
            &request.context_id,
        );
    };
    if !query_id_request_supports_local_execution_subset(body) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let total_hits = query_id_total_hits_for_reader_context(&request, &reader_context);
    let score_doc_ids = query_id_score_doc_ids_for_reader_context(&request, &reader_context);
    let Some(payload) = build_java_query_phase_result_body(
        transport_identity,
        &reader_context.shard_id.index_name,
        &reader_context.shard_id.index_uuid,
        reader_context.shard_id.shard_id,
        &request.context_id,
        total_hits,
        &score_doc_ids,
        false,
    ) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    build_transport_response_frame(request_id, header_version_id, payload)
}

