fn build_local_create_reader_context_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_create_reader_context_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if request.validate_supported_subset().is_err() {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if time_value_wire_to_millis(&request.keep_alive) > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS {
        return build_empty_transport_response(request_id, header_version_id);
    }
    match create_reader_context_shard_admission(dev_transport_pit_bindings(), &request.shard_id) {
        CreateReaderContextShardAdmission::Accepted => {}
        CreateReaderContextShardAdmission::MissingIndex => {
            return build_create_reader_context_index_not_found_error_response(
                request_id,
                header_version_id,
                &request.shard_id,
            );
        }
        CreateReaderContextShardAdmission::MissingShard => {
            return build_create_reader_context_shard_not_found_error_response(
                request_id,
                header_version_id,
                &request.shard_id,
            );
        }
    }
    if !can_allocate_reader_context(dev_transport_pit_bindings()) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let keep_alive_millis =
        transport_positive_keep_alive_millis(time_value_wire_to_millis(&request.keep_alive));
    let now_millis = now_epoch_ms();
    let context_id = {
        let bindings = dev_transport_pit_bindings();
        let mut next_id = bindings
            .next_id
            .lock()
            .expect("dev transport next PIT id lock poisoned");
        *next_id += 1;
        let context_id = os_transport::action::OpenSearchShardSearchContextIdWire::new(
            format!("steelsearch-pit-reader-{}", *next_id),
            i64::try_from(*next_id).unwrap_or(i64::MAX),
        );
        let reader_context = DevTransportReaderContext {
            shard_id: request.shard_id.clone(),
            documents: transport_pit_document_snapshot(
                bindings,
                std::slice::from_ref(&request.shard_id.index_name),
                None,
            ),
            keep_alive_millis,
            expires_at_millis: transport_pit_expires_at_millis(now_millis, keep_alive_millis),
            pit_id: None,
            creation_time_millis: None,
        };
        bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .insert(reader_context_key(&context_id), reader_context);
        context_id
    };
    os_transport::action::build_opensearch_create_reader_context_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &os_transport::action::OpenSearchCreateReaderContextResponseWire::new(context_id),
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn create_reader_context_request_supports_local_subset(body: &[u8]) -> bool {
    decode_create_reader_context_request_from_transport_body(body)
        .filter(|request| {
            time_value_wire_to_millis(&request.keep_alive)
                <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS
        })
        .filter(|request| {
            create_reader_context_shard_admission(dev_transport_pit_bindings(), &request.shard_id)
                == CreateReaderContextShardAdmission::Accepted
        })
        .filter(|_| can_allocate_reader_context(dev_transport_pit_bindings()))
        .and_then(|request| request.validate_supported_subset().ok())
        .is_some()
}

