fn build_create_reader_context_too_many_open_contexts_error_response(
    request_id: i64,
    header_version_id: u32,
) -> Vec<u8> {
    let reason = format!(
        "Trying to create too many Point In Time contexts. Must be less than or equal to: [{}]. This limit can be set by changing the [search.max_open_pit_context] setting.",
        DEV_TRANSPORT_MAX_OPEN_PIT_CONTEXTS
    );
    let mut output = StreamOutput::new();
    os_transport::error::write_rejected_execution_exception(&mut output, Some(&reason));
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn build_create_reader_context_index_not_found_error_response(
    request_id: i64,
    header_version_id: u32,
    shard_id: &os_transport::action::OpenSearchShardIdWire,
) -> Vec<u8> {
    let mut output = StreamOutput::new();
    os_transport::error::write_index_not_found_exception(&mut output, &shard_id.index_name);
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn build_create_reader_context_shard_not_found_error_response(
    request_id: i64,
    header_version_id: u32,
    shard_id: &os_transport::action::OpenSearchShardIdWire,
) -> Vec<u8> {
    let index_uuid = if shard_id.index_uuid.is_empty() {
        "_na_"
    } else {
        &shard_id.index_uuid
    };
    let mut output = StreamOutput::new();
    os_transport::error::write_shard_not_found_exception(
        &mut output,
        &shard_id.index_name,
        index_uuid,
        shard_id.shard_id,
    );
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn decode_create_reader_context_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchCreateReaderContextRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_create_reader_context_request_message(&message).ok()
}

fn create_reader_context_shard_admission(
    bindings: &DevTransportPitBindings,
    shard_id: &os_transport::action::OpenSearchShardIdWire,
) -> CreateReaderContextShardAdmission {
    let manifest = bindings
        .metadata_manifest
        .lock()
        .expect("dev transport metadata manifest lock poisoned");
    if let Some(index_body) = manifest["indices"].get(&shard_id.index_name) {
        if index_body["state"]
            .as_str()
            .is_some_and(|state| state == "close")
        {
            return CreateReaderContextShardAdmission::MissingIndex;
        }
        if let Some(index_uuid) = transport_manifest_index_uuid(index_body) {
            if shard_id.index_uuid != "_na_" && shard_id.index_uuid != index_uuid {
                return CreateReaderContextShardAdmission::MissingIndex;
            }
        }
        let settings = &index_body["settings"];
        let shard_count = settings["index"]["number_of_shards"]
            .as_str()
            .or_else(|| settings["number_of_shards"].as_str())
            .and_then(|value| value.parse::<i32>().ok())
            .unwrap_or(1);
        return if shard_id.shard_id >= 0 && shard_id.shard_id < shard_count {
            CreateReaderContextShardAdmission::Accepted
        } else {
            CreateReaderContextShardAdmission::MissingShard
        };
    }
    drop(manifest);

    if bindings
        .created_indices
        .lock()
        .expect("dev transport created indices lock poisoned")
        .contains(&shard_id.index_name)
    {
        if shard_id.shard_id == 0 {
            CreateReaderContextShardAdmission::Accepted
        } else {
            CreateReaderContextShardAdmission::MissingShard
        }
    } else {
        CreateReaderContextShardAdmission::MissingIndex
    }
}

fn build_local_update_reader_context_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    build_update_reader_context_response(request_id, header_version_id, body, None)
}

fn build_update_reader_context_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    transport_identity: Option<&DevTransportIdentity>,
) -> Vec<u8> {
    let Some(request) = decode_update_reader_context_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if let Some(transport_identity) = transport_identity {
        if !reader_context_exists(&request.search_context_id) {
            if let Some(peer) = update_reader_context_target_peer(&request, transport_identity) {
                return update_reader_context_on_peer(
                    request_id,
                    header_version_id,
                    &peer,
                    &request,
                )
                .unwrap_or_else(|_| {
                    build_update_reader_context_missing_context_error_response(
                        request_id,
                        header_version_id,
                        body,
                    )
                });
            }
        }
    }
    if request.validate_supported_subset().is_err() {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if request.keep_alive_millis > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if !reader_context_exists(&request.search_context_id) {
        return build_update_reader_context_missing_context_error_response(
            request_id,
            header_version_id,
            body,
        );
    }
    if !reader_context_available_for_update(&request.search_context_id) {
        return build_update_reader_context_already_assigned_error_response(
            request_id,
            header_version_id,
            body,
        );
    }
    if !upsert_transport_pit_context_from_reader_update(&request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let update_response = os_transport::action::OpenSearchUpdateReaderContextResponseWire {
        pit_id: request.pit_id,
        creation_time_millis: request.creation_time_millis,
        keep_alive_millis: request.keep_alive_millis,
    };
    os_transport::action::build_opensearch_update_reader_context_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &update_response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn update_reader_context_request_supports_local_subset(body: &[u8]) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.keep_alive_millis <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
        .filter(|request| reader_context_available_for_update(&request.search_context_id))
        .and_then(|request| request.validate_supported_subset().ok())
        .is_some()
}

fn update_reader_context_request_supports_bounded_fanout_subset(
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.keep_alive_millis <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
        .filter(|request| {
            reader_context_available_for_update(&request.search_context_id)
                || update_reader_context_target_peer(request, transport_identity).is_some()
        })
        .and_then(|request| request.validate_supported_subset().ok())
        .is_some()
}

fn update_reader_context_request_exceeds_local_keep_alive_limit(body: &[u8]) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .is_some_and(|request| request.keep_alive_millis > DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
}

fn update_reader_context_request_has_missing_context(body: &[u8]) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .filter(|request| request.keep_alive_millis <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
        .is_some_and(|request| !reader_context_exists(&request.search_context_id))
}

fn update_reader_context_request_has_missing_context_for_identity(
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .filter(|request| request.keep_alive_millis <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
        .is_some_and(|request| {
            !reader_context_exists(&request.search_context_id)
                && update_reader_context_target_peer(&request, transport_identity).is_none()
        })
}

fn update_reader_context_request_has_assigned_context(body: &[u8]) -> bool {
    decode_update_reader_context_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .filter(|request| request.keep_alive_millis <= DEV_TRANSPORT_MAX_PIT_KEEP_ALIVE_MILLIS)
        .is_some_and(|request| {
            reader_context_exists(&request.search_context_id)
                && !reader_context_available_for_update(&request.search_context_id)
        })
}

fn update_reader_context_target_peer(
    request: &os_transport::action::OpenSearchUpdateReaderContextRequestWire,
    transport_identity: &DevTransportIdentity,
) -> Option<GetAllPitsPeerTarget> {
    let context_id =
        os_transport::action::OpenSearchSearchContextIdWire::decode(&request.pit_id).ok()?;
    let target_node = context_id.shards.values().find_map(|context| {
        (context.search_context_id == request.search_context_id).then(|| context.node.clone())
    })?;
    if target_node.is_empty()
        || target_node == "_local"
        || target_node == transport_identity.node_id
        || target_node == transport_identity.node_name
    {
        return None;
    }
    get_all_pits_target_peers(
        &os_transport::action::OpenSearchGetAllPitsRequestWire {
            node_ids: Some(vec![target_node]),
            ..os_transport::action::OpenSearchGetAllPitsRequestWire::default()
        },
        transport_identity,
    )
    .into_iter()
    .next()
}

fn update_reader_context_on_peer(
    request_id: i64,
    _header_version_id: u32,
    peer: &GetAllPitsPeerTarget,
    request: &os_transport::action::OpenSearchUpdateReaderContextRequestWire,
) -> Result<Vec<u8>, String> {
    let target_transport_address = peer
        .transport_address
        .parse::<SocketAddr>()
        .map_err(|error| format!("invalid transport address: {error}"))?;
    let forwarded_request_id = TRANSPORT_REQUEST_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let frame = os_transport::action::build_opensearch_update_reader_context_request_message(
        forwarded_request_id,
        OPENSEARCH_3_7_0_TRANSPORT,
        request,
    )
    .map_err(|error| format!("failed to encode request: {error}"))?;
    let response_body = send_transport_request_and_capture_response_body(
        target_transport_address,
        forwarded_request_id,
        &frame,
        Duration::from_secs(5),
    )
    .map_err(|error| format!("transport request failed: {error}"))?
    .ok_or_else(|| "transport request returned no response".to_string())?;
    Ok(build_transport_frame_from_body(
        &rewrite_transport_body_request_id(&response_body, request_id),
    ))
}

fn build_update_reader_context_keep_alive_too_large_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_update_reader_context_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    build_pit_keep_alive_too_large_error_response(
        request_id,
        header_version_id,
        request.keep_alive_millis,
    )
}

fn build_update_reader_context_missing_context_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_update_reader_context_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    build_missing_search_context_error_response(
        request_id,
        header_version_id,
        &request.search_context_id,
    )
}

fn build_update_reader_context_already_assigned_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    release_update_reader_context_if_present(body);
    let mut output = os_stream::StreamOutput::new();
    os_transport::error::write_illegal_state_exception(
        &mut output,
        Some("The object cannot be set twice!"),
    );
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn decode_update_reader_context_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchUpdateReaderContextRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_update_reader_context_request_message(&message).ok()
}

fn release_update_reader_context_if_present(body: &[u8]) {
    let Some(request) = decode_update_reader_context_request_from_transport_body(body) else {
        return;
    };
    let bindings = dev_transport_pit_bindings();
    let released_pit_id = {
        let mut reader_contexts = bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned");
        prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
        if let Some(reader_context_key) =
            reader_context_lookup_key_for_request(&reader_contexts, &request.search_context_id)
        {
            reader_contexts
                .remove(&reader_context_key)
                .and_then(|reader_context| reader_context.pit_id)
        } else {
            None
        }
    };
    if let Some(pit_id) = released_pit_id {
        remove_transport_pit_context_without_reader_contexts(&pit_id);
    }
}

fn remove_transport_pit_context_without_reader_contexts(pit_id: &str) {
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    let has_reader_context = reader_contexts
        .values()
        .any(|context| context.pit_id.as_deref() == Some(pit_id));
    drop(reader_contexts);
    if !has_reader_context {
        bindings
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .remove(pit_id);
    }
}

fn upsert_transport_pit_context_from_reader_update(
    request: &os_transport::action::OpenSearchUpdateReaderContextRequestWire,
) -> bool {
    let keep_alive_millis = transport_positive_keep_alive_millis(request.keep_alive_millis);
    let now_millis = now_epoch_ms();
    let creation_time_millis = request.creation_time_millis;
    let pit_context_creation_time_millis = if creation_time_millis >= 0 {
        u128::try_from(creation_time_millis).unwrap_or(now_millis)
    } else {
        0
    };
    let expires_at_millis = transport_pit_expires_at_millis(now_millis, keep_alive_millis);
    let reader_context = {
        let bindings = dev_transport_pit_bindings();
        let mut reader_contexts = bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned");
        prune_expired_transport_reader_contexts(&mut reader_contexts, now_millis);
        let Some(reader_context_key) =
            reader_context_lookup_key_for_request(&reader_contexts, &request.search_context_id)
        else {
            return false;
        };
        let Some(reader_context) = reader_contexts.get_mut(&reader_context_key) else {
            return false;
        };
        if reader_context.pit_id.is_some() || reader_context.creation_time_millis.is_some() {
            reader_contexts.remove(&reader_context_key);
            return false;
        }
        reader_context.expires_at_millis = reader_context.expires_at_millis.max(expires_at_millis);
        reader_context.keep_alive_millis = reader_context.keep_alive_millis.max(keep_alive_millis);
        reader_context.pit_id = Some(request.pit_id.clone());
        reader_context.creation_time_millis = Some(creation_time_millis);
        reader_context.clone()
    };
    let mut indices = transport_pit_indices_from_id(&request.pit_id).unwrap_or_default();
    if indices.is_empty() {
        indices.push(reader_context.shard_id.index_name.clone());
    }
    indices.sort();
    indices.dedup();
    let documents = reader_context.documents;
    let mut contexts = dev_transport_pit_bindings()
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    prune_expired_transport_pits(&mut contexts, now_millis);
    contexts
        .entry(request.pit_id.clone())
        .and_modify(|context| {
            context.indices.extend(indices.clone());
            context.indices.sort();
            context.indices.dedup();
            for (key, document) in documents.iter() {
                Arc::make_mut(&mut context.documents).insert(key.clone(), Arc::clone(document));
            }
            context.keep_alive_millis = context.keep_alive_millis.max(keep_alive_millis);
            context.expires_at_millis = context.expires_at_millis.max(expires_at_millis);
            context.creation_time_millis = context
                .creation_time_millis
                .min(pit_context_creation_time_millis);
        })
        .or_insert_with(|| PitContext {
            indices,
            documents,
            keep_alive_millis,
            expires_at_millis,
            creation_time_millis: pit_context_creation_time_millis,
        });
    true
}

fn transport_pit_indices_from_id(pit_id: &str) -> Option<Vec<String>> {
    os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id)
        .ok()
        .map(|context_id| context_id.actual_indices())
}

fn build_local_free_pit_context_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> Vec<u8> {
    let Some(request) = decode_free_pit_context_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if !free_pit_context_request_matches_bounded_fanout_subset(&request, transport_identity) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let response = free_transport_reader_contexts_for_free_pit_request_with_fanout(
        &request,
        transport_identity,
    );
    os_transport::action::build_opensearch_delete_pit_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn free_pit_context_request_supports_local_subset(
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> bool {
    decode_free_pit_context_request_from_transport_body(body)
        .as_ref()
        .is_some_and(|request| {
            free_pit_context_request_matches_bounded_fanout_subset(request, transport_identity)
        })
}

fn free_pit_context_request_matches_bounded_fanout_subset(
    request: &os_transport::action::OpenSearchFreePitContextRequestWire,
    transport_identity: &DevTransportIdentity,
) -> bool {
    request.validate_supported_subset().is_ok()
        && !request.context_ids.is_empty()
        && request.context_ids.iter().all(|context| {
            let search_context = &context.search_context;
            let cluster_alias_is_local = search_context
                .cluster_alias
                .as_deref()
                .map_or(true, str::is_empty);
            cluster_alias_is_local
                && (free_pit_context_targets_local_node(search_context, transport_identity)
                    || free_pit_context_target_peer(search_context, transport_identity).is_some())
        })
}

fn decode_free_pit_context_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchFreePitContextRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_free_pit_context_request_message(&message).ok()
}

fn reader_context_key(
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> (String, i64) {
    (context_id.session_id.clone(), context_id.id)
}

fn reader_context_exists(
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    reader_context_lookup_key_for_request(&reader_contexts, context_id).is_some()
}

fn reader_context_available_for_update(
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> bool {
    let bindings = dev_transport_pit_bindings();
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    let Some(reader_context_key) =
        reader_context_lookup_key_for_request(&reader_contexts, context_id)
    else {
        return false;
    };
    reader_contexts
        .get(&reader_context_key)
        .is_some_and(|context| context.pit_id.is_none() && context.creation_time_millis.is_none())
}

fn reader_context_lookup_key_for_request(
    reader_contexts: &BTreeMap<(String, i64), DevTransportReaderContext>,
    context_id: &os_transport::action::OpenSearchShardSearchContextIdWire,
) -> Option<(String, i64)> {
    if context_id.session_id.is_empty() {
        reader_context_key_by_numeric_id(reader_contexts, context_id.id)
    } else {
        let key = reader_context_key(context_id);
        reader_contexts.contains_key(&key).then_some(key)
    }
}

fn reader_context_key_by_numeric_id(
    reader_contexts: &BTreeMap<(String, i64), DevTransportReaderContext>,
    context_id: i64,
) -> Option<(String, i64)> {
    reader_contexts
        .keys()
        .find(|(_, id)| *id == context_id)
        .cloned()
}

fn can_allocate_reader_context(bindings: &DevTransportPitBindings) -> bool {
    let mut reader_contexts = bindings
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    reader_contexts.len() < DEV_TRANSPORT_MAX_OPEN_PIT_CONTEXTS
}

fn prune_expired_transport_reader_contexts(
    reader_contexts: &mut BTreeMap<(String, i64), DevTransportReaderContext>,
    now_millis: u128,
) {
    reader_contexts.retain(|_, context| context.expires_at_millis > now_millis);
}

fn free_transport_reader_contexts_for_free_pit_request(
    request: &os_transport::action::OpenSearchFreePitContextRequestWire,
) -> os_transport::action::OpenSearchDeletePitResponseWire {
    let mut reader_contexts = dev_transport_pit_bindings()
        .reader_contexts
        .lock()
        .expect("dev transport reader contexts lock poisoned");
    prune_expired_transport_reader_contexts(&mut reader_contexts, now_epoch_ms());
    let results = request
        .context_ids
        .iter()
        .map(|context| {
            let search_context_id = &context.search_context.search_context_id;
            let reader_key = if search_context_id.session_id.is_empty() {
                reader_context_key_by_numeric_id(&reader_contexts, search_context_id.id)
            } else {
                let key = reader_context_key(search_context_id);
                reader_contexts.contains_key(&key).then_some(key)
            };
            let pit_id = reader_contexts
                .remove(&reader_key.unwrap_or_else(|| reader_context_key(search_context_id)))
                .and_then(|reader_context| reader_context.pit_id)
                .unwrap_or_else(|| context.pit_id.clone());
            os_transport::action::OpenSearchDeletePitInfoWire::new(true, pit_id)
        })
        .collect();
    os_transport::action::OpenSearchDeletePitResponseWire::with_results(results)
}

fn free_transport_reader_contexts_for_free_pit_request_with_fanout(
    request: &os_transport::action::OpenSearchFreePitContextRequestWire,
    transport_identity: &DevTransportIdentity,
) -> os_transport::action::OpenSearchDeletePitResponseWire {
    let local_request = os_transport::action::OpenSearchFreePitContextRequestWire {
        parent_task_node: request.parent_task_node.clone(),
        parent_task_id: request.parent_task_id,
        context_ids: request
            .context_ids
            .iter()
            .filter(|context| {
                free_pit_context_targets_local_node(&context.search_context, transport_identity)
            })
            .cloned()
            .collect(),
    };
    let mut results = Vec::new();
    if !local_request.context_ids.is_empty() {
        let local_response = free_transport_reader_contexts_for_free_pit_request(&local_request);
        remove_transport_pit_context_entries_without_readers(
            local_response
                .results
                .iter()
                .map(|result| result.pit_id.as_str()),
        );
        results.extend(local_response.results);
    }

    let mut grouped_remote_contexts: BTreeMap<String, (GetAllPitsPeerTarget, Vec<_>)> =
        BTreeMap::new();
    for context in request.context_ids.iter().filter(|context| {
        !free_pit_context_targets_local_node(&context.search_context, transport_identity)
    }) {
        if let Some(peer) =
            free_pit_context_target_peer(&context.search_context, transport_identity)
        {
            grouped_remote_contexts
                .entry(peer.node_id.clone())
                .or_insert_with(|| (peer, Vec::new()))
                .1
                .push(context.clone());
        }
    }

    for (_node_id, (peer, context_ids)) in grouped_remote_contexts {
        let remote_request = os_transport::action::OpenSearchFreePitContextRequestWire {
            parent_task_node: request.parent_task_node.clone(),
            parent_task_id: request.parent_task_id,
            context_ids,
        };
        match free_pit_contexts_on_peer(&peer, &remote_request) {
            Ok(response) => results.extend(response.results),
            Err(_) => results.extend(remote_request.context_ids.into_iter().map(|context| {
                os_transport::action::OpenSearchDeletePitInfoWire::new(false, context.pit_id)
            })),
        }
    }

    os_transport::action::OpenSearchDeletePitResponseWire::with_results(results)
}

fn free_pit_context_targets_local_node(
    search_context: &os_transport::action::OpenSearchSearchContextIdForNodeWire,
    transport_identity: &DevTransportIdentity,
) -> bool {
    search_context.node.is_empty()
        || search_context.node == "_local"
        || search_context.node == transport_identity.node_id
        || search_context.node == transport_identity.node_name
}

fn free_pit_context_target_peer(
    search_context: &os_transport::action::OpenSearchSearchContextIdForNodeWire,
    transport_identity: &DevTransportIdentity,
) -> Option<GetAllPitsPeerTarget> {
    get_all_pits_target_peers(
        &os_transport::action::OpenSearchGetAllPitsRequestWire {
            node_ids: Some(vec![search_context.node.clone()]),
            ..os_transport::action::OpenSearchGetAllPitsRequestWire::default()
        },
        transport_identity,
    )
    .into_iter()
    .next()
}

fn free_pit_contexts_on_peer(
    peer: &GetAllPitsPeerTarget,
    request: &os_transport::action::OpenSearchFreePitContextRequestWire,
) -> Result<os_transport::action::OpenSearchDeletePitResponseWire, String> {
    let target_transport_address = peer
        .transport_address
        .parse::<SocketAddr>()
        .map_err(|error| format!("invalid transport address: {error}"))?;
    let forwarded_request_id = TRANSPORT_REQUEST_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let frame = os_transport::action::build_opensearch_free_pit_context_request_message(
        forwarded_request_id,
        OPENSEARCH_3_7_0_TRANSPORT,
        request,
    )
    .map_err(|error| format!("failed to encode request: {error}"))?;
    let response_body = send_transport_request_and_capture_response_body(
        target_transport_address,
        forwarded_request_id,
        &frame,
        Duration::from_secs(5),
    )
    .map_err(|error| format!("transport request failed: {error}"))?
    .ok_or_else(|| "transport request returned no response".to_string())?;
    let response_message = decode_transport_message_from_body(&response_body)
        .ok_or_else(|| "transport response frame was not decodable".to_string())?;
    os_transport::action::read_opensearch_delete_pit_response_message(&response_message)
        .map_err(|error| format!("failed to decode response: {error}"))
}

fn build_local_delete_pit_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    build_delete_pit_response_for_request(request_id, header_version_id, body, None)
}

fn build_delete_pit_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> Vec<u8> {
    build_delete_pit_response_for_request(
        request_id,
        header_version_id,
        body,
        Some(transport_identity),
    )
}

fn build_delete_pit_response_for_request(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
    transport_identity: Option<&DevTransportIdentity>,
) -> Vec<u8> {
    let Some(request) = decode_delete_pit_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if let Some(_) = delete_pit_request_first_invalid_pit_id(&request) {
        return build_delete_pit_invalid_pit_id_error_response(request_id, header_version_id, body);
    }
    if !delete_pit_request_matches_local_lifecycle_subset(&request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let response = if let Some(transport_identity) = transport_identity {
        delete_transport_pit_contexts_with_fanout(&request.pit_ids, transport_identity)
    } else {
        delete_transport_pit_contexts(&request.pit_ids)
    };
    os_transport::action::build_opensearch_delete_pit_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &response,
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn delete_pit_request_supports_local_lifecycle_subset(body: &[u8]) -> bool {
    decode_delete_pit_request_from_transport_body(body)
        .as_ref()
        .is_some_and(delete_pit_request_matches_local_lifecycle_subset)
}

fn delete_pit_request_supports_bounded_fanout_subset(
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> bool {
    decode_delete_pit_request_from_transport_body(body)
        .as_ref()
        .is_some_and(|request| {
            delete_pit_request_matches_bounded_fanout_subset(request, transport_identity)
        })
}

fn delete_pit_request_has_invalid_pit_id(body: &[u8]) -> bool {
    decode_delete_pit_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .is_some_and(|request| delete_pit_request_first_invalid_pit_id(&request).is_some())
}

fn delete_pit_request_matches_local_lifecycle_subset(
    request: &os_transport::action::OpenSearchDeletePitRequestWire,
) -> bool {
    request.validate_supported_subset().is_ok()
        && delete_pit_ids_match_local_lifecycle_subset(&request.pit_ids)
}

fn delete_pit_request_matches_bounded_fanout_subset(
    request: &os_transport::action::OpenSearchDeletePitRequestWire,
    transport_identity: &DevTransportIdentity,
) -> bool {
    if !delete_pit_request_matches_local_lifecycle_subset(request) {
        return false;
    }
    if request.pit_ids.len() == 1 && request.pit_ids.first().is_some_and(|id| id == "_all") {
        return true;
    }
    request.pit_ids.iter().all(|pit_id| {
        os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id)
            .ok()
            .is_some_and(|context_id| {
                context_id.shards.values().all(|search_context| {
                    let cluster_alias_is_local = search_context
                        .cluster_alias
                        .as_deref()
                        .map_or(true, str::is_empty);
                    cluster_alias_is_local
                        && (free_pit_context_targets_local_node(search_context, transport_identity)
                            || free_pit_context_target_peer(search_context, transport_identity)
                                .is_some())
                })
            })
    })
}

fn delete_pit_ids_match_local_lifecycle_subset(ids: &[String]) -> bool {
    if ids.len() == 1 && ids.first().is_some_and(|id| id == "_all") {
        return true;
    }
    !ids.iter().any(|id| id == "_all")
        && ids
            .iter()
            .all(|id| os_transport::action::OpenSearchSearchContextIdWire::decode(id).is_ok())
}

fn delete_pit_request_first_invalid_pit_id(
    request: &os_transport::action::OpenSearchDeletePitRequestWire,
) -> Option<String> {
    if request.pit_ids.len() == 1 && request.pit_ids[0] == "_all" {
        return None;
    }
    request
        .pit_ids
        .iter()
        .find(|pit_id| os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id).is_err())
        .cloned()
}

fn build_delete_pit_invalid_pit_id_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_delete_pit_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let pit_id = delete_pit_request_first_invalid_pit_id(&request).unwrap_or_default();
    let reason = format!("invalid id: [{pit_id}]");
    let mut output = StreamOutput::new();
    os_transport::error::write_illegal_argument_exception(&mut output, Some(&reason));
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn ids_use_all_only_as_standalone(ids: &[String]) -> bool {
    !ids.iter().any(|id| id == "_all")
        || (ids.len() == 1 && ids.first().is_some_and(|id| id == "_all"))
}

fn decode_delete_pit_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchDeletePitRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_delete_pit_request_message(&message).ok()
}

fn build_local_clear_scroll_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_clear_scroll_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if !clear_scroll_request_matches_local_lifecycle_subset(&request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    os_transport::action::build_opensearch_clear_scroll_response_message(
        request_id,
        Version::from_id(header_version_id as i32),
        &clear_transport_scroll_contexts(&request.scroll_ids),
    )
    .map(|frame| frame.to_vec())
    .unwrap_or_else(|_| build_empty_transport_response(request_id, header_version_id))
}

fn clear_scroll_request_supports_local_lifecycle_subset(body: &[u8]) -> bool {
    decode_clear_scroll_request_from_transport_body(body)
        .as_ref()
        .is_some_and(clear_scroll_request_matches_local_lifecycle_subset)
}

fn clear_scroll_request_matches_local_lifecycle_subset(
    request: &os_transport::action::OpenSearchClearScrollRequestWire,
) -> bool {
    request.validate_supported_subset().is_ok()
}

fn get_all_pits_request_supports_local_lifecycle_subset(
    body: &[u8],
    transport_identity: &DevTransportIdentity,
) -> bool {
    let Some(request) = decode_get_all_pits_request_from_transport_body(body) else {
        return false;
    };
    request.validate_supported_subset().is_ok()
        && get_all_pits_request_targets_known_nodes(&request, transport_identity)
}

fn get_all_pits_request_targets_known_nodes(
    request: &os_transport::action::OpenSearchGetAllPitsRequestWire,
    transport_identity: &DevTransportIdentity,
) -> bool {
    request.node_ids.as_deref().map_or(true, |node_ids| {
        node_ids.iter().all(|node_id| {
            node_id == "_all"
                || node_id == "_local"
                || node_id == &transport_identity.node_id
                || node_id == &transport_identity.node_name
                || transport_identity.seed_peer_identities.iter().any(|peer| {
                    node_id == &peer.discovery_node.id || node_id == &peer.discovery_node.name
                })
                || get_all_pits_cached_peer_targets(transport_identity)
                    .iter()
                    .any(|peer| node_id == &peer.node_id || node_id == &peer.node_name)
        })
    }) && request.concrete_nodes.as_deref().map_or(true, |nodes| {
        nodes.iter().all(|node| {
            node.id == transport_identity.node_id
                || transport_identity
                    .seed_peer_identities
                    .iter()
                    .any(|peer| peer.discovery_node.id == node.id)
                || get_all_pits_cached_peer_targets(transport_identity)
                    .iter()
                    .any(|peer| peer.node_id == node.id)
        })
    })
}

fn clear_transport_scroll_contexts(
    scroll_ids: &[String],
) -> os_transport::action::OpenSearchClearScrollResponseWire {
    let mut contexts = dev_transport_scroll_bindings()
        .contexts
        .lock()
        .expect("dev transport scroll contexts lock poisoned");
    let freed = if scroll_ids.len() == 1 && scroll_ids.first().is_some_and(|id| id == "_all") {
        let freed = contexts.len();
        contexts.clear();
        freed
    } else {
        scroll_ids
            .iter()
            .map(|scroll_id| {
                if let Ok(parsed) =
                    os_transport::action::OpenSearchParsedScrollIdWire::decode(scroll_id)
                {
                    parsed
                        .contexts
                        .iter()
                        .filter_map(|context| {
                            transport_scroll_context_lookup_key_for_request(
                                &contexts,
                                &context.search_context_id,
                            )
                        })
                        .collect::<BTreeSet<_>>()
                        .into_iter()
                        .filter(|context_key| contexts.remove(context_key).is_some())
                        .count()
                } else if contexts.remove(scroll_id).is_some() {
                    1
                } else {
                    0
                }
            })
            .sum()
    };
    os_transport::action::OpenSearchClearScrollResponseWire {
        succeeded: true,
        num_freed: usize_to_i32_saturating(freed),
    }
}

fn decode_clear_scroll_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchClearScrollRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_clear_scroll_request_message(&message).ok()
}

fn decode_get_all_pits_request_from_transport_body(
    body: &[u8],
) -> Option<os_transport::action::OpenSearchGetAllPitsRequestWire> {
    let message = decode_transport_message_from_body(body)?;
    os_transport::action::read_opensearch_get_all_pits_request_message(&message).ok()
}

fn pit_segments_request_supports_local_subset(body: &[u8]) -> bool {
    let Some(request) = decode_pit_segments_request_from_transport_body(body) else {
        return false;
    };
    request.validate_supported_subset().is_ok() && transport_pit_segment_ids_exist(&request)
}

fn pit_segments_request_has_invalid_pit_id(body: &[u8]) -> bool {
    decode_pit_segments_request_from_transport_body(body)
        .filter(|request| request.validate_supported_subset().is_ok())
        .is_some_and(|request| pit_segments_request_first_invalid_pit_id(&request).is_some())
}

fn build_local_pit_segments_node_response(
    request_id: i64,
    header_version_id: u32,
    transport_identity: &DevTransportIdentity,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_pit_segments_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    if request.validate_supported_subset().is_err() {
        return build_empty_transport_response(request_id, header_version_id);
    }
    if let Some(_) = pit_segments_request_first_invalid_pit_id(&request) {
        return build_pit_segments_invalid_pit_id_error_response(
            request_id,
            header_version_id,
            body,
        );
    }
    if let Some(context_id) = missing_decodable_pit_segment_context_id(&request) {
        return build_missing_search_context_error_response(
            request_id,
            header_version_id,
            &context_id,
        );
    }
    if !transport_pit_segment_ids_exist(&request) {
        return build_empty_transport_response(request_id, header_version_id);
    }
    let shard_segments = local_pit_segment_shards_for_request(&request, transport_identity);
    build_pit_segments_node_response(
        request_id,
        header_version_id,
        transport_identity,
        &shard_segments,
    )
}

fn pit_segments_request_first_invalid_pit_id(
    request: &os_transport::action::OpenSearchPitSegmentsRequestWire,
) -> Option<String> {
    if request.pit_ids.len() == 1 && request.pit_ids[0] == "_all" {
        return None;
    }
    let mut contexts = dev_transport_pit_bindings()
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    prune_expired_transport_pits(&mut contexts, now_epoch_ms());
    prune_unavailable_transport_pits(&mut contexts);
    request
        .pit_ids
        .iter()
        .find(|pit_id| {
            os_transport::action::OpenSearchSearchContextIdWire::decode(pit_id).is_err()
                && !contexts.contains_key(*pit_id)
        })
        .cloned()
}

fn build_pit_segments_invalid_pit_id_error_response(
    request_id: i64,
    header_version_id: u32,
    body: &[u8],
) -> Vec<u8> {
    let Some(request) = decode_pit_segments_request_from_transport_body(body) else {
        return build_empty_transport_response(request_id, header_version_id);
    };
    let pit_id = pit_segments_request_first_invalid_pit_id(&request).unwrap_or_default();
    let reason = format!("invalid id: [{pit_id}]");
    let mut output = StreamOutput::new();
    os_transport::error::write_illegal_argument_exception(&mut output, Some(&reason));
    build_transport_error_response_frame(request_id, header_version_id, output.freeze().to_vec())
}

fn transport_pit_segment_ids_exist(
    request: &os_transport::action::OpenSearchPitSegmentsRequestWire,
) -> bool {
    if !ids_use_all_only_as_standalone(&request.pit_ids) {
        return false;
    }
    let mut contexts = dev_transport_pit_bindings()
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    prune_expired_transport_pits(&mut contexts, now_epoch_ms());
    prune_unavailable_transport_pits(&mut contexts);
    let mut seen_ids = BTreeSet::new();
    request
        .pit_ids
        .iter()
        .filter(|pit_id| seen_ids.insert((*pit_id).clone()))
        .all(|pit_id| pit_id == "_all" || contexts.contains_key(pit_id))
}

fn missing_decodable_pit_segment_context_id(
    request: &os_transport::action::OpenSearchPitSegmentsRequestWire,
) -> Option<os_transport::action::OpenSearchShardSearchContextIdWire> {
    if !ids_use_all_only_as_standalone(&request.pit_ids) {
        return None;
    }
    let mut contexts = dev_transport_pit_bindings()
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    prune_expired_transport_pits(&mut contexts, now_epoch_ms());
    prune_unavailable_transport_pits(&mut contexts);
    let mut seen_ids = BTreeSet::new();
    request
        .pit_ids
        .iter()
        .filter(|pit_id| *pit_id != "_all")
        .filter(|pit_id| seen_ids.insert((*pit_id).clone()))
        .find_map(|pit_id| {
            if contexts.contains_key(pit_id) {
                None
            } else {
                first_search_context_id_from_pit_id(pit_id)
            }
        })
}

fn local_pit_segment_shards_for_request(
    request: &os_transport::action::OpenSearchPitSegmentsRequestWire,
    transport_identity: &DevTransportIdentity,
) -> Vec<os_transport::action::OpenSearchShardIdWire> {
    let bindings = dev_transport_pit_bindings();
    let mut contexts = bindings
        .contexts
        .lock()
        .expect("dev transport PIT contexts lock poisoned");
    let now_millis = now_epoch_ms();
    prune_expired_transport_pits(&mut contexts, now_millis);
    prune_unavailable_transport_pits(&mut contexts);
    let selected_pit_ids = if request.pit_ids.len() == 1 && request.pit_ids[0] == "_all" {
        contexts.keys().cloned().collect::<Vec<_>>()
    } else {
        let mut seen_ids = BTreeSet::new();
        request
            .pit_ids
            .iter()
            .filter(|pit_id| seen_ids.insert((*pit_id).clone()))
            .cloned()
            .collect::<Vec<_>>()
    };
    let mut shards = Vec::new();
    for pit_id in selected_pit_ids {
        if let Ok(search_context_id) =
            os_transport::action::OpenSearchSearchContextIdWire::decode(&pit_id)
        {
            for (shard_id, context) in search_context_id.shards {
                if context.cluster_alias.is_none() && context.node == transport_identity.node_id {
                    shards.push(shard_id);
                }
            }
            continue;
        }
        let Some(context) = contexts.get(&pit_id) else {
            continue;
        };
        for index in &context.indices {
            for shard_id in 0..transport_pit_primary_shard_count(bindings, index) {
                let shard_id = os_transport::action::OpenSearchShardIdWire {
                    index_name: index.clone(),
                    index_uuid: transport_pit_index_uuid(bindings, index),
                    shard_id: shard_id as i32,
                };
                shards.push(shard_id);
            }
        }
    }
    shards
}

fn build_pit_segments_node_response(
    request_id: i64,
    header_version_id: u32,
    transport_identity: &DevTransportIdentity,
    shard_segments: &[os_transport::action::OpenSearchShardIdWire],
) -> Vec<u8> {
    let mut payload = Vec::new();
    write_string(&mut payload, &transport_identity.node_id);
    write_transport_vint_to(&mut payload, shard_segments.len() as u32);
    write_transport_vint_to(&mut payload, shard_segments.len() as u32);
    for shard_id in shard_segments {
        write_bool(&mut payload, true);
        write_pit_shard_segments_wire(&mut payload, shard_id, transport_identity);
    }
    write_bool(&mut payload, false);
    build_transport_response_frame(request_id, header_version_id, payload)
}

fn write_pit_shard_segments_wire(
    out: &mut Vec<u8>,
    shard_id: &os_transport::action::OpenSearchShardIdWire,
    transport_identity: &DevTransportIdentity,
) {
    write_string(out, &shard_id.index_name);
    write_string(out, &shard_id.index_uuid);
    write_transport_vint_to(out, shard_id.shard_id.max(0) as u32);
    write_optional_string_to(out, Some(&transport_identity.node_id));
    write_optional_string_to(out, None);
    write_bool(out, true);
    write_bool(out, false);
    out.push(3);
    write_optional_writeable_absent(out);
    write_optional_writeable_absent(out);
    write_transport_vint_to(out, 0);
}

