    #[test]
    fn add_voting_config_exclusions_transport_route_mutates_coordination_state() {
        let transport_identity = DevTransportIdentity {
            cluster_name: "steelsearch-dev".to_string(),
            node_name: "steel-node".to_string(),
            node_id: "steel-node-id".to_string(),
            ephemeral_id: "steel-node-ephemeral".to_string(),
            transport_address: "127.0.0.1:9300".parse().unwrap(),
            attributes: Vec::new(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            seed_peer_identity: None,
            seed_peer_identities: vec![InteropSeedPeerIdentityManifest {
                peer_identity_present: true,
                cluster_name: "steelsearch-dev".to_string(),
                discovery_node: InteropSeedPeerIdentityNode {
                    name: "peer-manager".to_string(),
                    id: "peer-manager-id".to_string(),
                    ephemeral_id: "peer-manager-ephemeral".to_string(),
                    host_name: "peer-host".to_string(),
                    host_address: "127.0.0.2".to_string(),
                    http_address: None,
                    transport_address: "127.0.0.2:9300".to_string(),
                    version_id: OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
                    roles: vec!["cluster_manager".to_string(), "data".to_string()],
                },
            }],
            coordination_state: Arc::new(Mutex::new(DevTransportCoordinationState::default())),
            remote_transport_queue_gate: Arc::new(RemoteTransportQueueGate::new(1, 1000)),
            task_queue_state: None,
        };
        let request = os_transport::action::AddVotingConfigExclusionsRequestWire {
            node_names: vec!["steel-node".to_string(), "missing-node".to_string()],
            ..os_transport::action::AddVotingConfigExclusionsRequestWire::default()
        };
        let frame = os_transport::action::build_add_voting_config_exclusions_request_message(
            194,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        assert!(
            add_voting_config_exclusions_request_supports_local_execution_subset(
                &frame[6..],
                &transport_identity
            )
        );

        let response = build_local_add_voting_config_exclusions_response(
            194,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &frame[6..],
            &transport_identity,
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected add voting config exclusions response message");
        };

        assert_eq!(message.request_id, 194);
        assert!(!message.status.is_request());
        assert_eq!(
            os_transport::action::read_add_voting_config_exclusions_response_message(&message)
                .unwrap(),
            os_transport::action::AddVotingConfigExclusionsResponseWire::empty()
        );
        let coordination_state = transport_identity
            .coordination_state
            .lock()
            .expect("coordination state lock poisoned");
        assert!(coordination_state
            .voting_config_exclusions
            .contains("steel-node-id"));
        assert!(coordination_state
            .voting_config_exclusions
            .contains("_missing_:missing-node"));
        drop(coordination_state);

        let id_request = os_transport::action::AddVotingConfigExclusionsRequestWire {
            node_names: Vec::new(),
            node_ids: vec!["steel-node-id".to_string(), "missing-node-id".to_string()],
            ..os_transport::action::AddVotingConfigExclusionsRequestWire::default()
        };
        let id_frame = os_transport::action::build_add_voting_config_exclusions_request_message(
            196,
            OPENSEARCH_3_7_0_TRANSPORT,
            &id_request,
        )
        .unwrap();
        assert!(
            add_voting_config_exclusions_request_supports_local_execution_subset(
                &id_frame[6..],
                &transport_identity
            )
        );
        let _ = build_local_add_voting_config_exclusions_response(
            196,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &id_frame[6..],
            &transport_identity,
        );
        let coordination_state = transport_identity
            .coordination_state
            .lock()
            .expect("coordination state lock poisoned");
        assert!(coordination_state
            .voting_config_exclusions
            .contains("missing-node-id"));
        drop(coordination_state);

        let description_request = os_transport::action::AddVotingConfigExclusionsRequestWire {
            node_names: Vec::new(),
            node_descriptions: vec!["_cluster_manager".to_string()],
            ..os_transport::action::AddVotingConfigExclusionsRequestWire::default()
        };
        let description_frame =
            os_transport::action::build_add_voting_config_exclusions_request_message(
                197,
                OPENSEARCH_3_7_0_TRANSPORT,
                &description_request,
            )
            .unwrap();
        assert!(
            add_voting_config_exclusions_request_supports_local_execution_subset(
                &description_frame[6..],
                &transport_identity
            )
        );
        let _ = build_local_add_voting_config_exclusions_response(
            197,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &description_frame[6..],
            &transport_identity,
        );
        let coordination_state = transport_identity
            .coordination_state
            .lock()
            .expect("coordination state lock poisoned");
        assert!(coordination_state
            .voting_config_exclusions
            .contains("steel-node-id"));
        assert!(coordination_state
            .voting_config_exclusions
            .contains("peer-manager-id"));
    }

