    #[test]
    fn search_transport_route_rejects_invalid_pit_id_like_opensearch() {
        let request = os_transport::action::OpenSearchSearchRequestWire {
            source: Some(os_transport::action::OpenSearchSearchSourceBuilderWire {
                point_in_time: Some(os_transport::action::OpenSearchPointInTimeBuilderWire {
                    id: "nondecodableid".to_string(),
                    keep_alive: Some(os_transport::action::TimeValueWire::minutes(1)),
                }),
                ..os_transport::action::OpenSearchSearchSourceBuilderWire::default()
            }),
            ..os_transport::action::OpenSearchSearchRequestWire::default()
        };
        let frame = os_transport::action::build_opensearch_search_request_message(
            311,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        assert!(search_request_has_invalid_pit_id(&frame[6..]));
        assert!(!search_request_supports_local_execution_subset(&frame[6..]));
        let response = build_search_invalid_pit_id_error_response(
            311,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &frame[6..],
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected PIT search invalid-id error response frame");
        };
        assert_eq!(message.request_id, 311);
        assert!(message.status.is_error());
        let error = os_transport::error::TransportError::read(message.body.freeze())
            .unwrap()
            .unwrap();
        assert_eq!(error.class_name, "java.lang.IllegalArgumentException");
        assert_eq!(
            error.message.as_deref(),
            Some("invalid id: [nondecodableid]")
        );

        let stream_frame = os_transport::action::build_opensearch_stream_search_request_message(
            312,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        assert!(stream_search_request_has_invalid_pit_id(&stream_frame[6..]));
        assert!(!stream_search_request_supports_local_execution_subset(
            &stream_frame[6..]
        ));
        let stream_response = build_stream_search_invalid_pit_id_error_response(
            312,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &stream_frame[6..],
        );
        let mut frame = BytesMut::from(&stream_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected PIT stream-search invalid-id error response frame");
        };
        assert_eq!(message.request_id, 312);
        assert!(message.status.is_error());
        let error = os_transport::error::TransportError::read(message.body.freeze())
            .unwrap()
            .unwrap();
        assert_eq!(error.class_name, "java.lang.IllegalArgumentException");
        assert_eq!(
            error.message.as_deref(),
            Some("invalid id: [nondecodableid]")
        );
    }

    #[test]
    fn search_transport_route_uses_pit_snapshot_and_extends_keep_alive() {
        let _lock = dev_transport_pit_test_lock()
            .lock()
            .expect("dev transport PIT test lock poisoned");
        let bindings = dev_transport_pit_bindings();
        bindings
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .clear();
        bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .clear();
        bindings
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .clear();
        bindings
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .clear();
        *bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned") = serde_json::json!({
            "indices": {
                "logs-search-pit-transport": {
                    "settings": {
                        "index": {
                            "number_of_shards": "1"
                        }
                    }
                }
            }
        });
        bindings
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .insert("logs-search-pit-transport".to_string());

        let search_context_id = os_transport::action::OpenSearchShardSearchContextIdWire::new(
            "search-pit-session",
            700,
        );
        let pit_id = os_transport::action::OpenSearchSearchContextIdWire::new(BTreeMap::from([(
            os_transport::action::OpenSearchShardIdWire {
                index_name: "logs-search-pit-transport".to_string(),
                index_uuid: "uuid-search-pit-transport".to_string(),
                shard_id: 0,
            },
            os_transport::action::OpenSearchSearchContextIdForNodeWire {
                node: "steel-node-id".to_string(),
                cluster_alias: None,
                search_context_id: search_context_id.clone(),
            },
        )]))
        .encode(OPENSEARCH_3_7_0_TRANSPORT)
        .unwrap();
        let before_doc: Arc<StoredDocument> = StoredDocument {
            source: serde_json::json!({ "status": "before-pit" }),
            version: 1,
            seq_no: 1,
            primary_term: 1,
            routing: None,
            refreshed: true,
        }
        .into();
        bindings
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .insert(
                pit_id.clone(),
                PitContext {
                    indices: vec!["logs-search-pit-transport".to_string()],
                    documents: Arc::new(BTreeMap::from([(
                        "logs-search-pit-transport:doc-1:".to_string(),
                        before_doc.clone(),
                    )])),
                    keep_alive_millis: 60_000,
                    expires_at_millis: transport_pit_expires_at_millis(now_epoch_ms(), 60_000),
                    creation_time_millis: now_epoch_ms(),
                },
            );
        bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .insert(
                reader_context_key(&search_context_id),
                DevTransportReaderContext {
                    shard_id: os_transport::action::OpenSearchShardIdWire {
                        index_name: "logs-search-pit-transport".to_string(),
                        index_uuid: "uuid-search-pit-transport".to_string(),
                        shard_id: 0,
                    },
                    documents: Arc::new(BTreeMap::from([(
                        "logs-search-pit-transport:doc-1:".to_string(),
                        before_doc.clone(),
                    )])),
                    keep_alive_millis: 60_000,
                    expires_at_millis: transport_pit_expires_at_millis(now_epoch_ms(), 60_000),
                    pit_id: Some(pit_id.clone()),
                    creation_time_millis: Some(now_epoch_ms() as i64),
                },
            );
        {
            let mut documents = bindings
                .documents
                .lock()
                .expect("dev transport documents lock poisoned");
            documents.insert("logs-search-pit-transport:doc-1:".to_string(), before_doc);
            documents.insert(
                "logs-search-pit-transport:doc-1:".to_string(),
                StoredDocument {
                    source: serde_json::json!({ "status": "updated-after-pit" }),
                    version: 2,
                    seq_no: 2,
                    primary_term: 1,
                    routing: None,
                    refreshed: true,
                }
                .into(),
            );
            documents.remove("logs-search-pit-transport:doc-1:");
            documents.insert(
                "logs-search-pit-transport:doc-2:".to_string(),
                StoredDocument {
                    source: serde_json::json!({ "status": "after-pit" }),
                    version: 1,
                    seq_no: 3,
                    primary_term: 1,
                    routing: None,
                    refreshed: true,
                }
                .into(),
            );
        }

        let request = os_transport::action::OpenSearchSearchRequestWire {
            source: Some(os_transport::action::OpenSearchSearchSourceBuilderWire {
                point_in_time: Some(os_transport::action::OpenSearchPointInTimeBuilderWire {
                    id: pit_id.clone(),
                    keep_alive: Some(os_transport::action::TimeValueWire::minutes(2)),
                }),
                ..os_transport::action::OpenSearchSearchSourceBuilderWire::default()
            }),
            indices_options:
                os_transport::action::OpenSearchIndicesOptionsWire::point_in_time_search_prepared(),
            ccs_minimize_roundtrips: false,
            ..os_transport::action::OpenSearchSearchRequestWire::default()
        };
        let indexed_request = os_transport::action::OpenSearchSearchRequestWire {
            indices: vec!["logs-search-pit-transport".to_string()],
            ..request.clone()
        };
        let indexed_frame = os_transport::action::build_opensearch_search_request_message(
            304,
            OPENSEARCH_3_7_0_TRANSPORT,
            &indexed_request,
        )
        .unwrap();
        assert!(search_request_supports_local_execution_subset(
            &indexed_frame[6..]
        ));
        let mismatched_indices_request = os_transport::action::OpenSearchSearchRequestWire {
            indices: vec!["logs-search-pit-other".to_string()],
            ..request.clone()
        };
        let mismatched_frame = os_transport::action::build_opensearch_search_request_message(
            305,
            OPENSEARCH_3_7_0_TRANSPORT,
            &mismatched_indices_request,
        )
        .unwrap();
        assert!(!search_request_supports_local_execution_subset(
            &mismatched_frame[6..]
        ));
        let frame = os_transport::action::build_opensearch_search_request_message(
            306,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        assert!(search_request_supports_local_execution_subset(&frame[6..]));
        let response =
            build_local_search_response(306, OPENSEARCH_3_7_0_TRANSPORT.id() as u32, &frame[6..]);
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected PIT search response message");
        };
        let response = os_transport::action::read_opensearch_search_response_message(&message)
            .expect("PIT search response");
        assert_eq!(response.point_in_time_id.as_deref(), Some(pit_id.as_str()));
        assert_eq!(response.total_hits, Some(1));
        assert_eq!(response.hits.len(), 1);
        assert_eq!(response.hits[0].id.as_deref(), Some("doc-1"));
        assert_eq!(
            response.hits[0]
                .source
                .as_ref()
                .and_then(|source| source.get("status")),
            Some(&serde_json::json!("before-pit"))
        );
        assert_eq!(
            bindings
                .contexts
                .lock()
                .expect("dev transport PIT contexts lock poisoned")
                .get(&pit_id)
                .expect("PIT context should remain")
                .keep_alive_millis,
            120_000
        );
    }

