    #[test]
    fn create_list_and_delete_pit_transport_routes_share_local_lifecycle_state() {
        let _lock = dev_transport_pit_test_lock()
            .lock()
            .expect("dev transport PIT test lock poisoned");
        dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .clear();
        *dev_transport_pit_bindings()
            .next_id
            .lock()
            .expect("dev transport next PIT id lock poisoned") = 0;
        dev_transport_pit_bindings()
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .clear();
        dev_transport_pit_bindings()
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .clear();
        *dev_transport_pit_bindings()
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned") = serde_json::json!({
            "indices": {}
        });
        dev_transport_pit_bindings()
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .insert("logs-pit-000001".to_string());
        dev_transport_pit_bindings()
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .clear();
        dev_transport_pit_bindings()
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .insert(
                "logs-pit-000001:doc-1:".to_string(),
                StoredDocument {
                    source: serde_json::json!({ "message": "before-pit" }),
                    version: 1,
                    seq_no: 1,
                    primary_term: 1,
                    routing: None,
                    refreshed: true,
                }
                .into(),
            );
        *dev_transport_pit_bindings()
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned") = serde_json::json!({
            "indices": {
                "logs-pit-000001": {
                    "settings": {
                        "index": {
                            "number_of_shards": "2"
                        }
                    }
                }
            }
        });
        let transport_identity = DevTransportIdentity {
            cluster_name: "steelsearch-dev".to_string(),
            node_name: "steel-node".to_string(),
            node_id: "steel-node-id".to_string(),
            ephemeral_id: "steel-node-ephemeral".to_string(),
            transport_address: "127.0.0.1:9300".parse().unwrap(),
            attributes: Vec::new(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            seed_peer_identity: None,
            seed_peer_identities: Vec::new(),
            coordination_state: Arc::new(Mutex::new(DevTransportCoordinationState::default())),
            remote_transport_queue_gate: Arc::new(RemoteTransportQueueGate::new(1, 1000)),
            task_queue_state: None,
        };
        let create_request = os_transport::action::OpenSearchCreatePitRequestWire::default();
        let create_frame = os_transport::action::build_opensearch_create_pit_request_message(
            93,
            OPENSEARCH_3_7_0_TRANSPORT,
            &create_request,
        )
        .unwrap();
        let create_body = &create_frame[6..];
        assert!(create_pit_request_supports_local_lifecycle_subset(
            create_body
        ));

        let create_response = build_local_create_pit_response(
            93,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            create_body,
        );
        let mut frame = BytesMut::from(&create_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected create-PIT response message");
        };
        let create_response =
            os_transport::action::read_opensearch_create_pit_response_message(&message).unwrap();
        let pit_id = create_response.pit_id.clone();
        assert!(!pit_id.starts_with("pit-"));
        let decoded_pit_id = os_transport::action::OpenSearchSearchContextIdWire::decode(&pit_id)
            .expect("create PIT should return an OpenSearch SearchContextId");
        assert_eq!(
            decoded_pit_id.actual_indices(),
            vec!["logs-pit-000001".to_string()]
        );
        assert_eq!(decoded_pit_id.shards.len(), 2);
        assert!(decoded_pit_id
            .shards
            .values()
            .all(|context| context.node == "steel-node-id"));
        assert_eq!(create_response.total_shards, 2);
        assert!(dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .contains_key(&pit_id));
        let decoded_reader_context_keys = decoded_pit_id
            .shards
            .values()
            .map(|context| reader_context_key(&context.search_context_id))
            .collect::<BTreeSet<_>>();
        let initial_reader_context_expiries = {
            let reader_contexts = dev_transport_pit_bindings()
                .reader_contexts
                .lock()
                .expect("dev transport reader contexts lock poisoned");
            assert_eq!(reader_contexts.len(), 2);
            assert!(decoded_reader_context_keys
                .iter()
                .all(|key| reader_contexts.contains_key(key)));
            assert!(reader_contexts
                .values()
                .all(|context| context.pit_id.as_deref() == Some(pit_id.as_str())));
            assert!(reader_contexts.values().all(|context| {
                context.creation_time_millis == Some(create_response.creation_time_millis)
            }));
            reader_contexts
                .iter()
                .map(|(key, context)| (key.clone(), context.expires_at_millis))
                .collect::<BTreeMap<_, _>>()
        };
        dev_transport_pit_bindings()
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .insert(
                "logs-pit-000001:doc-2:".to_string(),
                StoredDocument {
                    source: serde_json::json!({ "message": "after-pit" }),
                    version: 1,
                    seq_no: 2,
                    primary_term: 1,
                    routing: None,
                    refreshed: true,
                }
                .into(),
            );
        let pit_context = dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .get(&pit_id)
            .cloned()
            .expect("pit context should be allocated");
        assert_eq!(pit_context.indices, vec!["logs-pit-000001".to_string()]);
        assert!(pit_context.documents.contains_key("logs-pit-000001:doc-1:"));
        assert!(!pit_context.documents.contains_key("logs-pit-000001:doc-2:"));

        let search_request = os_transport::action::OpenSearchSearchRequestWire {
            source: Some(os_transport::action::OpenSearchSearchSourceBuilderWire {
                point_in_time: Some(os_transport::action::OpenSearchPointInTimeBuilderWire {
                    id: pit_id.clone(),
                    keep_alive: Some(os_transport::action::TimeValueWire::minutes(2)),
                }),
                ..os_transport::action::OpenSearchSearchSourceBuilderWire::default()
            }),
            ..os_transport::action::OpenSearchSearchRequestWire::default()
        };
        let search_frame = os_transport::action::build_opensearch_search_request_message(
            94,
            OPENSEARCH_3_7_0_TRANSPORT,
            &search_request,
        )
        .unwrap();
        assert!(!search_request_has_invalid_pit_id(&search_frame[6..]));
        assert!(search_request_supports_local_execution_subset(
            &search_frame[6..]
        ));
        let search_response = build_local_search_response(
            94,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &search_frame[6..],
        );
        let mut frame = BytesMut::from(&search_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected PIT search response message");
        };
        let search_response =
            os_transport::action::read_opensearch_search_response_message(&message).unwrap();
        assert_eq!(
            search_response.point_in_time_id.as_deref(),
            Some(pit_id.as_str())
        );
        assert_eq!(search_response.total_hits, Some(1));
        assert_eq!(search_response.hits.len(), 1);
        assert_eq!(search_response.hits[0].id.as_deref(), Some("doc-1"));
        {
            let pit_context = dev_transport_pit_bindings()
                .contexts
                .lock()
                .expect("dev transport PIT contexts lock poisoned")
                .get(&pit_id)
                .cloned()
                .expect("pit context should still be allocated after search");
            assert_eq!(pit_context.keep_alive_millis, 120_000);
            let reader_contexts = dev_transport_pit_bindings()
                .reader_contexts
                .lock()
                .expect("dev transport reader contexts lock poisoned");
            assert_eq!(reader_contexts.len(), 2);
            for key in &decoded_reader_context_keys {
                let initial_expiry = initial_reader_context_expiries
                    .get(key)
                    .expect("reader context initial expiry should be captured");
                let reader_context = reader_contexts
                    .get(key)
                    .expect("reader context should survive PIT search keep-alive update");
                assert_eq!(
                    reader_context.expires_at_millis,
                    pit_context.expires_at_millis
                );
                assert!(reader_context.expires_at_millis > *initial_expiry);
            }
        }

        let list_response = build_local_get_all_pits_response(
            95,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &transport_identity,
        );
        let mut frame = BytesMut::from(&list_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected get-all-PITs response message");
        };
        let list_response =
            os_transport::action::read_opensearch_get_all_pits_response_message(&message).unwrap();
        assert_eq!(list_response.nodes.len(), 1);
        assert_eq!(
            list_response.nodes[0].pit_infos.len(),
            decoded_reader_context_keys.len()
        );
        assert!(list_response.nodes[0]
            .pit_infos
            .iter()
            .all(|pit| pit.pit_id == pit_id));

        let request = os_transport::action::OpenSearchDeletePitRequestWire::default();
        let frame = os_transport::action::build_opensearch_delete_pit_request_message(
            96,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        let body = &frame[6..];
        assert!(delete_pit_request_supports_local_lifecycle_subset(body));

        let response =
            build_local_delete_pit_response(96, OPENSEARCH_3_7_0_TRANSPORT.id() as u32, body);
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected delete-PIT response message");
        };

        assert_eq!(message.request_id, 96);
        assert!(!message.status.is_request());
        let response =
            os_transport::action::read_opensearch_delete_pit_response_message(&message).unwrap();
        assert_eq!(response.results.len(), 1);
        assert_eq!(response.results[0].pit_id, pit_id);
        assert!(response.results[0].successful);

        let list_response = build_local_get_all_pits_response(
            97,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &transport_identity,
        );
        let mut frame = BytesMut::from(&list_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected get-all-PITs response message");
        };
        let list_response =
            os_transport::action::read_opensearch_get_all_pits_response_message(&message).unwrap();
        assert_eq!(
            list_response,
            os_transport::action::OpenSearchGetAllPitsResponseWire::empty("steelsearch-dev")
        );
        assert!(dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .is_empty());
        assert!(dev_transport_pit_bindings()
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .is_empty());

        dev_transport_pit_bindings()
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .extend([
                "logs-routed-pit-000001".to_string(),
                "metrics-routed-pit-000001".to_string(),
            ]);
        *dev_transport_pit_bindings()
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned") = serde_json::json!({
            "indices": {
                "logs-routed-pit-000001": {
                    "settings": {
                        "index": {
                            "number_of_shards": "3"
                        }
                    },
                    "aliases": {
                        "logs-routed": {},
                        "shared-routed": {}
                    }
                },
                "logs-routed-hidden-000001": {
                    "settings": {
                        "index": {
                            "number_of_shards": "5",
                            "hidden": "true"
                        }
                    }
                },
                "logs-routed-closed-000001": {
                    "state": "close",
                    "settings": {
                        "index": {
                            "number_of_shards": "7"
                        }
                    }
                },
                "metrics-routed-pit-000001": {
                    "settings": {
                        "index": {
                            "number_of_shards": "1"
                        }
                    },
                    "aliases": {
                        "shared-routed": {}
                    }
                }
            }
        });
        let routing_a = "tenant-a".to_string();
        let routing_b = (1..100)
            .map(|suffix| format!("tenant-b-{suffix}"))
            .find(|routing| {
                transport_routing_shard_id(3, &routing_a) != transport_routing_shard_id(3, routing)
            })
            .expect("fixture should find a routing on a distinct shard slot");
        dev_transport_pit_bindings()
            .documents
            .lock()
            .expect("dev transport documents lock poisoned")
            .extend([
                (
                    format!("logs-routed-pit-000001:doc-a:{routing_a}"),
                    StoredDocument {
                        source: serde_json::json!({ "tenant": "a" }),
                        version: 1,
                        seq_no: 3,
                        primary_term: 1,
                        routing: Some(routing_a.clone()),
                        refreshed: true,
                    }
                    .into(),
                ),
                (
                    format!("logs-routed-pit-000001:doc-b:{routing_b}"),
                    StoredDocument {
                        source: serde_json::json!({ "tenant": "b" }),
                        version: 1,
                        seq_no: 4,
                        primary_term: 1,
                        routing: Some(routing_b.clone()),
                        refreshed: true,
                    }
                    .into(),
                ),
                (
                    format!("metrics-routed-pit-000001:doc-c:{routing_a}"),
                    StoredDocument {
                        source: serde_json::json!({ "tenant": "metric" }),
                        version: 1,
                        seq_no: 5,
                        primary_term: 1,
                        routing: Some(routing_a.clone()),
                        refreshed: true,
                    }
                    .into(),
                ),
            ]);
        let routed_create_request = os_transport::action::OpenSearchCreatePitRequestWire {
            indices: vec!["logs-routed*".to_string()],
            routing: Some(routing_a.clone()),
            preference: Some("_local".to_string()),
            allow_partial_pit_creation: Some(false),
            ..os_transport::action::OpenSearchCreatePitRequestWire::default()
        };
        let routed_create_frame =
            os_transport::action::build_opensearch_create_pit_request_message(
                98,
                OPENSEARCH_3_7_0_TRANSPORT,
                &routed_create_request,
            )
            .unwrap();
        let routed_create_body = &routed_create_frame[6..];
        assert!(create_pit_request_supports_local_lifecycle_subset(
            routed_create_body
        ));
        let routed_create_response = build_local_create_pit_response(
            98,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            routed_create_body,
        );
        let mut frame = BytesMut::from(&routed_create_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected routed create-PIT response message");
        };
        let routed_create_response =
            os_transport::action::read_opensearch_create_pit_response_message(&message).unwrap();
        let routed_pit_id = routed_create_response.pit_id.clone();
        assert!(!routed_pit_id.starts_with("pit-"));
        let decoded_routed_pit_id =
            os_transport::action::OpenSearchSearchContextIdWire::decode(&routed_pit_id)
                .expect("routed create PIT should return an OpenSearch SearchContextId");
        assert_eq!(
            decoded_routed_pit_id.actual_indices(),
            vec!["logs-routed-pit-000001".to_string()]
        );
        assert_eq!(decoded_routed_pit_id.shards.len(), 3);
        assert_ne!(routed_pit_id, pit_id);
        assert_eq!(routed_create_response.total_shards, 3);
        let decoded_routed_reader_context_keys = decoded_routed_pit_id
            .shards
            .values()
            .map(|context| reader_context_key(&context.search_context_id))
            .collect::<BTreeSet<_>>();
        {
            let reader_contexts = dev_transport_pit_bindings()
                .reader_contexts
                .lock()
                .expect("dev transport reader contexts lock poisoned");
            assert_eq!(reader_contexts.len(), 3);
            assert!(decoded_routed_reader_context_keys
                .iter()
                .all(|key| reader_contexts.contains_key(key)));
            assert!(reader_contexts
                .values()
                .all(|context| context.pit_id.as_deref() == Some(routed_pit_id.as_str())));
            assert!(reader_contexts.values().all(|context| {
                context.creation_time_millis == Some(routed_create_response.creation_time_millis)
            }));
        }
        let routed_pit_context = dev_transport_pit_bindings()
            .contexts
            .lock()
            .expect("dev transport PIT contexts lock poisoned")
            .get(&routed_pit_id)
            .cloned()
            .expect("routed pit context should be allocated");
        assert_eq!(
            routed_pit_context.indices,
            vec!["logs-routed-pit-000001".to_string()]
        );
        assert!(routed_pit_context
            .documents
            .contains_key(&format!("logs-routed-pit-000001:doc-a:{routing_a}")));
        assert!(!routed_pit_context
            .documents
            .contains_key(&format!("logs-routed-pit-000001:doc-b:{routing_b}")));
        assert!(!routed_pit_context
            .documents
            .contains_key(&format!("metrics-routed-pit-000001:doc-c:{routing_a}")));
        let routed_pit_search = os_transport::action::OpenSearchSearchRequestWire {
            source: Some(os_transport::action::OpenSearchSearchSourceBuilderWire {
                point_in_time: Some(os_transport::action::OpenSearchPointInTimeBuilderWire {
                    id: routed_pit_id.clone(),
                    keep_alive: None,
                }),
                ..os_transport::action::OpenSearchSearchSourceBuilderWire::default()
            }),
            indices: vec!["logs-routed-pit-000001".to_string()],
            indices_options:
                os_transport::action::OpenSearchIndicesOptionsWire::point_in_time_search_prepared(),
            ccs_minimize_roundtrips: false,
            ..os_transport::action::OpenSearchSearchRequestWire::default()
        };
        let routed_pit_search_frame =
            os_transport::action::build_opensearch_search_request_message(
                99,
                OPENSEARCH_3_7_0_TRANSPORT,
                &routed_pit_search,
            )
            .unwrap();
        assert!(search_request_supports_local_execution_subset(
            &routed_pit_search_frame[6..]
        ));
        let routed_pit_search_response = build_local_search_response(
            99,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &routed_pit_search_frame[6..],
        );
        let mut frame = BytesMut::from(&routed_pit_search_response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected routed PIT search response message");
        };
        let search_response =
            os_transport::action::read_opensearch_search_response_message(&message).unwrap();
        assert_eq!(search_response.total_hits, Some(1));
        assert_eq!(search_response.hits[0].id.as_deref(), Some("doc-a"));

        let hidden_indices = transport_pit_indices(
            dev_transport_pit_bindings(),
            &os_transport::action::OpenSearchCreatePitRequestWire {
                indices: vec!["logs-routed*".to_string()],
                indices_options:
                    os_transport::action::OpenSearchIndicesOptionsWire::strict_expand_hidden(),
                ..os_transport::action::OpenSearchCreatePitRequestWire::default()
            },
        )
        .expect("hidden wildcard PIT index resolution should be supported");
        assert!(hidden_indices.contains(&"logs-routed-hidden-000001".to_string()));

        let open_and_closed_indices = transport_pit_indices(
            dev_transport_pit_bindings(),
            &os_transport::action::OpenSearchCreatePitRequestWire {
                indices: vec!["logs-routed*".to_string()],
                indices_options:
                    os_transport::action::OpenSearchIndicesOptionsWire::expand_open_closed_allow_no_indices(),
                ..os_transport::action::OpenSearchCreatePitRequestWire::default()
            },
        )
        .expect("open and closed wildcard PIT index resolution should be supported");
        assert!(open_and_closed_indices.contains(&"logs-routed-closed-000001".to_string()));

        assert!(transport_pit_indices(
            dev_transport_pit_bindings(),
            &os_transport::action::OpenSearchCreatePitRequestWire {
                indices: vec!["logs-routed-closed-000001".to_string()],
                ..os_transport::action::OpenSearchCreatePitRequestWire::default()
            },
        )
        .is_none());
        assert!(transport_pit_indices(
            dev_transport_pit_bindings(),
            &os_transport::action::OpenSearchCreatePitRequestWire {
                indices: vec!["missing-routed-pit".to_string()],
                ..os_transport::action::OpenSearchCreatePitRequestWire::default()
            },
        )
        .is_none());
        assert_eq!(
            transport_pit_indices(
                dev_transport_pit_bindings(),
                &os_transport::action::OpenSearchCreatePitRequestWire {
                    indices: vec!["missing-routed-pit".to_string()],
                    indices_options:
                        os_transport::action::OpenSearchIndicesOptionsWire::lenient_expand_open(),
                    ..os_transport::action::OpenSearchCreatePitRequestWire::default()
                },
            )
            .expect("ignore-unavailable PIT index resolution should be supported"),
            Vec::<String>::new()
        );
        assert!(transport_pit_indices(
            dev_transport_pit_bindings(),
            &os_transport::action::OpenSearchCreatePitRequestWire {
                indices: vec!["shared-routed".to_string()],
                indices_options:
                    os_transport::action::OpenSearchIndicesOptionsWire::delete_index_default(),
                ..os_transport::action::OpenSearchCreatePitRequestWire::default()
            },
        )
        .is_none());
    }

