    #[test]
    fn free_pit_context_transport_route_rejects_nonlocal_contexts() {
        let transport_identity = DevTransportIdentity {
            cluster_name: "steelsearch-dev".to_string(),
            node_name: "steel-node".to_string(),
            node_id: "steel-node-id".to_string(),
            ephemeral_id: "steel-node-ephemeral".to_string(),
            transport_address: "127.0.0.1:9300".parse().unwrap(),
            attributes: Vec::new(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            seed_peer_identity: None,
            seed_peer_identities: Vec::new(),
            coordination_state: Arc::new(Mutex::new(DevTransportCoordinationState::default())),
            remote_transport_queue_gate: Arc::new(RemoteTransportQueueGate::new(1, 1000)),
            task_queue_state: None,
        };
        let local_context =
            os_transport::action::OpenSearchShardSearchContextIdWire::new("steelsearch-reader", 7);
        let empty_request = os_transport::action::OpenSearchFreePitContextRequestWire {
            parent_task_node: String::new(),
            parent_task_id: None,
            context_ids: Vec::new(),
        };
        let empty_frame = os_transport::action::build_opensearch_free_pit_context_request_message(
            311,
            OPENSEARCH_3_7_0_TRANSPORT,
            &empty_request,
        )
        .unwrap();
        assert!(
            !free_pit_context_request_supports_local_subset(&empty_frame[6..], &transport_identity),
            "empty free-PIT-context requests are not produced by OpenSearch PitService fanout"
        );

        for node in ["steel-node-id", "steel-node", "_local", ""] {
            let request = os_transport::action::OpenSearchFreePitContextRequestWire {
                parent_task_node: String::new(),
                parent_task_id: None,
                context_ids: vec![
                    os_transport::action::OpenSearchPitSearchContextIdForNodeWire {
                        pit_id: "pit-local".to_string(),
                        search_context:
                            os_transport::action::OpenSearchSearchContextIdForNodeWire {
                                node: node.to_string(),
                                cluster_alias: None,
                                search_context_id: local_context.clone(),
                            },
                    },
                ],
            };
            let frame = os_transport::action::build_opensearch_free_pit_context_request_message(
                309,
                OPENSEARCH_3_7_0_TRANSPORT,
                &request,
            )
            .unwrap();
            assert!(
                free_pit_context_request_supports_local_subset(&frame[6..], &transport_identity),
                "expected local node marker {node:?} to be admitted"
            );
        }

        for (node, cluster_alias) in [
            ("remote-node-id", None),
            ("steel-node-id", Some("remote-cluster")),
            ("remote-node-id", Some("remote-cluster")),
        ] {
            let request = os_transport::action::OpenSearchFreePitContextRequestWire {
                parent_task_node: String::new(),
                parent_task_id: None,
                context_ids: vec![
                    os_transport::action::OpenSearchPitSearchContextIdForNodeWire {
                        pit_id: "pit-remote".to_string(),
                        search_context:
                            os_transport::action::OpenSearchSearchContextIdForNodeWire {
                                node: node.to_string(),
                                cluster_alias: cluster_alias.map(str::to_string),
                                search_context_id: local_context.clone(),
                            },
                    },
                ],
            };
            let frame = os_transport::action::build_opensearch_free_pit_context_request_message(
                310,
                OPENSEARCH_3_7_0_TRANSPORT,
                &request,
            )
            .unwrap();
            assert!(
                !free_pit_context_request_supports_local_subset(&frame[6..], &transport_identity),
                "expected node {node:?} with cluster alias {cluster_alias:?} to be rejected"
            );
        }
    }

    #[test]
    fn create_reader_context_transport_route_rejects_missing_index_or_shard() {
        let _lock = dev_transport_pit_test_lock()
            .lock()
            .expect("dev transport PIT test lock poisoned");
        let bindings = dev_transport_pit_bindings();
        bindings
            .created_indices
            .lock()
            .expect("dev transport created indices lock poisoned")
            .clear();
        *bindings
            .metadata_manifest
            .lock()
            .expect("dev transport metadata manifest lock poisoned") = serde_json::json!({
            "indices": {
                "logs-reader-manifest": {
                    "settings": {
                        "index": {
                            "number_of_shards": "2"
                        }
                    }
                },
                "logs-reader-closed": {
                    "state": "close",
                    "settings": {
                        "index": {
                            "number_of_shards": "1"
                        }
                    }
                }
            }
        });
        *bindings
            .next_id
            .lock()
            .expect("dev transport next PIT id lock poisoned") = 17;

        for (request_id, shard_id, expected_class, expected_message) in [
            (
                299,
                os_transport::action::OpenSearchShardIdWire {
                    index_name: "logs-reader-missing".to_string(),
                    index_uuid: "uuid-reader-missing".to_string(),
                    shard_id: 0,
                },
                "org.opensearch.index.IndexNotFoundException",
                "no such index [logs-reader-missing]",
            ),
            (
                300,
                os_transport::action::OpenSearchShardIdWire {
                    index_name: "logs-reader-manifest".to_string(),
                    index_uuid: "uuid-reader-manifest".to_string(),
                    shard_id: 2,
                },
                "org.opensearch.index.shard.ShardNotFoundException",
                "no such shard",
            ),
            (
                301,
                os_transport::action::OpenSearchShardIdWire {
                    index_name: "logs-reader-closed".to_string(),
                    index_uuid: "uuid-reader-closed".to_string(),
                    shard_id: 0,
                },
                "org.opensearch.index.IndexNotFoundException",
                "no such index [logs-reader-closed]",
            ),
        ] {
            let request = os_transport::action::OpenSearchCreateReaderContextRequestWire::new(
                shard_id,
                os_transport::action::TimeValueWire::minutes(1),
            );
            let frame =
                os_transport::action::build_opensearch_create_reader_context_request_message(
                    request_id,
                    OPENSEARCH_3_7_0_TRANSPORT,
                    &request,
                )
                .unwrap();
            assert!(!create_reader_context_request_supports_local_subset(
                &frame[6..]
            ));

            let response = build_local_create_reader_context_response(
                request_id,
                OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
                &frame[6..],
            );
            let mut frame = BytesMut::from(&response[..]);
            let os_transport::frame::DecodedFrame::Message(message) =
                os_transport::frame::decode_frame(&mut frame)
                    .unwrap()
                    .unwrap()
            else {
                panic!("expected create-reader-context error response frame");
            };
            assert_eq!(message.request_id, request_id);
            assert!(message.status.is_error());
            let error = os_transport::error::TransportError::read(message.body.freeze())
                .unwrap()
                .unwrap();
            assert_eq!(error.class_name, expected_class);
            assert_eq!(error.message.as_deref(), Some(expected_message));
        }

        assert_eq!(
            *bindings
                .next_id
                .lock()
                .expect("dev transport next PIT id lock poisoned"),
            17
        );
        bindings
            .reader_contexts
            .lock()
            .expect("dev transport reader contexts lock poisoned")
            .clear();
    }

