    #[test]
    fn retention_lease_transport_routes_report_missing_shard_or_index_like_opensearch() {
        let missing_shard_id = os_transport::action::OpenSearchShardIdWire {
            index_name: "missing-retention-index".to_string(),
            index_uuid: "uuid-missing-retention-index".to_string(),
            shard_id: 0,
        };
        let add_request = os_transport::action::OpenSearchAddRetentionLeaseRequestWire {
            index: Some(missing_shard_id.index_name.clone()),
            shard_id: missing_shard_id.clone(),
            ..os_transport::action::OpenSearchAddRetentionLeaseRequestWire::default()
        };
        let add_frame = os_transport::action::build_opensearch_add_retention_lease_request_message(
            105,
            OPENSEARCH_3_7_0_TRANSPORT,
            &add_request,
        )
        .unwrap();
        let add_body = add_frame[6..].to_vec();
        assert!(retention_lease_request_has_missing_shard_or_index(
            Some("indices:admin/seq_no/add_retention_lease"),
            &add_body
        ));

        let response = build_retention_lease_missing_shard_or_index_error_response(
            105,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            Some("indices:admin/seq_no/add_retention_lease"),
            &add_body,
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected add retention lease index-not-found response message");
        };
        assert_eq!(message.request_id, 105);
        assert!(message.status.is_error());
        let error = os_transport::error::TransportError::read(message.body.freeze())
            .unwrap()
            .unwrap();
        assert_eq!(
            error.class_name,
            "org.opensearch.index.IndexNotFoundException"
        );
        assert_eq!(
            error.message.as_deref(),
            Some("no such index [missing-retention-index]")
        );

        dev_transport_pit_bindings()
            .created_indices
            .lock()
            .expect("created indices lock poisoned")
            .insert("retention-existing-index".to_string());
        let missing_shard = os_transport::action::OpenSearchShardIdWire {
            index_name: "retention-existing-index".to_string(),
            index_uuid: "_na_".to_string(),
            shard_id: 3,
        };
        let renew_request = os_transport::action::OpenSearchRenewRetentionLeaseRequestWire {
            index: Some(missing_shard.index_name.clone()),
            shard_id: missing_shard.clone(),
            ..os_transport::action::OpenSearchRenewRetentionLeaseRequestWire::default()
        };
        let renew_frame =
            os_transport::action::build_opensearch_renew_retention_lease_request_message(
                106,
                OPENSEARCH_3_7_0_TRANSPORT,
                &renew_request,
            )
            .unwrap();
        let renew_body = renew_frame[6..].to_vec();
        assert!(retention_lease_request_has_missing_shard_or_index(
            Some("indices:admin/seq_no/renew_retention_lease"),
            &renew_body
        ));

        let response = build_retention_lease_missing_shard_or_index_error_response(
            106,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            Some("indices:admin/seq_no/renew_retention_lease"),
            &renew_body,
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected renew retention lease shard-not-found response message");
        };
        assert_eq!(message.request_id, 106);
        assert!(message.status.is_error());
        let error = os_transport::error::TransportError::read(message.body.freeze())
            .unwrap()
            .unwrap();
        assert_eq!(
            error.class_name,
            "org.opensearch.index.shard.ShardNotFoundException"
        );
        assert_eq!(error.message.as_deref(), Some("no such shard"));

        let remove_request = os_transport::action::OpenSearchRemoveRetentionLeaseRequestWire {
            index: Some(missing_shard_id.index_name.clone()),
            shard_id: missing_shard_id,
            ..os_transport::action::OpenSearchRemoveRetentionLeaseRequestWire::default()
        };
        let remove_frame =
            os_transport::action::build_opensearch_remove_retention_lease_request_message(
                107,
                OPENSEARCH_3_7_0_TRANSPORT,
                &remove_request,
            )
            .unwrap();
        assert!(retention_lease_request_has_missing_shard_or_index(
            Some("indices:admin/seq_no/remove_retention_lease"),
            &remove_frame[6..]
        ));

        let accepted_request = os_transport::action::OpenSearchRenewRetentionLeaseRequestWire {
            index: Some("retention-existing-index".to_string()),
            shard_id: os_transport::action::OpenSearchShardIdWire {
                index_name: "retention-existing-index".to_string(),
                index_uuid: "_na_".to_string(),
                shard_id: 0,
            },
            ..os_transport::action::OpenSearchRenewRetentionLeaseRequestWire::default()
        };
        let accepted_frame =
            os_transport::action::build_opensearch_renew_retention_lease_request_message(
                108,
                OPENSEARCH_3_7_0_TRANSPORT,
                &accepted_request,
            )
            .unwrap();
        assert!(!retention_lease_request_has_missing_shard_or_index(
            Some("indices:admin/seq_no/renew_retention_lease"),
            &accepted_frame[6..]
        ));
    }

    #[test]
    fn term_vectors_transport_route_reports_missing_index_like_opensearch() {
        let request = os_transport::action::OpenSearchTermVectorsRequestWire::new(
            "missing-tv-index".to_string(),
            "doc-1".to_string(),
        );
        let request_frame = os_transport::action::build_opensearch_term_vectors_request_message(
            109,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        let request_body = request_frame[6..].to_vec();
        assert!(term_vectors_request_supports_missing_index_subset(
            &request_body
        ));

        let response = build_term_vectors_index_not_found_error_response(
            109,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &request_body,
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected term vectors index-not-found response message");
        };
        assert_eq!(message.request_id, 109);
        assert!(message.status.is_error());
        let error = os_transport::error::TransportError::read(message.body.freeze())
            .unwrap()
            .unwrap();
        assert_eq!(
            error.class_name,
            "org.opensearch.index.IndexNotFoundException"
        );
        assert_eq!(
            error.message.as_deref(),
            Some("no such index [missing-tv-index]")
        );

        let wildcard_request = os_transport::action::OpenSearchTermVectorsRequestWire::new(
            "missing-*".to_string(),
            "doc-1".to_string(),
        );
        let wildcard_frame = os_transport::action::build_opensearch_term_vectors_request_message(
            110,
            OPENSEARCH_3_7_0_TRANSPORT,
            &wildcard_request,
        )
        .unwrap();
        assert!(!term_vectors_request_supports_missing_index_subset(
            &wildcard_frame[6..]
        ));

        let routed_request = os_transport::action::OpenSearchTermVectorsRequestWire {
            routing: Some("tenant-a".to_string()),
            ..request
        };
        let routed_frame = os_transport::action::build_opensearch_term_vectors_request_message(
            111,
            OPENSEARCH_3_7_0_TRANSPORT,
            &routed_request,
        )
        .unwrap();
        assert!(!term_vectors_request_supports_missing_index_subset(
            &routed_frame[6..]
        ));
    }

    #[test]
    fn cancel_tasks_transport_route_reports_in_flight_task_as_failed_node() {
        let transport_identity = DevTransportIdentity {
            cluster_name: "steelsearch-dev".to_string(),
            node_name: "steel-node".to_string(),
            node_id: "steel-node-id".to_string(),
            ephemeral_id: "steel-node-ephemeral".to_string(),
            transport_address: "127.0.0.1:9300".parse().unwrap(),
            attributes: Vec::new(),
            roles: vec!["cluster_manager".to_string(), "data".to_string()],
            seed_peer_identity: None,
            seed_peer_identities: Vec::new(),
            coordination_state: Arc::new(Mutex::new(DevTransportCoordinationState::default())),
            remote_transport_queue_gate: Arc::new(RemoteTransportQueueGate::new(1, 1000)),
            task_queue_state: Some(PersistedClusterManagerTaskQueueState {
                in_flight: vec![ClusterManagerTaskRecord {
                    task_id: 32,
                    task: os_node::ClusterManagerTask {
                        source: "remove-node [node-b]".to_string(),
                        kind: os_node::ClusterManagerTaskKind::RemoveNode {
                            node_id: "node-b".to_string(),
                        },
                    },
                    state: ClusterManagerTaskState::InFlight,
                    parent_task_id: None,
                    headers: BTreeMap::new(),
                    failure_reason: None,
                }],
                ..PersistedClusterManagerTaskQueueState::default()
            }),
        };
        let request = os_transport::action::CancelTasksRequestWire {
            task_id: os_transport::action::TaskIdWire {
                node_id: "steel-node-id".to_string(),
                id: Some(32),
            },
            ..os_transport::action::CancelTasksRequestWire::default()
        };
        let request_frame = os_transport::action::build_cancel_tasks_request_message(
            85,
            OPENSEARCH_3_7_0_TRANSPORT,
            &request,
        )
        .unwrap();
        let request_body = request_frame[6..].to_vec();
        let response = build_cancel_tasks_response_for_request(
            85,
            OPENSEARCH_3_7_0_TRANSPORT.id() as u32,
            &transport_identity,
            Some(&request_body),
        );
        let mut frame = BytesMut::from(&response[..]);
        let os_transport::frame::DecodedFrame::Message(message) =
            os_transport::frame::decode_frame(&mut frame)
                .unwrap()
                .unwrap()
        else {
            panic!("expected cancel tasks response message");
        };

        let response = os_transport::action::read_cancel_tasks_response_message(&message).unwrap();
        assert!(response.tasks.is_empty());
        assert_eq!(response.node_failures.len(), 1);
        let failure = &response.node_failures[0];
        assert_eq!(
            failure.cause.as_ref().unwrap().class_name,
            "java.lang.IllegalArgumentException"
        );
        assert_eq!(
            failure.cause.as_ref().unwrap().message.as_deref(),
            Some("task [steel-node-id:32] doesn't support cancellation")
        );
    }

